  FT["PH-H5760"] = {"id":"PH-H5760","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1992/ra_7272_1992.html","fetchedAt":"2026-10-06","articleCount":7,"structureMode":"ARTICLE","title":{"zh":"将三宝颜市三宝颜地区医院改设为三宝颜市医疗中心并为其拨款的法案","en":"An Act Converting the Zamboanga Regional Hospital in Zamboanga City Into Zamboanga City Medical Center, and Appropriating Funds Therefor","orig":"An Act Converting the Zamboanga Regional Hospital in Zamboanga City Into Zamboanga City Medical Center, and Appropriating Funds Therefor"},"level":"law","status":"active","topics":["health"],"docNumber":"Republic Act No. 7272","issuingBody":"Congress of the Philippines","promulgatedDate":"1992-03-24","completenessNote":"全文，共 7 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1992/ra_7272_1992.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H5760-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The existing Zamboanga Regional Hospital in Zamboanga City is hereby converted into and shall henceforth be known as the Zamboanga City Medical Center, hereinafter called the Medical Center."}},{"id":"PH-H5760-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The Medical Center shall serve as the principal hospital facility of Region IX. It shall have a minimum bed capacity of two hundred fifty (250)."}},{"id":"PH-H5760-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"The Medical Center shall be under the jurisdiction of the Department of Health which is hereby authorized to organize the management and administration thereof in accordance with existing laws, rules and regulations: Provided, however, That the present staff and personnel of the Zamboanga Regional Hospital shall be transferred to and absorbed by the Medical Center."}},{"id":"PH-H5760-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"The amount necessary to carry out the provisions of this Act shall be charged against the lump-sum appropriations authorized for the purpose under the current General Appropriations Act. Thereafter, such sums as may be necessary for the operation and maintenance of the hospital shall be included in the annual General Appropriations Act."}},{"id":"PH-H5760-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"All lands, buildings, unexpected appropriations, and other properties and assets, fixed and movable, belonging to the Zamboanga Regional Hospital are hereby transferred to the Zamboanga City Medical Center."}},{"id":"PH-H5760-A6","no":6,"noLabel":{"en":"Section 6."},"text":{"en":"The Secretary of the Department of Health is hereby directed to immediately implement this Act."}},{"id":"PH-H5760-A7","no":7,"noLabel":{"en":"Section 7."},"text":{"en":"This Act shall take effect upon its approval."}}],"pack":"ph-p82","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Converting the Zamboanga Regional Hospital in Zamboanga City Into Zamboanga City Medical Center, and Appropriating Funds Therefor","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
