  FT["PH-H5763"] = {"id":"PH-H5763","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1992/ra_7275_1992.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":"将黎刹省 Morong市镇 Morong 综合医院的名称变更为黎刹省立医院的法案","en":"An Act Changing the Name of the Morong General Hospital in the Municipality of Morong, Province of Rizal, to Rizal Provincial Hospital","orig":"An Act Changing the Name of the Morong General Hospital in the Municipality of Morong, Province of Rizal, to Rizal Provincial Hospital"},"level":"law","status":"active","topics":["health"],"docNumber":"Republic Act No. 7275","issuingBody":"Congress of the Philippines","promulgatedDate":"1992-03-24","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1992/ra_7275_1992.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H5763-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The name of the Morong General Hospital located in the Municipality of Morong, Province of Rizal, is hereby changed to Rizal Provincial Hospital."}},{"id":"PH-H5763-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect upon its approval."}}],"pack":"ph-p82","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Changing the Name of the Morong General Hospital in the Municipality of Morong, Province of Rizal, to Rizal Provincial Hospital","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H5764"] = {"id":"PH-H5764","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1992/ra_7276_1992.html","fetchedAt":"2026-10-06","articleCount":3,"structureMode":"ARTICLE","title":{"zh":"将东内格罗斯Guihulngan的Guihulngan区医院床位由50张增至75张并为此拨款的法案","en":"An Act Increasing the Bed Capacity of the Guihulngan District Hospital in Guihulngan, Negros Oriental, From Fifty (50) to Seventy-five (75) Beds, and Appropriating Funds Therefor","orig":"An Act Increasing the Bed Capacity of the Guihulngan District Hospital in Guihulngan, Negros Oriental, From Fifty (50) to Seventy-five (75) Beds, and Appropriating Funds Therefor"},"level":"law","status":"active","topics":["health"],"docNumber":"Republic Act No. 7276","issuingBody":"Congress of the Philippines","promulgatedDate":"1992-03-24","completenessNote":"全文，共 3 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1992/ra_7276_1992.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H5764-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The bed capacity of the Guihulngan District Hospital in Guihulngan, Negros Oriental, is hereby increased from fifty (50) to seventy-five (75) beds."}},{"id":"PH-H5764-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The amount necessary to carry out the provisions of this Act shall be included in the General Appropriations Act of the year following its enactment into law and thereafter."}},{"id":"PH-H5764-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"This Act shall take effect upon its approval."}}],"pack":"ph-p82","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Increasing the Bed Capacity of the Guihulngan District Hospital in Guihulngan, Negros Oriental, From Fifty (50) to Seventy-five (75) Beds, and Appropriating Funds Therefor","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H5765"] = {"id":"PH-H5765","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1992/ra_7277_1992.html","fetchedAt":"2026-10-06","articleCount":50,"structureMode":"ARTICLE","title":{"zh":"重整制度","en":"An Act Providing for the Rehabilitation, Self-development and Self-reliance of Disabled Persons and Their Integration Into the Mainstream of Society and for Other Purposes","orig":"An Act Providing for the Rehabilitation, Self-development and Self-reliance of Disabled Persons and Their Integration Into the Mainstream of Society and for Other Purposes"},"level":"law","status":"active","topics":["company"],"docNumber":"Republic Act No. 7277","issuingBody":"Congress of the Philippines","promulgatedDate":"1992-03-24","completenessNote":"全文，共 50 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1992/ra_7277_1992.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H5765-A1","no":1,"noLabel":{"en":"Section 1."},"chapter":{"zh":"CHAPTER 2 - Education"},"text":{"en":"Title . - This Act shall be known and cited as the \"Magna Carta for Disabled Persons\"."}},{"id":"PH-H5765-A2","no":2,"noLabel":{"en":"Section 2."},"chapter":{"zh":"CHAPTER 2 - Education"},"text":{"en":"Declaration of Policy . - The grant of the rights and privileges for disabled persons shall be guided by the following principles:\na. Disabled persons are part of Philippine society, thus the State shall give full support to the improvement of the total well-being of disabled persons and their integration into the mainstream of society. Toward this end, the State shall adopt policies ensuring the rehabilitation, self-development and self-reliance of disabled persons. It shall develop their skills and potentials to enable them to compete favorably for available opportunities.\nb. Disabled persons have the same rights as other people to take their proper place in society. They should be able to live freely and as independently as possible. This must be the concern of everyone - the family, community and all government and non government organizations. Disabled persons' rights must never be perceived as welfare services by the Government.\nc. The rehabilitation of the disabled persons shall be the concern of the Government in order to foster their capacity to attain a more meaningful, productive and satisfying life. To reach out to a greater number of disabled persons, the rehabilitation services and benefits shall be expanded beyond the traditional urban-based centers to community based programs, that will ensure full participation of different sectors as supported by national and local government agencies.\nd. The State also recognizes the role of the private sector in promoting the welfare of disabled persons and shall encourage partnership in programs that address their needs and concerns.\ne. To facilitate integration of disabled persons into the mainstream of society, the State shall advocate for and encourage respect for disabled persons. The State shall exert all efforts to remove all social, cultural, economic, environmental and attitudinal barriers that are prejudicial to disabled persons."}},{"id":"PH-H5765-A3","no":3,"noLabel":{"en":"Section 3."},"chapter":{"zh":"CHAPTER 2 - Education"},"text":{"en":"Coverage . - This Act shall cover all disabled persons and, to the extent herein provided, departments, offices and agencies of the National Government or non-government organizations involved in the attainment of the objectives of this Act."}},{"id":"PH-H5765-A4","no":4,"noLabel":{"en":"Section 4."},"chapter":{"zh":"CHAPTER 2 - Education"},"text":{"en":"Definition of Terms. - For purposes of this Act, these terms are defined as follows:\na. Disabled Persons are those suffering from restriction or different abilities, as a result of a mental, physical or sensory impairment, to perform an activity in the manner or within the range considered normal for a human being;\nb. Impairment is any loss, diminution or aberration of psychological, physiological, or anatomical structure or function;\nc. Disability shall mean 1) a physical or mental impairment that substantially limits one or more psychological, physiological or anatomical function of an individual or activities of such individual; 2) a record of such an impairment; or 3) being regarded as having such an impairment;\nd. Handicap refers to a disadvantage for a given individual, resulting from an impairment or a disability, that limits or prevents the function or activity, that is considered normal given the age and sex of the individual;\ne. Rehabilitation is an integrated approach to physical, social, cultural, spiritual, educational and vocational measures that create conditions for the individual to attain the highest possible level of functional ability;\nf. Social Barriers refer to the characteristics of institutions, whether legal, economic cultural, recreational or other, any human group, community, or society which limit the fullest possible participation of disabled persons in the life of the group. Social barriers include negative attitudes which tend to single out and exclude disabled persons and which distort roles and inter-personal relationships;\ng. Auxiliary Aids and Services include:\n1. qualified interpreters or other effective methods of delivering materials to individuals with hearing impairments;\n2. qualified readers, taped tests, or other effective methods of delivering materials to individuals with visual impairments;\n3. acquisition or modification of equipment or devices, and\n4. other similar services and actions or all types of aids and services that facilitate the learning process of people with mental disability.\nh. Reasonable Accommodation include 1) improvement of existing facilities used by employees in order to render these readily accessible to and usable by disabled persons; and 2) modifications of work schedules, reassignment to a vacant position, acquisition or modification of equipment or devices, appropriate adjustments or modifications of examinations, training materials or company policies, rules and regulations, the provision of auxiliary aids and services, and other similar accommodations for disabled persons;\ni. Sheltered Employment refers to the provision of productive work for disabled persons through workshops providing special facilities, income-producing projects or homework schemes with a to giving them the opportunity to earn a living thus enabling them to acquire a working capacity required in open industry;\nj. Auxiliary Social Services are the supportive activities in the delivery of social services to the marginalized sectors of society;\nk. Marginalized Disabled Persons refer to disabled persons who lack access to rehabilitative services and opportunities to be able to participate fully in socioeconomic activities and who have no means of livelihood or whose incomes fall below the poverty threshold;\nl. Qualified Individual with a Disability shall mean an individual with a disability who, with or without reasonable accommodations, can perform the essential functions of the employment position that such individual holds or desires. However, consideration shall be given to the employer's judgment as to what functions of a job are essential, and if an employer has prepared a written description before advertising or interviewing applicants for the job, this description shall be considered evidence of the essential functions of the job;\nm. Readily Achievable means a goal can be easily attained and carried out without much difficulty or expense. In determining whether an action is readily achievable, factors to be considered include;\n1. the nature and cost of the action;\n2. the overall financial resources of the facility or facilities involved in the action; the number of persons employed at such facility; the effect on expenses and resources, or the impact otherwise of such action upon the operation of the facility;\n3. the overall financial resources of the covered entity with respect to the number of its employees; the number, type and location of its facilities; and\n4. the type of operation or operations of the covered entity, including the composition, structure and functions of the work force of such entity; the geographic separateness, administrative or fiscal relationship of the facility or facilities in question to the covered entity.\nn. Public Transportation means transportation by air, land and sea that provides the public with general or special service on a regular and continuing basis;\no. Covered Entity means an employer, employment agency, labor organization or joint labor-management committee; and\np. Commerce shall be taken to mean as travel, trade, traffic, commerce, transportation, or communication among the provinces or between any foreign country or any territory or possession and any province.\nTITLE TWO - RIGHTS AND PRIVILEGES OF DISABLED PERSONS CHAPTER 1 - Employment"}},{"id":"PH-H5765-A5","no":5,"noLabel":{"en":"Section 5."},"chapter":{"zh":"CHAPTER 2 - Education"},"text":{"en":"Equal Opportunity for Employment. - No disabled person shall be denied access to opportunities for suitable employment. A qualified disabled employee shall be subject to the same terms and conditions of employment and the same compensation, privileges, benefits, fringe benefits, incentives or allowances as a qualified able bodied person.\nFive percent (5%) of all casual, emergency and contractual positions in the Departments of Social Welfare and Development; Health; Education, Culture and Sports; and other government agencies, offices or corporations engaged in social development shall be reserved for disabled persons."}},{"id":"PH-H5765-A6","no":6,"noLabel":{"en":"Section 6."},"chapter":{"zh":"CHAPTER 2 - Education"},"text":{"en":"Sheltered Employment. - If suitable employment for disabled persons cannot be found through open employment as provided in the immediately preceding Section, the State shall endeavor to provide it by means of sheltered employment. In the placement of disabled persons in sheltered employment, it shall accord due regard to the individual qualities, vocational goals and inclinations to ensure a good working atmosphere and efficient production."}},{"id":"PH-H5765-A7","no":7,"noLabel":{"en":"Section 7."},"chapter":{"zh":"CHAPTER 2 - Education"},"text":{"en":"Apprenticeship. - Subject to the provisions of the Labor Code as amended, disabled persons shall be eligible as apprentices or learners: Provided, That their handicap is not much as to effectively impede the performance of job operations in the particular occupation for which they are hired: Provided, further, That after the lapse of the period of apprenticeship, if found satisfactory in the job performance, they shall be eligible for employment."}},{"id":"PH-H5765-A8","no":8,"noLabel":{"en":"Section 8."},"chapter":{"zh":"CHAPTER 2 - Education"},"text":{"en":"Incentives for Employers. -\na. To encourage the active participation of the private sector in promoting the welfare of disabled persons and to ensure gainful employment for qualified disabled persons, adequate incentives shall be provided to private entities which employ disabled persons.\nb. Private entities that employ disabled persons who meet the required skills or qualifications, either as regular employee, apprentice or learner, shall be entitled to an additional deduction, from their gross income, equivalent to twenty-five percent (25%) of the total amount paid as salaries and wages to disabled persons: Provided, however, That such entities present proof as certified by the Department of Labor and Employment that disabled persons are under their employ: Provided, further, That the disabled employee is accredited with the Department of Labor and Employment and the Department of Health as to his disability, skills and qualifications.\nc. Private entities that improve or modify their physical facilities in order to provide reasonable accommodation for disabled persons shall also be entitled to an additional deduction from their net taxable income, equivalent to fifty percent (50%) of the direct costs of the improvements or modifications. This Section, however, does not apply to improvements or modifications of facilities required under Batas Pambansa Bilang 344."}},{"id":"PH-H5765-A9","no":9,"noLabel":{"en":"Section 9."},"chapter":{"zh":"CHAPTER 2 - Education"},"text":{"en":"Vocational Rehabilitation. - Consistent with the principle of equal opportunity for disabled workers and workers in general, the State shall take appropriate vocational rehabilitation measures that shall serve to develop the skills and potentials of disabled persons and enable them to compete favorably for available productive and remunerative employment opportunities in the labor market.\nThe State shall also take measures to ensure the provision of vocational rehabilitation and livelihood services for disabled persons in the rural areas. In addition, it shall promote cooperation and coordination between the government and nongovernmental organizations and other private entities engaged in vocational rehabilitation activities.\nThe Department of Social Welfare and Development shall design and implement training programs that will provide disabled persons with vocational skills to enable them to engage in livelihood activities or obtain gainful employment. The Department of Labor and Employment shall likewise design and conduct training programs geared towards providing disabled persons with skills for livelihood."}},{"id":"PH-H5765-A10","no":10,"noLabel":{"en":"Section 10."},"chapter":{"zh":"CHAPTER 2 - Education"},"text":{"en":"Vocational Guidance and Counseling. - The Department of Social Welfare and Development, shall implement measures providing and evaluating vocational guidance and counseling to enable disabled persons to secure, retain and advance in employment. It shall ensure the availability and training of counselors and other suitably qualified staff responsible for the vocational guidance and counseling of disabled persons."}},{"id":"PH-H5765-A11","no":11,"noLabel":{"en":"Section 11."},"chapter":{"zh":"CHAPTER 2 - Education"},"text":{"en":"Implementing Rules and Regulations . - The Department of Labor and Employment shall in coordination with the Department of Social Welfare and Development (DSWD) and National Council for the Welfare of the Disabled Persons (NCWDP) shall promulgate the rules and regulations necessary to implement the provisions under this Chapter.\nCHAPTER 2 - Education"}},{"id":"PH-H5765-A12","no":12,"noLabel":{"en":"Section 12."},"chapter":{"zh":"CHAPTER 2 - Education"},"text":{"en":"Access to Quality Education. - The State shall ensure that disabled persons are provided with adequate access to quality education and ample opportunities to develop their skills. It shall take appropriate steps to make such education accessible to all disabled persons. It shall be unlawful for any learning institution to deny a disabled person admission to any course it offers by reason of handicap or disability.\nThe State shall take into consideration the special requirements of disabled persons in the formulation of educational policies and programs. It shall encourage learning institutions to take into account the special needs of disabled persons with respect to the use of school facilities, class schedules, physical education requirements, and other pertinent consideration.\nThe State shall also promote the provision by learning institutions, especially higher learning institutions, of auxiliary services that will facilitate the learning process for disabled persons."}},{"id":"PH-H5765-A13","no":13,"noLabel":{"en":"Section 13."},"chapter":{"zh":"CHAPTER 2 - Education"},"text":{"en":"Assistance to Disabled Students. - The State shall provide financial assistance to economically marginalized but deserving disabled students pursuing post secondary or tertiary education. Such assistance may be in the form of scholarship grants, student loan programs, subsidies, and other incentives to qualified disabled students in both public and private schools. At least five percent (5%) of the allocation for the Private Education Student Financial Assistance Program created by virtue of R.A. 6725 shall be set aside for disabled students pursuing vocational or technical and degree courses."}},{"id":"PH-H5765-A14","no":14,"noLabel":{"en":"Section 14."},"chapter":{"zh":"CHAPTER 2 - Education"},"text":{"en":"Special Education. - The State shall establish maintain and support a complete, adequate and integrated system of special education for the visually impaired, hearing impaired, mentally retarded persons and other types of exceptional children in all regions of the country. Toward this end, the Department of Education, Culture and Sports shall establish, special education classes in public schools in cities, or municipalities. It shall also establish, where viable, Braille and Record Libraries in provinces, cities or municipalities.\nThe National Government shall allocate funds necessary for the effective implementation of the special education program nationwide. Local government units may likewise appropriate counterpart funds to supplement national funds."}},{"id":"PH-H5765-A15","no":15,"noLabel":{"en":"Section 15."},"chapter":{"zh":"CHAPTER 2 - Education"},"text":{"en":"Vocational or Technical and Other Training Programs. -The State shall provide disabled persons with training in civics, vocational efficiency, sports and physical fitness, and other skills. The Department of Education, Culture and Sports shall establish in at least one government-owned vocational and technical school in every province a special vocational and technical training program for disabled persons. It shall develop and implement sports and physical fitness programs specifically designed for disabled persons taking into consideration the nature of their handicap."}},{"id":"PH-H5765-A16","no":16,"noLabel":{"en":"Section 16."},"chapter":{"zh":"CHAPTER 2 - Education"},"text":{"en":"Non-Formal Education. - The State shall develop non-formal education programs intended for the total human development of disabled persons. It shall provide adequate resources for non-formal education programs and projects that cater to the special needs of disabled persons."}},{"id":"PH-H5765-A17","no":17,"noLabel":{"en":"Section 17."},"chapter":{"zh":"CHAPTER 3 - Health"},"text":{"en":"State Universities and Colleges. - If viable and needed, the State University or State College in each region or province shall be responsible for (a) the development of material appliances and technical aids for disabled persons; (b) the development of training materials for vocational rehabilitation and special education instructions; (c) the research on special problems, particularly of the visually-impaired, hearing-impaired, speech-impaired, and orthopedically-impaired students, mentally retarded, and multi-handicapped and others, and the elimination of social barriers and discrimination against disabled persons; and (d) inclusion of the Special Education for Disabled (SPED) course in the curriculum.\nThe National Government shall provide these state universities and colleges with the necessary special facilities for visually-impaired, hearing-impaired, speech-impaired, and orthopedically-impaired students. It shall likewise allocate the necessary funds in support of the above.\nCHAPTER 3 - Health"}},{"id":"PH-H5765-A18","no":18,"noLabel":{"en":"Section 18."},"chapter":{"zh":"CHAPTER 3 - Health"},"text":{"en":"National Health Program. - The Department of Health in coordination with the National Council for the Welfare of Disabled Persons, shall institute a national health program which shall aim to attain the following:\na. prevention of disability, whether occurring prenatally or post-natally;\nb. recognition and early diagnosis of disability; and\nc. early rehabilitation of the disabled."}},{"id":"PH-H5765-A19","no":19,"noLabel":{"en":"Section 19."},"chapter":{"zh":"CHAPTER 3 - Health"},"text":{"en":"Rehabilitation Centers. - The Department of Health shall establish medical rehabilitation centers in government provincial hospitals, and shall include in its annual appropriation the necessary funds for the operation of such centers.\nThe Department of Health shall formulate and implement a program to enable marginalized disabled persons to avail of free rehabilitation services in government hospitals."}},{"id":"PH-H5765-A20","no":20,"noLabel":{"en":"Section 20."},"chapter":{"zh":"CHAPTER 4 - Auxiliary Social Services"},"text":{"en":"Health Services. - The State shall protect and promote the right to health of disabled persons and shall adopt an integrated and comprehensive approach to their health development which shall make essential health services available to them at affordable cost.\nThe National Government shall provide an integrated health service for disabled persons which shall include, but not limited to, the following:\na. prevention of disability through immunization, nutrition, environmental protection and preservation, and genetic counseling; and early detection of disability and timely intervention to arrest disabling condition; and\nb. medical treatment and rehabilitation.\nThe Department of Health shall field medical personnel specializing in the treatment and rehabilitation of disabled persons to provincial hospitals and when viable to municipal health centers. It shall also train its field health personnel in the provision of medical attention to disabled persons. It shall further ensure that its field health units have the necessary capabilities to fit prosthetic and orthotic appliances on disabled persons.\nCHAPTER 4 - Auxiliary Social Services"}},{"id":"PH-H5765-A21","no":21,"noLabel":{"en":"Section 21."},"chapter":{"zh":"CHAPTER 5 - Telecommunications"},"text":{"en":"Auxiliary Social Services. - The State shall ensure that marginalized persons are provided with the necessary auxiliary services that will restore their social functioning and participation in community affairs. Toward this end, the Department of Social Welfare and Development shall develop and implement programs on auxiliary social services that respond to the needs of marginalized disabled persons. The components of such a program shall be as follows:\na. assistance in the acquisition of prosthetic devices and medical intervention of specialty services;\nb. provision of specialized training activities designed to improved functional limitations of disabled persons related to communication skills;\nc. development among disabled persons of a positive self-image through the provision of counseling, orientation and mobility and strengthening daily living capability;\nd. provision of family care services geared towards developing the capability of families to respond to the needs of the disabled members of the family;\ne. provision of substitute family care services and the facilities therefor for abandoned, neglected, abused and unattached disabled persons who need custodial care;\nf. provision of after care and follow-up services for the continued rehabilitation in a community-based setting of disabled persons who were released from residential care or rehabilitation centers; and\ng. provision of day care services for disabled children of pre-school age.\nCHAPTER 5 - Telecommunications"}},{"id":"PH-H5765-A22","no":22,"noLabel":{"en":"Section 22."},"chapter":{"zh":"CHAPTER 5 - Telecommunications"},"text":{"en":"Broadcast Media. - Television stations shall be encouraged to provide a sign-language inset or subtitles in at least one (1) newscast program a day and special programs covering events of national significance."}},{"id":"PH-H5765-A23","no":23,"noLabel":{"en":"Section 23."},"chapter":{"zh":"CHAPTER 5 - Telecommunications"},"text":{"en":"Telephone Services. - All telephone companies shall be encouraged to install special telephone devices or units for the hearing-impaired and ensure that they are commercially available to enable them to communicate through the telephone system."}},{"id":"PH-H5765-A24","no":24,"noLabel":{"en":"Section 24."},"chapter":{"zh":"CHAPTER 6 - Accessibility"},"text":{"en":"Free Postal Charges for the Disabled. - Postal charges shall be free on the following:\na. articles and literatures like books and periodicals, orthopedic and other devices, and teaching aids for the use of the disabled sent by mail within the Philippines and abroad; and\nb. aids and orthopedic devices for the disabled sent abroad by mail for repair:\nProvided, That the aforesaid items are for personal purposes only: Provided, further, That the disabled person is a marginalized disabled as certified by the Social Welfare and Development Office of the local government unit concerned or the Department of Social Welfare and Development.\nCHAPTER 6 - Accessibility"}},{"id":"PH-H5765-A25","no":25,"noLabel":{"en":"Section 25."},"chapter":{"zh":"CHAPTER 6 - Accessibility"},"text":{"en":"Barrier-Free Environment. - The State shall ensure the attainment of a barrier-free environment that will enable disabled persons to have access in public and private buildings and establishments and such other places mentioned in Batas Pambansa Bilang 344, otherwise known as the \"Accessibility Law.\"\nThe national and local governments shall allocate funds for the provision of architectural facilities or structural features for disabled persons in government buildings and facilities."}},{"id":"PH-H5765-A26","no":26,"noLabel":{"en":"Section 26."},"chapter":{"zh":"CHAPTER 6 - Accessibility"},"text":{"en":"Mobility. - The State shall promote the mobility of disabled persons. Disabled persons shall be allowed to drive motor vehicles, subject to the rules and regulations issued by the Land Transportation Office pertinent to the nature of their disability and the appropriate adaptations or modifications made on such vehicles."}},{"id":"PH-H5765-A27","no":27,"noLabel":{"en":"Section 27."},"chapter":{"zh":"CHAPTER 6 - Accessibility"},"text":{"en":"Access to Public Transport Facilities. - The Department of Social Welfare and Development shall develop a program to assist marginalized disabled persons gain access in the use of public transport facilities. Such assistance may be in the form of subsidized transportation fare.\nThe said department shall also allocate such funds as may be necessary for the effective implementation of the public transport program for the disabled persons.\nThe \"Accessibility Law\", as amended, shall be made suppletory to this Act."}},{"id":"PH-H5765-A28","no":28,"noLabel":{"en":"Section 28."},"chapter":{"zh":"CHAPTER 7 - Political and Civil Rights"},"text":{"en":"Implementing Rules and Regulations . - The Department of Transportation and Communications shall formulate the rules and regulations necessary to implement the provisions of this Chapter.\nCHAPTER 7 - Political and Civil Rights"}},{"id":"PH-H5765-A29","no":29,"noLabel":{"en":"Section 29."},"chapter":{"zh":"CHAPTER 7 - Political and Civil Rights"},"text":{"en":"System of Voting. - Disabled persons shall be allowed to be assisted by a person of his choice in voting in the national or local elections. The person thus chosen shall prepare the ballot for the disabled voter inside the voting booth. The person assisting shall bind himself in a formal document under oath to fill out the ballot strictly in accordance with the instructions of the voter and not to reveal the contents of the ballot prepared by him. Violation of this provision shall constitute an election offense.\nPolling places should be made accessible to disabled persons during national or local elections."}},{"id":"PH-H5765-A30","no":30,"noLabel":{"en":"Section 30."},"chapter":{"zh":"CHAPTER 7 - Political and Civil Rights"},"text":{"en":"Right to Assemble. - Consistent with the provisions of the Constitution, the State shall recognize the right of disabled persons to participate in processions, rallies, parades, demonstrations, public meetings, and assemblages or other forms of mass or concerted action held in public."}},{"id":"PH-H5765-A31","no":31,"noLabel":{"en":"Section 31."},"chapter":{"zh":"CHAPTER 7 - Political and Civil Rights"},"text":{"en":"Right to Organize. - The State recognizes the right of disabled persons to form organizations or associations that promote their welfare and advance or safeguard their interests. The National Government, through its agencies, instrumentalities and subdivisions, shall assist disabled persons in establishing self-help organizations by providing them with the necessary technical and financial assistance.\nConcerned government agencies and offices shall establish close linkages with organizations of disabled persons in order to respond expeditiously to the needs of disabled persons. National line agencies and local government units shall assist disabled persons in setting up specific projects that will be managed like business propositions.\nTo ensure the active participation of disabled persons in the social and economic development of the country, their organizations shall be encouraged to participate in the planning, organization and management of government programs and projects for disabled persons.\nOrganizations of disabled persons shall participate in the identification and preparation of programs that shall serve to develop employment opportunities for the disabled persons.\nTITLE THREE - PROHIBITION ON DISCRIMINATION AGAINST DISABLED PERSONS CHAPTER 1 - Discrimination on Employment"}},{"id":"PH-H5765-A32","no":32,"noLabel":{"en":"Section 32."},"chapter":{"zh":"CHAPTER 7 - Political and Civil Rights"},"text":{"en":"Discrimination on Employment. - No entity, whether public or private, shall discriminate against a qualified disabled person by reason of disability in regard to job application procedures, the hiring, promotion, or discharge of employees, employee compensation, job training, and other terms, conditions, and privileges of employment.\nThe following constitute acts of discrimination:\na. Limiting, segregating or classifying a disabled job applicant in such a manner that adversely affects his work opportunities;\nb. Using qualification standards, employment test or other selection criteria that screen out or tend to screen out a disabled person unless such standards, test or other selection criteria are shown to be job-related for the position in question and are consistent with business necessity;\nc. Utilizing standards, criteria, or methods of administration that:\n1. have the effect of discrimination on the basis of disability; or\n2. perpetuate the discriminations of others who are subject to common administrative control.\nd. Providing less compensation, such as salary, wage or other forms of remuneration and fringe benefits, to a qualified disabled employee, by reason of his disability, than the amount to which a non-disabled person performing the same work is entitled;\ne. Favoring a non-disabled employee over a qualified disabled employee with respect to promotion, training opportunities, study and scholarship grants, solely on account of the latter's disability;\nf. Re-assigning or transferring a disabled employee to a job or position he cannot perform by reason of his disability;\ng. Dismissing or terminating the services of a disabled employee by reason of his disability unless the employer can prove that he impairs the satisfactory performance of the work involved to the prejudice of the business entity; Provided, however, That the employer first sought to provide reasonable accommodations for disabled persons;\nh. Failing to select or administer in the most effective manner employment test which accurately reflect the skills, aptitude or other factor of the disabled applicant or employee that such test purports to measure, rather than the impaired sensory, manual or speaking skills of such applicant or employee, if any; and\ni. Excluding disabled persons from membership in labor unions or similar organizations."}},{"id":"PH-H5765-A33","no":33,"noLabel":{"en":"Section 33."},"chapter":{"zh":"CHAPTER 2 - Discrimination on Transportation"},"text":{"en":"Employment Entrance Examination. - Upon an offer of employment, a disabled applicant may be subjected to medical examination, on the following occasions:\na. all entering employees are subjected to such an examination regardless of disability;\nb. information obtained during the medical condition or history of the applicant is collected and maintained on separate forms and in separate medical files and is treated as a confidential medical record: Provided,however That:\n1. supervisors and managers may be informed regarding necessary restrictions on the work or duties of the employees and necessary accommodations;\n2. first aid and safety personnel may be informed, when appropriate, if the disability might require emergency treatment;\n3. government officials investigating compliance with this Act shall be provided relevant information on request; and\n4. the results of such examination are used only in accordance with this Act.\nCHAPTER 2 - Discrimination on Transportation"}},{"id":"PH-H5765-A34","no":34,"noLabel":{"en":"Section 34."},"chapter":{"zh":"CHAPTER 3 - Discrimination on the Use of Public Accommodations and Services"},"text":{"en":"Public Transportation. - It shall be considered discrimination for the franchisees or operators and personnel of sea, land, and air transportation facilities to charge higher fare or to refuse to convey a passenger, his orthopedic devices, personal effects, and merchandise by reason of his disability.\nCHAPTER 3 - Discrimination on the Use of Public Accommodations and Services"}},{"id":"PH-H5765-A35","no":35,"noLabel":{"en":"Section 35."},"chapter":{"zh":"CHAPTER 3 - Discrimination on the Use of Public Accommodations and Services"},"text":{"en":"Public Accommodations and Services. - For purposes of this Chapter, public accommodations and services shall include the following:\na. an inn, hotel, motel, or other place of lodging, except for an establishment located within a building that contains not more than five (5) rooms for rent or hire and that is actually occupied by the proprietor of such establishment as the residence of such proprietor;\nb. a restaurant, bar, or other establishment serving food or drink;\nc. a motion picture, theater, concert hall, stadium, or other place of exhibition or entertainment;\nd. an auditorium, convention center, lecture hall, or other place of public gathering;\ne. a bakery, grocery store, hardware store, shopping center, or other sales or rental establishment;\nf. a bank, barber shop, beauty shop, travel service, funeral parlor, gas station, office of a lawyer, pharmacy, insurance office, professional office of a health care provider, hospital or other service establishment;\ng. a terminal, depot, or other station used for specified public transportation;\nh. a museum, gallery, library or other place of public display or collection;\ni. a park, zoo, amusement park, or other place of recreation;\nj. a nursery, elementary, secondary, undergraduate, or post-graduate private school, or other place of education;\nk. a gymnasium, health spa, bowling alley, golf course; or\nl. other place of exercise or recreation."}},{"id":"PH-H5765-A36","no":36,"noLabel":{"en":"Section 36."},"chapter":{"zh":"CHAPTER 3 - Discrimination on the Use of Public Accommodations and Services"},"text":{"en":"Discrimination on the Use of Public Accommodations. -\na. No disabled person shall be discriminated on the basis of disability in the full and equal enjoyment of the goods, services facilities, privileges, advantages or accommodations of any place of public accommodation by any person who owns, leases, or operates a place of public accommodation. The following constitute acts of discrimination:\n1. denying a disabled person, directly or through contractual, licensing, or other arrangement, the opportunity to participate in or benefit from the goods, services, facilities, privileges, advantages, or accommodations of an entity by reason of his disability;\n2. affording a disabled person, on the basis of his disability, directly or through contractual, licensing, or other arrangement, with the opportunity to participate in or benefit from a good, service, facility, privilege, advantage, or accommodation that is not equal to that afforded to other able-bodied persons; and\n3. providing a disabled person, on the basis of his disability, directly or through contractual, licensing, or other arrangement, with a good, service, facility, advantage, privilege, or accommodation that is different or separate form that provided to other able-bodied persons unless such action is necessary to provide the disabled person with a good, service, facility, advantage, privilege, or accommodation, or other opportunity that is as effective as that provided to others;\nFor purposes of this Section, the term \"individuals or class of individuals\" refers to the clients or customers of the covered public accommodation that enters into the contractual, licensing or other arrangement.\nb. Integrated Settings - Goods, services, facilities, privileges, advantages, and accommodations shall be afforded to an individual with a disability in the most integrated setting appropriate to the needs of the individual.\nc. Opportunity to Participate - Notwithstanding the existence of separate or different programs or activities provided in accordance with this Section, an individual with a disability shall not be denied the opportunity to participate in such programs or activities that are not separate or different.\nd. Association - It shall be discriminatory to exclude or otherwise deny equal goods, services, facilities, advantages, privileges, accommodations or other opportunities to an individual or entity because of the known disability of an individual with whom the individual or entity is known to have a relationship or association.\ne. Prohibitions - For purposes of this Section, the following shall be considered as discriminatory:\n1. the imposition or application of eligibility criteria that screen out or tend to screen out an individual with a disability or any class or individuals with disabilities from fully and equally enjoying any goods, services, facilities, privileges, advantages, or accommodations unless such criteria can be shown to be necessary for the provision of the goods, services, facilities, privileges, or accommodations being offered;\n2. a failure to make reasonable modifications in policies, practices, or procedures, when such modifications are necessary to afford such goods, services, facilities, privileges, advantages, or accommodations to individuals with disabilities, unless the entity can demonstrate that making such modifications would fundamentally alter the nature of the goods, facilities, services, privileges, advantages, or accommodations;\n3. failure to take such steps as may be necessary to ensure that no individual with a disability is excluded, denied services, segregated or otherwise treated differently than other individuals because of the absence of auxiliary aids and services, unless the entity can demonstrate that taking such steps would fundamentally alter the nature of the good, service, facility, privilege, advantage or accommodation being offered or would result in undue burden;\n4. a failure to remove architectural barriers, and communication barriers that are structural in nature, in existing facilities, where such removal is readily achievable; and\n5. where an entity can demonstrate that the removal of a barrier under clause (4) is not readily achievable, a failure to make such goods, services, facilities, privileges, advantages, or accommodations available through alternative methods if such methods are readily achievable."}},{"id":"PH-H5765-A37","no":37,"noLabel":{"en":"Section 37."},"chapter":{"zh":"CHAPTER 3 - Discrimination on the Use of Public Accommodations and Services"},"text":{"en":"Use of Government Recreational or Sports Centers Free of Charge. - Recreational or sports centers owned or operated by the Government shall be used, free of charge, by marginalized disabled persons during their social, sports or recreation activities."}},{"id":"PH-H5765-A38","no":38,"noLabel":{"en":"Section 38."},"chapter":{"zh":"CHAPTER 3 - Discrimination on the Use of Public Accommodations and Services"},"text":{"en":"Implementing Rules and Regulations . - The Department of Public Works and Highways shall formulate the rules and regulations necessary to implement the provisions of this Chapter.\nTITLE FOUR - FINAL PROVISIONS"}},{"id":"PH-H5765-A39","no":39,"noLabel":{"en":"Section 39."},"chapter":{"zh":"CHAPTER 3 - Discrimination on the Use of Public Accommodations and Services"},"text":{"en":"Housing Program. - The National Government shall take into consideration in its national shelter program the special housing requirements of disabled persons."}},{"id":"PH-H5765-A40","no":40,"noLabel":{"en":"Section 40."},"chapter":{"zh":"CHAPTER 3 - Discrimination on the Use of Public Accommodations and Services"},"text":{"en":"Role of National Agencies and Local Government Units. - Local government units shall promote the establishment of organizations of disabled persons in their respective territorial jurisdictions. National agencies and local government units may enter into joint ventures with organizations or associations of disabled persons to explore livelihood opportunities and other undertakings that shall enhance the health, physical fitness and the economic and social well-being of disabled persons."}},{"id":"PH-H5765-A41","no":41,"noLabel":{"en":"Section 41."},"chapter":{"zh":"CHAPTER 3 - Discrimination on the Use of Public Accommodations and Services"},"text":{"en":"Support From Nongovernment Organizations. - Non government organizations or private volunteer organizations dedicated to the purpose of promoting and enhancing the welfare of disabled persons shall, as they, are hereby encouraged, become partners of the Government in the implementation of vocational rehabilitation measures and other related programs and projects. Accordingly, their participation in the implementation of said measures, programs and projects is to be extended all possible support by the Government.\nThe Government shall sponsor a volunteer service program which shall harness the involvement of private individuals in the provision of assistance to disabled persons."}},{"id":"PH-H5765-A42","no":42,"noLabel":{"en":"Section 42."},"chapter":{"zh":"CHAPTER 3 - Discrimination on the Use of Public Accommodations and Services"},"text":{"en":"Tax Incentives. -\na. Any donation, bequest, subsidy or financial aid which may be made to government agencies engaged in the rehabilitation of disabled persons and organizations of disabled persons shall be exempt from the donor's tax subject to the provisions of Section 94 of the National Internal Revenue Code (NIRC), as amended and shall be allowed as deductions from the donor's gross income for purposes of computing the taxable income subject to the provisions of Section 29 (h) of the Code.\nb. Donations from foreign countries shall be exempt from taxes and duties on importation subject to the provisions of Section 105 of the Tariff and Customs Code of the Philippines, as amended, Section 103 of the NIRC, as amended and other relevant laws and international agreements.\nc. Local manufacturing of technical aids and appliances used by disabled persons shall be considered as a preferred area of investment subject to the provisions of Executive Order No. 226 otherwise known as the \"Omnibus Investments Code of 1987\" and, as such, shall enjoy the rights, privileges and incentives as provided in said Code such as, but not limited, to the following:\n1. repatriation of investments;\n2. remittance of earnings;\n3. remittance of payments on foreign contracts;\n4. freedom from expropriations;\n5. freedom from requisition of investment;\n6. income tax holiday;\n7. additional deduction for labor expense;\n8. tax and duty exemption on imported capital equipment;\n9. tax credit on domestic capital equipment;\n10. exemption from contractor's tax;\n11. simplification of customs procedures;\n12. unrestricted use of consigned equipment;\n13. employment of foreign nationals;\n14. tax credit for taxes and duties on raw materials;\n15. access to bonded manufacturing/trading warehouse system;\n16. exemption from taxes and duties on imported spare parts; and\n17. exemption from wharfage dues and any export tax, duty, impost and fee."}},{"id":"PH-H5765-A43","no":43,"noLabel":{"en":"Section 43."},"chapter":{"zh":"CHAPTER 3 - Discrimination on the Use of Public Accommodations and Services"},"text":{"en":"Continuity Clause. - Should any department or agency tasked with the enforcement or formulation of rules and regulations and guidelines for implementation of any provision of this Act is abolished, merged with another department or agency or modified, such shall not affect the enforcement or formulation of rules, regulations and guidelines for implementation of this Act to the effect that -\na. In case of abolition, the department or agency established to replace the abolished department or agency shall take-over the functions under this Act of the abolished department or agency.\nb. In case the department or agency tasked with the enforcement or formulation of rules, regulations and guidelines for implementation of this Act is merged with another department or agency, the former shall continue the functions under this Act of the merged department or agency.\nc. In case of modification, the department or agency modified shall continue the functions under this Act of the department or agency that has undergone modification."}},{"id":"PH-H5765-A44","no":44,"noLabel":{"en":"Section 44."},"chapter":{"zh":"CHAPTER 3 - Discrimination on the Use of Public Accommodations and Services"},"text":{"en":"Enforcement by the Secretary of Justice. -\na. Denial of Right\n1. Duty to Investigate - the Secretary of Justice shall investigate alleged violations of this Act, and shall undertake periodic reviews of compliance of covered entities under this Act.\nb. Potential Violations - If the Secretary of Justice has reasonable cause to believe that -\n1. any person or group of persons is engaged in a pattern or practice of discrimination under this Act; or\n2. any person or group or persons has been discriminated against under this Act and such discrimination raises an issue of general public importance, the Secretary of Justice may commence a legal action in any appropriate court."}},{"id":"PH-H5765-A45","no":45,"noLabel":{"en":"Section 45."},"chapter":{"zh":"CHAPTER 3 - Discrimination on the Use of Public Accommodations and Services"},"text":{"en":"Authority of Court. - The court may grant any equitable relief that such court considers to be appropriate, including, to the extent required by this Act;\na. granting temporary, preliminary or permanent relief;\nb. providing an auxiliary aid or service, modification of policy, practice or procedure, or alternative method; and\nc. making facilities readily accessible to and usable by individuals with disabilities."}},{"id":"PH-H5765-A46","no":46,"noLabel":{"en":"Section 46."},"chapter":{"zh":"CHAPTER 3 - Discrimination on the Use of Public Accommodations and Services"},"text":{"en":"Penal Clause. -\na. Any person who violates any provision of this Act shall suffer the following penalties:\n1. for the first violation, a fine of not less than Fifty thousand pesos (P50,000.00) but not exceeding One hundred thousand pesos (P100,000.00) or imprisonment of not less than six (6) months but not more than two (2) years, or both at the discretion of the court; and 2) for any subsequent violation, a fine of not less than One hundred thousand pesos (P100,000.00) but not exceeding Two hundred thousand pesos (P200,000.00) or imprisonment for not less than two (2) years but not more than six (6) years, or both at the discretion of the court.\nb. Any person who abuses the privileges granted herein shall be punished with imprisonment of not less than six (6) months or a fine of not less than Five thousand pesos (P5,000.00) but not more than Fifty thousand pesos (P50,000.00), or both, at the discretion of the court.\nc. If the violator is a corporation, organization or any similar entity, the officials thereof directly involved shall be liable therefor.\nd. If the violator is an alien or a foreigner, he shall be deported immediately after service of sentence without further deportation proceedings."}},{"id":"PH-H5765-A47","no":47,"noLabel":{"en":"Section 47."},"chapter":{"zh":"CHAPTER 3 - Discrimination on the Use of Public Accommodations and Services"},"text":{"en":"Appropriations . - The amount necessary to carry out the provisions of this Act shall be included in the General Appropriations Act of the year following its enactment into law and thereafter."}},{"id":"PH-H5765-A48","no":48,"noLabel":{"en":"Section 48."},"chapter":{"zh":"CHAPTER 3 - Discrimination on the Use of Public Accommodations and Services"},"text":{"en":"Separability Clause . - Should any provision of this Act be found unconstitutional by a court of law, such provisions shall be severed from the remainder of the Act, and such action shall not affect the enforceability of the remaining provisions of this Act."}},{"id":"PH-H5765-A49","no":49,"noLabel":{"en":"Section 49."},"chapter":{"zh":"CHAPTER 3 - Discrimination on the Use of Public Accommodations and Services"},"text":{"en":"Repealing Clause . - All laws, presidential decrees, executive orders and rules and regulations inconsistent with the provisions of this Act are hereby repealed or modified accordingly."}},{"id":"PH-H5765-A50","no":50,"noLabel":{"en":"Section 50."},"chapter":{"zh":"CHAPTER 3 - Discrimination on the Use of Public Accommodations and Services"},"text":{"en":"Effectivity . - This Act shall take effect fifteen (15) days after its publication in any two (2) newspapers of general circulation."}}],"pack":"ph-p82"};
  FT["PH-H5766"] = {"id":"PH-H5766","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1992/ra_7278_1992.html","fetchedAt":"2026-10-06","articleCount":15,"structureMode":"ARTICLE","title":{"zh":"对第 111 号共和国法的修改","en":"An Act Amending Commonwealth Act No. 111, as Amended By Presidential Decree No. 460, Entitled \"An Act to Create a Public Corporation to Be Known as the Boy Scouts of the Philippines, and to Define Its Powers and Purposes,\" By Strengthening the Volunteer and Democratic Character of the Boy Scouts of the Philippines and for Other Purposes","orig":"An Act Amending Commonwealth Act No. 111, as Amended By Presidential Decree No. 460, Entitled \"An Act to Create a Public Corporation to Be Known as the Boy Scouts of the Philippines, and to Define Its Powers and Purposes,\" By Strengthening the Volunteer and Democratic Character of the Boy Scouts of the Philippines and for Other Purposes"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 7278","issuingBody":"Congress of the Philippines","promulgatedDate":"1992-03-24","completenessNote":"全文，共 15 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1992/ra_7278_1992.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。 源文条号不连续（自第 1 条起，止于第 11 条，缺 9）：经逐条比对原始页面，该处原文没有对应的 “Section N.” 抬头行，系来源页自身的编号跳跃或条文以“续段”形式并入前条，非抽取遗漏，故未擅自补号。 源文存在同号重出的条款（第 2、3、4、5、6 条）：该处官方页面确有两段均标同一 Section 号，本库照录其 `no` 值（不改动官方编号），条文 `id` 以 `_2`「_3」后缀保证唯一。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H5766-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Sections 2 and 3 of Commonwealth Act No. 111, as amended, is hereby amended to read as follows:\n\""}},{"id":"PH-H5766-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The said corporation shall have the powers of perpetual succession, to sue and be sued; to enter into contracts; to acquire, own, lease, convey and dispose of such real and personal estate, land grants, rights and choses in action as shall be necessary for corporate purposes, and to accept and receive funds, real and personal property by gift, devise, bequest or other means, to conduct fund-raising activities; to adopt and use a seal, and the same to alter and destroy; to have offices and conduct its business and affairs in Metropolitan Manila and in the regions, provinces, cities, municipalities, and barangays of the Philippines, to make and adopt bylaws, rules and regulations not inconsistent with this Act and the laws of the Philippines, and generally to do all such acts and things, including the establishment of regulations for the election of associates and successors, as may be necessary to carry into effect the provisions of this Act and promote the purposes of said corporation: Provided, That said corporation shall have no power to issue certificates of stock or to declare or pay dividends, its objectives and purposes being solely of benevolent character and not for pecuniary profit of its members.\n\""}},{"id":"PH-H5766-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"The purpose of this corporation shall be to promote through organization and cooperation with other agencies, the ability of boys to do useful things for themselves and others, to train them in scoutcraft, and to inculcate in them patriotism, civic consciousness and responsibility, courage, self-reliance, discipline and kindred virtues, and moral values, using the method which are in common use by boy scouts.\""}},{"id":"PH-H5766-A2-d2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"Section 4 of Commonwealth Act No. 111, as amended, is hereby repealed and in lieu thereof, Section 4 shall read as follows:\n\""},"dupIndex":2},{"id":"PH-H5766-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"The President of the Philippines shall be the Chief Scout of the Boy Scouts of the Philippines.\""}},{"id":"PH-H5766-A3-d2","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"Sections 5, 6, 7 and 8 of Commonwealth Act No. 111, as amended, are hereby amended to read as follows:\n\""},"dupIndex":2},{"id":"PH-H5766-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"The governing body of the said corporation shall consist of a National Executive Board, the members of which shall be Filipino citizens of good moral character. The Board shall be composed of the following:\n\"(a) One (1) charter member of the Boy Scouts of the Philippines who shall be elected by the members of the National Council at its meeting called for this purpose;\n\"(b) The regional chairmen of the scout regions who shall be elected by the representatives of all the local scout councils of the region during its meeting called for this purpose: Provided, That a candidate for regional chairman need not be the chairman of a local scout council;\n\"(c) The Secretary of Education, Culture and Sports;\n\"(d) The National President of the Girl Scouts of the Philippines;\n\"(e) One (1) senior scout, each from Luzon, Visayas and Mindanao areas, to be elected by the senior scout delegates of the local scout councils to the scout youth forums in their respective areas, in its meeting called for this purpose, to represent the boy scout membership;\n\"(f) Twelve (12) regular members to be elected by the members of the National Council in its meeting called for this purpose;\n\"(g) At least ten (10) but not more than fifteen (15) additional members from the private sector who shall be elected by the members of the National Executive Board referred to in the immediately preceding paragraphs (a), (b), (c), (d), (e) and (f) at the organizational meeting of the newly reconstituted National Executive Board which shall be held immediately after the meeting of the National Council wherein the twelve (12) regular members and the one (1) charter member were elected.\n\"Thereafter, the National Executive Board as herein fully constituted shall elect from among themselves the following officers of the corporation:\n\"(a) President;\n\"(b) Senior Vice-President;\n\"(c) One (1) Vice-President each from Luzon, Visayas and Mindanao areas; and \"(d) Such other officers as the Board may deem necessary.\n\"The numerical composition of the National Executive Board shall be provided for in the bylaws of the Boy Scouts of the Philippines: Provided, That said numerical composition shall be at least thirty (30) and not more than forty-five (45) for all elected, life and ex officio members.\n\"The term of office of the members of the National Executive Board shall be one (1) year, except for the regular members to be elected by the National Council whose term of office shall be three (3) years: Provided, That for the first twelve (12) regular members to be elected by the National Council, the term of office shall be as follows: the members garnering the first four (4) highest number of votes shall serve for a term of three (3) years; the members garnering the second four (4) highest number of votes shall serve for a term of two (2) years; and the members garnering the last four (4) number of votes shall serve for a term of one (1) year.\n\"Vacancies in the National Executive Board shall be filled by a majority vote of the remaining members and a member thus elected shall serve only for the unexpired term.\n\"The bylaws may prescribe the number of members of the National Executive Board necessary to constitute a quorum of the Board, which number shall not be less than the majority of the entire membership of the Board.\n\"The National Executive Board shall exercise the following powers and functions:\n\"(a) To make and to amend the bylaws subject to the ratification by a majority vote of the members present at a meeting of the National Council or at a special meeting called for this purpose;\n\"(b) To authorize and cause to be executed mortgages and liens upon the property of the corporation by a two-thirds (2/3) vote of the whole Board at a meeting called for this purpose;\n\"(c) To designate five (5) or more of their number to constitute an executive or governing committee, of which a majority shall constitute a quorum, through a resolution passed by a majority of the whole Board. Such Committee, to the extent provided in said resolution or in the bylaws of the corporation, shall have and exercise the powers of the National Executive Board in the management of the business affairs of the corporation, and may have the power to authorize the seal of the corporation to be affixed to all papers which may require it;\n\"(d) To create standing committees and appoint the chairmen and members thereof from among themselves by the affirmative vote of a majority of the whole Board. Such standing committees shall exercise such powers as may be authorized by the bylaws;\n\"(e) To dispose in any manner a part or the whole property of the corporation with the consent in writing and pursuant to an affirmative vote of two-thirds (2/3) of the members of the National Council; and \"(f) To hold regular meetings at least once every two (2) months at a time and place to be designated in the bylaws. Special meetings of the Board may be called upon such notice as may be prescribed in the bylaws.\n\""}},{"id":"PH-H5766-A6","no":6,"noLabel":{"en":"Section 6."},"text":{"en":"The National Council shall be composed of the following members:\n\"(a) The members of the National Executive Board;\n\"(b) The charter members;\n\"(c) The regional commissioners;\n\"(d) The chairmen and commissioners of all local scout councils; and \"(e) Other duly accredited delegates of local scout councils as may be provided in the bylaws.\n\"The qualifications, terms of office, and the manner of electing the abovementioned members of the National Council shall be prescribed in the bylaws of the corporation.\n\"The numerical composition of the National Council shall be provided for in the bylaws of the Boy Scouts of the Philippines: Provided, That all regions and all local councils shall be duly represented therein by at least two (2) duly accredited delegates, in addition to those who are members of the National Executive Board as provided for under Section 5 of this Act.\n\"The annual meeting of the National Council shall be held at such time and place as shall be prescribed in the bylaws, at which meeting the annual reports of the officers and the National Executive Board shall be presented and the election of members to the National Executive Board.\n\"Special meetings of the National Council may be called upon such notice as may be prescribed in the bylaws. One-third (1/3) of the members of the National Council shall constitute a quorum to do business at any annual or special meeting.\n\"The National Council and the National Executive Board shall have the power to hold their meetings and keep the seal, books, documents, and papers of the corporation within or without the Metropolitan Manila.\n\"The National President of the corporation shall preside over the meetings of the National Council.\n\"Each local scout council represented in the annual or special meeting of the National Council shall be entitled to four (4) votes plus one (1) vote for every ten thousand (10,000) of their scout membership. The members of the National Executive Board and the life members shall each be entitled to one (1) vote.\n\""}},{"id":"PH-H5766-A7","no":7,"noLabel":{"en":"Section 7."},"text":{"en":"The corporation created by this Act shall adopt and shall have the sole and exclusive right to use distinctive titles, emblems, descriptive or designing, marks, words and phrases, badges, uniforms and insignia for the Boy Scouts of the Philippines in carrying out its program in accordance with the purposes of this Act, and which shall be published in the Official Gazette or in any newspaper of general circulation in the Philippines.\n\""}},{"id":"PH-H5766-A8","no":8,"noLabel":{"en":"Section 8."},"text":{"en":"Any donation or contribution which from time to time may be made to the Boy Scouts of the Philippines by the Government or any of its subdivisions, branches, offices, agencies or instrumentalities or by a foreign government or by private, entities and individuals shall be expended by the National Executive Board in pursuance of this Act.\n\"The corporation shall be entitled to the following tax and duty privileges:\n\"(a) Exemption from income tax pursuant to Section 26(e), (g) and (h) of the National Internal Revenue Code, as amended;\n\"(b) Exemption from donor's tax pursuant to Section 94 (a) (3) of the National Internal Revenue Code, as amended;\n\"(c) Full deductibility of donations from the donor's gross income for purposes of computing taxable income; and \"(d) Tax and/or duty exemption of donations from foreign countries as provided under relevant laws such as, but not limited to, Section 105 of the Tariff and Customs Code of the Philippines, as amended, Section 103 of the National Internal Revenue Code, as amended.\n\"Any other provisions of law to the contrary notwithstanding, there shall be no discrimination in tax treatment of the Boy and Girl Scouts of the Philippines.\""}},{"id":"PH-H5766-A4-d2","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"Sections 10 and 11 of Commonwealth Act No. 111, as amended, are hereby amended to read as follows:\n\""},"dupIndex":2},{"id":"PH-H5766-A10","no":10,"noLabel":{"en":"Section 10."},"text":{"en":"From and after the passage of this Act, it shall be unlawful for any person within the jurisdiction of the Philippines to falsely and fraudulently call himself as, or represent himself to be, a member of, or an agent for, the Boy Scouts of the Philippines; and any person who violates any of the provisions of this Act shall be punished by prison correccional in its minimum period or a fine not exceeding Five thousand pesos (P5,000.00) or both, at the discretion of the court.\n\"It shall be unlawful for any person to manufacture, sell or distribute or cause to be manufactured, sold or distributed fraudulently or without the official knowledge and written consent or permission of the National Executive Board of the Boy Scouts of the Philippines badges, uniforms, insignia, or any other boy scout paraphernalia; or to use, apply, feature or portray said badges, uniforms, insignia or scouting paraphernalia or the photos or visuals of a boy scout or boy scouts in uniform, or the logo, seal, or corporate name of the Boy Scouts of the Philippines, in any print ad, radio or television commercial, billboard, collateral material or any form of advertisement; or to use the name of the Boy Scouts of the Philippines for any illegal purpose or personal gain. Any violation of any of the provisions of Section 7 and of this section shall be punished by prison correccional in its medium period to prison mayor in its minimum period or a fine of not less than Ten thousand pesos (P10,000.00) nor more than One hundred thousand pesos (P100,000.00), or both, at the discretion of the court: Provided, That, in case of corporations, partnerships, associations, societies or companies, the manager, administrator or the person in charge of the management or administration of the business shall be criminally responsible for any such violation. These penalties shall be without prejudice to the proper civil action for recovery of civil damages, which may be instituted together with or independently of the criminal prosecution.\n\""}},{"id":"PH-H5766-A11","no":11,"noLabel":{"en":"Section 11."},"text":{"en":"Until such time as the reorganization and restructuring of the Boy Scouts of the Philippines in accordance with this Act is effected, the incumbent officers and members of the National Executive Board and the present and past national presidents of the Boy Scouts of the Philippines shall continue to conduct the affairs of the Boy Scouts of the Philippines and to take the necessary steps to effect such reorganization until a new National Executive Board and a new set of national officers shall have been elected within six (6) months from the effectivity of this Act.\""}},{"id":"PH-H5766-A5-d2","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"If any section or provision of this Act is held invalid, all other provisions not affected thereby shall remain valid."},"dupIndex":2},{"id":"PH-H5766-A6-d2","no":6,"noLabel":{"en":"Section 6."},"text":{"en":"This Act shall take effect upon the completion of its publication in at least two (2) national newspapers of general circulation."},"dupIndex":2}],"pack":"ph-p82"};
  FT["PH-H5767"] = {"id":"PH-H5767","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1992/ra_7279_1992.html","fetchedAt":"2026-10-06","articleCount":49,"structureMode":"ARTICLE","title":{"zh":"规定全面持续的城市发展与住房计划，建立其实施机制并为其他目的法案","en":"An Act to Provide for a Comprehensive and Continuing Urban Development and Housing Program, Establish the Mechanism for Its Implementation, and for Other Purposes","orig":"An Act to Provide for a Comprehensive and Continuing Urban Development and Housing Program, Establish the Mechanism for Its Implementation, and for Other Purposes"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 7279","issuingBody":"Congress of the Philippines","promulgatedDate":"1992-03-24","completenessNote":"全文，共 49 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1992/ra_7279_1992.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H5767-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Title . - This Act shall be known as the \"Urban Development and Housing Act of 1992.\""}},{"id":"PH-H5767-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"Declaration of State Policy and Program Objectives. - It shall be the policy of the State to undertake, in cooperation with the private sector, a comprehensive and continuing Urban Development and Housing Program, hereinafter referred to as the Program, which shall:\na. Uplift the conditions of the underprivileged and homeless citizens in urban areas and in resettlement areas by making available to them decent housing at affordable cost, basic services, and employment opportunities;\nb. Provide for the rational use and development of urban land in order to bring about the following:\n1. Equitable utilization of residential lands in urban and urbanizable areas with particular attention to the needs and requirements of the underprivileged and homeless citizens and not merely on the basis of market forces;\n2. Optimization of the use and productivity of land and urban resources;\n3. Development of urban areas conducive to commercial and industrial activities which can generate more economic opportunities for the people;\n4. Reduction in urban dysfunctions, particularly those that adversely affect public health, safety and ecology; and\n5. Access to land and housing by the underprivileged and homeless citizens;\nc. Adopt workable policies to regulate and direct urban growth and expansion towards a dispersed urban net and more balanced urban-rural interdependence;\nd. Provide for an equitable land tenure system that shall guarantee security of tenure to Program beneficiaries but shall respect the rights of small property owners and ensure the payment of just compensation;\ne. Encourage more effective people's participation in the urban development process; and\nf. Improve the capability of local government units in undertaking urban development and housing programs and projects."}},{"id":"PH-H5767-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"Definition of Terms. - For purposes of this Act:\na. \"Affordable cost\" refers to the most reasonable price of land and shelter based on the needs and financial capability of Program beneficiaries and appropriate financing schemes;\nb. \"Areas for priority development\" refers to those areas declared as such under existing statutes and pertinent executive issuances;\nc. \"Blighted lands\" refers to the areas where the structures are dilapidated, obsolete and unsanitary, tending to depreciate the value of the land and prevent normal development and use of the area.\nd. \"Consultation\" refers to the constitutionally mandated process whereby the public, on their own or through people's organizations, is provided an opportunity to be heard and to participate in the decision-making process on matters involving the protection and promotion of its legitimate collective interests, which shall include appropriate documentation and feedback mechanisms;\ne. \"Idle lands\" refers to non-agricultural lands in urban and urbanizable areas on which no improvements, as herein defined, have been made by the owner, as certified by the city, municipal or provincial assessor;\nf. \"Improvements\" refers to all types of buildings and residential units, walls, fences, structures or construction of all kinds of a fixed character or which are adhered to the soil but shall not include trees, plants and growing fruits, and other fixtures that are mere superimpositions on the land, and the value of improvements shall not be less than fifty percent (50%) of the assessed value of the property;\ng. \"Joint venture\" refers to the commitment or agreement by two (2) or more persons to carry out a specific or single business enterprise for their mutual benefit, for which purpose they combine their funds, land resources, facilities and services;\nh. \"Land assembly or consolidation\" refers to the acquisition of lots of varying ownership through purchase or expropriation for the purpose of planned and rational development and socialized housing programs without individual property boundary restrictions;\ni. \"Land banking\" refers to the acquisition of land at values based on existing use in advance of actual need to promote planned development and socialized housing programs;\nj. \"Land swapping\" refers to the process of land acquisition by exchanging land for another piece of land of equal value, or for shares of stock in a government or quasi-government corporation whose book value is of equal value to the land being exchanged, for the purpose of planned and rational development and provision for socialized housing where land values are determined based on land classification, market value and assessed value taken from existing tax declarations: Provided, That more valuable lands owned by private persons may be exchanged with less valuable lands to carry out the objectives of this Act;\nk. \"Land use plan\" refers to the rational approach of allocating available land resources as equitably as possible among competing user groups and for different functions consistent with the development plan of the area and the Program under this Act;\nl. \"On-site development\" refers to the process of upgrading and rehabilitation of blighted and slum urban areas with a view of minimizing displacement of dwellers in said areas, and with provisions for basic services as provided for in Section 21 hereof;\nm. \"Professional squatters\" refers to individuals or groups who occupy lands without the express consent of the landowner and who have sufficient income for legitimate housing. The term shall also apply to persons who have previously been awarded homelot or housing units by the Government but who sold, leased or transferred the same to settle illegally in the same place or in another urban area, and non-bona fide occupants and intruders of lands reserved for socialized housing. The term shall not apply to individuals or groups who simply rent land and housing from professional squatters or squatting syndicates;\nn. \"Resettlement areas\" refers to areas identified by the appropriate national agency or by the local government unit with respect to areas within its jurisdiction, which shall be used for the relocation of the underprivileged and homeless citizens;\no. \"Security of tenure\" refers to the degree of protection afforded to qualified Program beneficiaries against infringement or unjust, unreasonable and arbitrary eviction or disposition, by virtue of the right of ownership, lease agreement, usufruct and other contractual arrangements;\np. \"Slum Improvement and Resettlement Program or SIR\" refers to the program of the National Housing Authority of upgrading and improving blighted squatter areas outside of Metro Manila pursuant to existing statutes and pertinent executive issuances;\nq. \"Small property owners\" refers to those whose only real property consists of residential lands not exceeding three hundred square meters (300 sq. m.) in highly urbanized cities and eight hundred square meters (800 sq. m.) in other urban areas;\nr. \"Socialized housing\" refers to housing programs and projects covering houses and lots or homelots only undertaken by the Government or the private sector for the underprivileged and homeless citizens which shall include sites and services development, long-term financing, liberalized terms on interest payments, and such other benefits in accordance with the provisions of this Act;\ns. \"Squatting syndicates\" refers to groups of persons engaged in the business of squatter housing for profit or gain;\nt. \"Underprivileged and homeless citizens\" refers to the beneficiaries of this Act and to individuals or families residing in urban and urbanizable areas whose income or combined household income falls within the poverty threshold as defined by the National Economic and Development Authority and who do not own housing facilities. This shall include those who live in makeshift dwelling units and do not enjoy security of tenure;\nu. \"Unregistered or abandoned lands\" refers to lands in urban and urbanizable areas which are not registered with the Register of Deeds, or with the city or municipal assessor's office concerned, or which are uninhabited by the owner and have not been developed or devoted for any useful purpose, or appears unutilized for a period of three (3) consecutive years immediately prior to the issuance and receipt or publication of notice of acquisition by the Government as provided under this Act. It does not include land which has been abandoned by reason of force majeure or any other fortuitous event: Provided, That prior to such event, such land was previously used for some useful or economic purpose;\nv. \"Urban areas\" refers to all cities regardless of their population density and to municipalities with a population density of at least five hundred (500) persons per square kilometer;\nw. \"Urbanizable areas\" refers to sites and lands which, considering present characteristics and prevailing conditions, display marked and great potential of becoming urban areas within the period of five (5) years; and\nx. \"Zonal Improvement Program or ZIP\" refers to the program of the National Housing Authority of upgrading and improving blighted squatter areas within the cities and municipalities of Metro Manila pursuant to existing statutes and pertinent executive issuances.\nARTICLE II\nCOVERAGE AND EXEMPTIONS"}},{"id":"PH-H5767-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"Coverage . - The Program shall cover all lands in urban and urbanizable areas, including existing areas for priority development, zonal improvement sites, slum improvement and resettlement sites, and in other areas that may be identified by the local government units as suitable for socialized housing."}},{"id":"PH-H5767-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"Exemptions. - The following lands shall be exempt from the coverage of this Act:\na. Those included in the coverage of Republic Act No. 6657, otherwise known as the Comprehensive Agrarian Reform Law;\nb. Those actually used for national defense and security of the State;\nc. Those used, reserved or otherwise set aside for government offices, facilities and other installations, whether owned by the National Government, its agencies and instrumentalities, including government-owned or-controlled corporations, or by the local government units: Provided, however, That the lands herein mentioned, or portions thereof, which have not been used for the purpose for which they have been reserved or set aside for the past ten (10) years from the effectivity of this Act, shall be covered by this Act;\nd. Those used or set aside for parks, reserves for flora and fauna, forests and watersheds, and other areas necessary to maintain ecological balance or environment protection, as determined and certified to by the proper government agency; and\ne. Those actually and primarily used for religious, charitable, or educational purposes, cultural and historical sites, hospitals and health centers, and cemeteries or memorial parks.\nThe exemptions herein provided shall not apply when the use or purpose of the abovementioned lands has ceased to exist.\nARTICLE III\nNATIONAL URBAN DEVELOPMENT AND HOUSING FRAMEWORK"}},{"id":"PH-H5767-A6","no":6,"noLabel":{"en":"Section 6."},"text":{"en":"Framework for Rational Development. - There shall be a National Urban Development and Housing Framework to be formulated by the Housing and Land Use Regulatory Board under the direction of the Housing and Urban Development Coordinating Council in coordination with all local government units and other concerned public and private sectors within one (1) year from the effectivity of this Act.\nThe Framework shall refer to the comprehensive plan for urban and urbanizable areas aimed at achieving the objectives of the Program. In the formulation of the Framework, a review and rationalization of existing town and land use plans, housing programs, and all other projects and activities of government agencies and the private sector which may substantially affect urban land use patterns, transportations and public utilities, infrastructure, environment and population movements shall be undertaken with the concurrence of the local government units concerned.\nARTICLE IV\nLAND USE, INVENTORY, ACQUISITION AND DISPOSITION"}},{"id":"PH-H5767-A7","no":7,"noLabel":{"en":"Section 7."},"text":{"en":"Inventory of Lands. - Within one (1) year from the effectivity of this Act, all city and municipal governments shall conduct an inventory of all lands and improvements thereon within their respective localities. The inventory shall include the following:\na. Residential lands;\nb. Government-owned lands whether owned by the National Government or any of its subdivisions, instrumentalities, or agencies, including government-owned or-controlled corporation and their subsidiaries;\nc. Unregistered or abandoned and idle lands; and\nd. Other lands.\nIn conducting the inventory, the local government units concerned, in coordination with the Housing and Land Use Regulatory Board and with the assistance of the appropriate government agencies, shall indicate the type of land use and the degree of land utilization, and other data or information necessary to carry out the purposes of this Act.\nFor planning purposes, the housing and Urban Development Coordinating Council shall be furnished by each local government unit a copy of its inventory which shall be updated every three (3) years."}},{"id":"PH-H5767-A8","no":8,"noLabel":{"en":"Section 8."},"text":{"en":"Identification of Sites for Socialized Housing. - After the inventory, the local government units, in coordination with the National Housing Authority, the Housing and Land Use Regulatory Board, the National Mapping Resource Information Authority, and the Land Management Bureau, shall identify lands for socialized housing and resettlement areas for the immediate and future needs of the underprivileged and homeless in the urban areas, taking into consideration the degree of availability of basic services and facilities, their accessibility and proximity to job sites and other economic opportunities, and the actual number of registered beneficiaries.\nGovernment-owned lands under paragraph (b) of the preceding section which have not been used for the purpose for which they have been reserved or set aside for the past ten (10) years from the effectivity of this Act and identified as suitable for socialized housing, shall immediately be transferred to the National Housing Authority subject to the approval of the President of the Philippines or by the local government unit concerned, as the case may be, for proper disposition in accordance with this Act."}},{"id":"PH-H5767-A9","no":9,"noLabel":{"en":"Section 9."},"text":{"en":"Priorities in the Acquisition of Land. - Lands for socialized housing shall be acquired in the following order:\na. Those owned by the Government or any of its subdivisions, instrumentalities, or agencies, including government-owned or -controlled corporations and their subsidiaries;\nb. Alienable lands of the public domain;\nc. Unregistered or abandoned and idle Iands;\nd. Those within the declared Areas for Priority Development, Zonal Improvement Program sites, and Slum Improvement and Resettlement Program sites which have not yet been acquired;\ne. Bagong Lipunan Improvement of Sites and Services or BLISS sites which have not yet been acquired; and\nf. Privately-owned lands.\nWhere on-site development is found more practicable and advantageous to the beneficiaries, the priorities mentioned in this section shall not apply. The local government units shall give budgetary priority to on-site development of government lands."}},{"id":"PH-H5767-A10","no":10,"noLabel":{"en":"Section 10."},"text":{"en":"Modes of Land Acquisition. - The modes of acquiring lands for purposes of this Act shall include, among others, community mortgage, land swapping, land assembly or consolidation, land banking, donation to the Government, joint-venture agreement, negotiated purchase, and expropriation: Provided,however, That expropriation shall be resorted to only when other modes of acquisition have been exhausted: Provided, further, That where expropriation is resorted to, parcels of land owned by small property owners shall be exempted for purposes of this Act: Provided, finally, That abandoned property, as herein defined, shall be reverted and escheated to the State in a proceeding analogous to the procedure laid down in Rule 91 of the Rules of Court.\nFor the purpose of socialized housing, government-owned and foreclosed properties shall be acquired by the local government units, or by the National Housing Authority primarily through negotiated purchase: Provided, That qualified beneficiaries who are actual occupants of the land shall be given the right of first refusal."}},{"id":"PH-H5767-A11","no":11,"noLabel":{"en":"Section 11."},"text":{"en":"Expropriation of Idle Lands. - All idle lands in urban and urbanizable areas, as defined and identified in accordance with this Act, shall be expropriated and shall form part of the public domain. These lands shall be disposed of or utilized by the Government for such purposes that conform with their land use plans. Expropriation proceedings shall be instituted if, after the lapse of one (1) year following receipt of notice of acquisition, the owner fails to introduce improvements as defined in Section 3(f) hereof, except in the case of force majeure and other fortuitous events. Exempted from this provision, however, are residential lands owned by small property owners or those the ownership of which is subject of a pending litigation."}},{"id":"PH-H5767-A12","no":12,"noLabel":{"en":"Section 12."},"text":{"en":"Disposition of Lands for Socialized Housing. - The National Housing Authority, with respect to lands belonging to the National Government, and the local government units with respect to other lands within their respective localities, shall coordinate with each other to formulate and make available various alternative schemes for the disposition of lands to the beneficiaries of the Program. These schemes shall not be limited to those involving transfer of ownership in fee simple but shall include lease, with option to purchase, usufruct or such other variations as the local government units or the National Housing Authority may deem most expedient in carrying out the purposes of this Act.\nConsistent with this provision, a scheme for public rental housing may be adopted."}},{"id":"PH-H5767-A13","no":13,"noLabel":{"en":"Section 13."},"text":{"en":"Valuation of Lands for Socialized Housing. - Equitable land valuation guidelines for socialized housing shall be set by the Department of Finance on the basis of the market value reflected in the zonal valuation, or in its absence, on the latest real property tax declaration.\nFor sites already occupied by qualified Program beneficiaries, the Department of Finance shall factor into the valuation the blighted status of the land as certified by the local government unit or the National Housing Authority."}},{"id":"PH-H5767-A14","no":14,"noLabel":{"en":"Section 14."},"text":{"en":"Limitations on the Disposition of Lands for Socialized Housing. - No land for socialized housing, including improvements or rights thereon, shall be sold, alienated, conveyed, encumbered or leased by any beneficiary of this Program except to qualified Program beneficiaries as determined by the government agency concerned.\nShould the beneficiary unlawfully sell, transfer, or otherwise dispose of his lot or any right thereon, the transaction shall be null and void. He shall also lose his right to the land, forfeit the total amortization paid thereon, and shall be barred from the benefits under this Act for a period of ten (10) years from the date of violation.\nIn the event the beneficiary dies before full ownership of the land is vested on him, transfer to his heirs shall take place only upon their assumption of his outstanding obligations. In case of failure by the heirs to assume such obligations, the land shall revert to the Government for disposition in accordance with this Act.\nARTICLE V\nSOCIALIZED HOUSING"}},{"id":"PH-H5767-A15","no":15,"noLabel":{"en":"Section 15."},"text":{"en":"Policy. - Socialized housing, as defined in Section 3 hereof, shall be the primary strategy in providing shelter for the underprivileged and homeless. However, if the tenurial arrangement in a particular socialized housing program is in the nature of leasehold or usufruct, the same shall be transitory and the beneficiaries must be encouraged to become independent from the Program within a given period of time, to be determined by the implementing agency concerned."}},{"id":"PH-H5767-A16","no":16,"noLabel":{"en":"Section 16."},"text":{"en":"Eligibility Criteria for Socialized Housing Program Beneficiaries. - To qualify for the socialized housing program, a beneficiary:\na. Must be a Filipino citizen;\nb. Must be an underprivileged and homeless citizen, as defined in Section 3 of this Act;\nc. Must not own any real property whether in the urban or rural areas; and\nd. Must not be a professional squatter or a member of squatting syndicates."}},{"id":"PH-H5767-A17","no":17,"noLabel":{"en":"Section 17."},"text":{"en":"Registration of Socialized Housing Beneficiaries. - The Housing and Urban Development Coordinating Council, in coordination with the local government units, shall design a system for the registration of qualified Program beneficiaries in accordance with the Framework. The local government units, within one (1) year from the effectivity of this Act, shall identify and register all beneficiaries within their respective localities."}},{"id":"PH-H5767-A18","no":18,"noLabel":{"en":"Section 18."},"text":{"en":"Balanced Housing Development. - The Program shall include a system to be specified in the Framework plan whereby developers of proposed subdivision projects shall be required to develop an area for socialized housing equivalent to at least twenty percent (20%) of the total subdivision area or total subdivision project cost, at the option of the developer, within the same city or municipality, whenever feasible, and in accordance with the standards set by the Housing and Land Use Regulatory Board and other existing laws. The balanced housing development as herein required may also be complied with by the developers concerned in any of the following manner:\na. Development of new settlement;\nb. Slum upgrading or renewal of areas for priority development either through zonal improvement programs or slum improvement and resettlement programs;\nc. Joint-venture projects with either the local government units or any of the housing agencies; or\nd. Participation in the community mortgage program."}},{"id":"PH-H5767-A19","no":19,"noLabel":{"en":"Section 19."},"text":{"en":"Incentives for the National Housing Authority. - The National Housing Authority, being the primary government agency in charge of providing housing for the underprivileged and homeless, shall be exempted from the payment of all fees and charges of any kind, whether local or national, such as income and real taxes. All documents or contracts executed by and in favor of the National Housing Authority shall also be exempt from the payment of documentary stamp tax and registration fees, including fees required for the issuance of transfer certificates of titles."}},{"id":"PH-H5767-A20","no":20,"noLabel":{"en":"Section 20."},"text":{"en":"Incentives for Private Sector Participating in Socialized Housing. - To encourage greater private sector participation in socialized housing and further reduce the cost of housing units for the benefit of the underprivileged and homeless, the following incentives shall be extended to the private sector:\na. Reduction and simplification of qualification and accreditation requirements for participating private developers;\nb. Creation of one-stop offices in the different regions of the country for the processing, approval and issuance of clearances, permits and licenses: Provided, That clearances, permits and licenses shall be issued within ninety (90) days from the date of submission of all requirements by the participating private developers;\nc. Simplification of financing procedures; and\nd. Exemption from the payment of the following:\n1. Project-related income taxes;\n2. Capital gains tax on raw lands used for the project;\n3. Value-added tax for the project contractor concerned;\n4. Transfer tax for both raw and completed projects; and\n5. Donor's tax for lands certified by the local government units to have been donated for socialized housing purposes.\nProvided, That upon application for exemption, a lien on the title of the land shall be annotated by the Register of Deeds: Provided, further, That the socialized housing development plan has already been approved by the appropriate government agencies concerned: Provided,finally, That all the savings acquired by virtue of this provision shall accrue in favor of the beneficiaries subject to the implementing guidelines to be issued by the Housing and Urban Development Coordinating Council.\nAppropriate implementing guidelines shall be prepared by the Department of Finance, in consultation with the Housing and Urban Development Coordinating Council, for the proper implementation of the tax exemption mentioned in this section within one (1) year after the approval of this Act.\nProperty owners who voluntarily provide resettlement sites to illegal occupants of their lands shall be entitled to a tax credit equivalent to the actual non-recoverable expenses incurred in the resettlement, subject to the implementing guidelines jointly issued by the Housing and Urban Development Coordinating Council and the Department of Finance."}},{"id":"PH-H5767-A21","no":21,"noLabel":{"en":"Section 21."},"text":{"en":"Basic Services. - Socialized housing or resettlement areas shall be provided by the local government unit or the National Housing Authority in cooperation with the private developers and concerned agencies with the following basic services and facilities:\na. Potable water;\nb. Power and electricity and an adequate power distribution system;\nc. Sewerage facilities and an efficient and adequate solid waste disposal system; and\nd. Access to primary roads and transportation facilities.\nThe provision of other basic services and facilities such as health, education, communications, security, recreation, relief and welfare shall be planned and shall be given priority for implementation by the local government unit and concerned agencies in cooperation with the private sector and the beneficiaries themselves.\nThe local government unit, in coordination with the concerned national agencies, shall ensure that these basic services are provided at the most cost-efficient rates, and shall set a mechanism to coordinate operationally the thrusts, objectives and activities of other government agencies concerned with providing basic services to housing projects."}},{"id":"PH-H5767-A22","no":22,"noLabel":{"en":"Section 22."},"text":{"en":"Livelihood Component. - To the extent feasible, socialized housing and resettlement projects shall be located near areas where employment opportunities are accessible. The government agencies dealing with the development of livelihood programs and grant of livelihood loans shall give priority to the beneficiaries of the Program."}},{"id":"PH-H5767-A23","no":23,"noLabel":{"en":"Section 23."},"text":{"en":"Participation of Beneficiaries. - The local government units, in coordination with the Presidential Commission for the Urban Poor and concerned government agencies, shall afford Program beneficiaries or their duly designated representatives an opportunity to be heard and to participate in the decision-making process over matters involving the protection and promotion of their legitimate collective interests which shall include appropriate documentation and feedback mechanisms. They shall also be encouraged to organize themselves and undertake self-help cooperative housing and other livelihood activities. They shall assist the Government in preventing the incursions of professional squatters and members of squatting syndicates into their communities.\nIn instances when the affected beneficiaries have failed to organize themselves or form an alliance within a reasonable period prior to the implementation of the program or projects affecting them, consultation between the implementing agency and the affected beneficiaries shall be conducted with the assistance of the Presidential Commission for the Urban Poor and the concerned nongovernment organizations."}},{"id":"PH-H5767-A24","no":24,"noLabel":{"en":"Section 24."},"text":{"en":"Consultation with Private Sector. - Opportunities for adequate consultation shall be accorded to the private sector involved in socialized housing project pursuant to this Act.\nARTICLE VI\nAREAS FOR PRIORITY DEVELOPMENT, ZONAL IMPROVEMENT PROGRAM SITES AND SLUM IMPROVEMENT AND RESETTLEMENT PROGRAM SITES"}},{"id":"PH-H5767-A25","no":25,"noLabel":{"en":"Section 25."},"text":{"en":"Benefits. - In addition to the benefits provided under existing laws and other related issuances to occupants of areas for priority development, zonal improvement program sites and slum improvement and resettlement program sites, such occupants shall be entitled to priority in all government projects initiated pursuant to this Act. They shall also be entitled to the following support services:\na. Land surveys and titling at minimal cost;\nb. Liberalized terms on credit facilities and housing loans and one hundred percent (100%) deduction from every homebuyer's gross income tax of all interest payments made on documented loans incurred for the construction or purchase of the homebuyer's house;\nc. Exemption from the payment of documentary stamp tax, registration fees, and other fees for the issuance of transfer certificate of titles;\nd. Basic services as provided for in Section 21 of this Act; and\ne. Such other benefits that may arise from the implementation of this Act.\nARTICLE VII\nURBAN RENEWAL AND RESETTLEMENT"}},{"id":"PH-H5767-A26","no":26,"noLabel":{"en":"Section 26."},"text":{"en":"Urban Renewal and Resettlement. - This shall include the rehabilitation and development of blighted and slum areas and the resettlement of Program beneficiaries in accordance with the provisions of this Act. On-site development shall be implemented whenever possible in order to ensure minimum movement of occupants of blighted lands and slum areas. The resettlement of the beneficiaries of the Program from their existing places of occupancy shall be undertaken only when on-site development is not feasible and after compliance with the procedures laid down in Section 28 of this Act."}},{"id":"PH-H5767-A27","no":27,"noLabel":{"en":"Section 27."},"text":{"en":"Action Against Professional Squatters and Squatting Syndicates. - The local government units, in cooperation with the Philippine National Police, the Presidential Commission for the Urban Poor (PCUP), and the PCUP-accredited urban poor organization in the area, shall adopt measures to identify and effectively curtail the nefarious and illegal activities of professional squatters and squatting syndicates, as herein defined.\nAny person or group identified as such shall be summarily evicted and their dwellings or structures demolished, and shall be disqualified to avail of the benefits of the Program. A public official who tolerates or abets the commission of the abovementioned acts shall be dealt with in accordance with existing laws.\nFor purposes of this Act, professional squatters or members of squatting syndicates shall be imposed the penalty of six (6) years imprisonment or a fine of not less than Sixty thousand pesos (P60,000) but not more than One hundred thousand pesos (P100,000), or both, at the discretion of the court."}},{"id":"PH-H5767-A28","no":28,"noLabel":{"en":"Section 28."},"text":{"en":"Eviction and Demolition. - Eviction or demolition as a practice shall be discouraged. Eviction or demolition, however, may be allowed under the following situations:\na. When persons or entities occupy danger areas such as esteros, railroad tracks, garbage dumps, riverbanks, shorelines, waterways, and other public places such as sidewalks, roads, parks, and playgrounds;\nb. When government infrastructure projects with available funding are about to be implemented; or\nc. When there is a court order for eviction and demolition.\nIn the execution of eviction or demolition orders involving underprivileged and homeless citizens, the following shall be mandatory:\n1. Notice upon the affected persons or entities at least thirty (30) days prior to the date of eviction or demolition;\n2. Adequate consultations on the matter of resettlement with the duly designated representatives of the families to be resettled and the affected communities in the areas where they are to be relocated;\n3. Presence of local government officials or their representatives during eviction or demolition;\n4. Proper identification of all persons taking part in the demolition;\n5. Execution of eviction or demolition only during regular office hours from Mondays to Fridays and during good weather, unless the affected families consent otherwise;\n6. No use of heavy equipment for demolition except for structures that are permanent and of concrete materials;\n7. Proper uniforms for members of the Philippine National Police who shall occupy the first line of law enforcement and observe proper disturbance control procedures; and\n8. Adequate relocation, whether temporary or permanent: Provided, however, That in cases of eviction and demolition pursuant to a court order involving underprivileged and homeless citizens, relocation shall be undertaken by the local government unit concerned and the National Housing Authority with the assistance of other government agencies within forty-five (45) days from service of notice of final judgment by the court, after which period the said order shall be executed: Provided, further, That should relocation not be possible within the said period, financial assistance in the amount equivalent to the prevailing minimum daily wage multiplied by sixty (60) days shall be extended to the affected families by the local government unit concerned.\nThe Department of the Interior and Local Government and the Housing and Urban Development Coordinating Council shall jointly promulgate the necessary rules and regulations to carry out the above provision."}},{"id":"PH-H5767-A29","no":29,"noLabel":{"en":"Section 29."},"text":{"en":"Resettlement. - Within two (2) years from the effectivity of this Act, the local government units, in coordination with the National Housing Authority, shall implement the relocation and resettlement of persons living in danger areas such as esteros, railroad tracks, garbage dumps, riverbanks, shorelines, waterways, and other public places such as sidewalks, roads, parks, and playgrounds. The local government unit, in coordination with the National Housing Authority, shall provide relocation or resettlement sites with basic services and facilities and access to employment and livelihood opportunities sufficient to meet the basic needs of the affected families."}},{"id":"PH-H5767-A30","no":30,"noLabel":{"en":"Section 30."},"text":{"en":"Prohibition Against New Illegal Structures. - It shall be unlawful for any person to construct any structure in areas mentioned in the preceding section.\nAfter the effectivity of this Act, the barangay, municipal or city government units shall prevent the construction of any kind of illegal dwelling units or structures within their respective localities. The head of any local government unit concerned who allows, abets or otherwise tolerates the construction of any structure in violation of this section shall be liable to administrative sanctions under existing laws and to penal sanctions provided for in this Act.\nARTICLE VIII\nCOMMUNITY MORTGAGE PROGRAM"}},{"id":"PH-H5767-A31","no":31,"noLabel":{"en":"Section 31."},"text":{"en":"Definition. - The Community Mortgage Program (CMP) is a mortgage financing program of the National Home Mortgage Finance Corporation which assists legally organized associations of underprivileged and homeless citizens to purchase and develop a tract of land under the concept of community ownership. The primary objective of the program is to assist residents of blighted or depressed areas to own the lots they occupy, or where they choose to relocate to, and eventually improve their neighborhood and homes to the extent of their affordability."}},{"id":"PH-H5767-A32","no":32,"noLabel":{"en":"Section 32."},"text":{"en":"Incentives. - To encourage its wider implementation, participants in the CMP shall be granted with the following privileges or incentives:\na. Government-owned or-controlled corporations and local government units, may dispose of their idle lands suitable for socialized housing under the CMP through negotiated sale at prices based on acquisition cost plus financial carrying costs;\nb. Properties sold under the CMP shall be exempted from the capital gains tax; and\nc. Beneficiaries under the CMP shall not be evicted nor dispossessed of their lands or improvements unless they have incurred arrearages in payments of amortization for three (3) months."}},{"id":"PH-H5767-A33","no":33,"noLabel":{"en":"Section 33."},"text":{"en":"Organization of Beneficiaries. - Beneficiaries of the Program shall be responsible for their organization into associations to manage their subdivisions or places of residence, to secure housing loans under existing Community Mortgage Program and such other projects beneficial to them. Subject to such rules and regulations to be promulgated by the National Home Mortgage Finance Corporation, associations organized pursuant to this Act may collectively acquire and own lands covered by this Program. Where the beneficiaries fail to form an association by and among themselves, the National Home Mortgage Finance Corporation shall initiate the organization of the same in coordination with the Presidential Commission for the Urban Poor and the local government units concerned. No person who is not a bona fide resident of the area shall be a member or officer of such association.\nARTICLE IX\nRELATED STRATEGIES"}},{"id":"PH-H5767-A34","no":34,"noLabel":{"en":"Section 34."},"text":{"en":"Promotion of Indigenous Housing Materials and Technologies. - The local government units, in cooperation with the National Housing Authority, Technology and Livelihood Resource Center, and other concerned agencies, shall promote the production and use of indigenous, alternative, and low-cost construction materials and technologies for socialized housing."}},{"id":"PH-H5767-A35","no":35,"noLabel":{"en":"Section 35."},"text":{"en":"Transport System. - The local government units, in coordination with the Departments of Transportation and Communications, Budget and Management, Trade and Industry, Finance, and Public Works and Highways, the Home Insurance Guaranty Corporation, and other concerned government agencies, shall device a set of mechanisms including incentives to the private sector so that a viable transport system shall evolve and develop in the urban areas. It shall also formulate standards designed to attain these objectives:\na. Smooth flow of traffic;\nb. Safety and convenience of travel;\nc. Minimum use of land space;\nd. Minimum damage to the physical environment; and\ne. Adequate and efficient transport service to the people and goods at minimum cost."}},{"id":"PH-H5767-A36","no":36,"noLabel":{"en":"Section 36."},"text":{"en":"Ecological Balance. - The local government units shall coordinate with the Department of Environment and Natural Resources in taking measures that will plan and regulate urban activities for the conservation and protection of vital, unique and sensitive ecosystems, scenic landscapes, cultural sites and other similar resource areas.\nTo make the implementation of this function more effective, the active participation of the citizenry in environmental rehabilitation and in decision-making process shall be promoted and encouraged. The local government units shall recommend to the Environmental and Management Bureau the immediate closure of factories, mines and transport companies which are found to be causing massive pollution."}},{"id":"PH-H5767-A37","no":37,"noLabel":{"en":"Section 37."},"text":{"en":"Population Movements. - The local government units shall set up an effective mechanism, together with the appropriate agencies like the Population Commission, the National Economic and Development Authority and the National Statistics Office, to monitor trends in the movements of population from rural to urban, urban to urban, and urban to rural areas. They shall identify measures by which such movements can be influenced to achieve balance between urban capabilities and population, to direct appropriate segments of the population into areas where they can have access to opportunities to improve their lives and to contribute to national growth and recommend proposed legislation to Congress, if necessary.\nThe Population Commission, the National Economic and Development Authority, and the National Statistics Office shall likewise provide advanced planning information to national and local government planners on population projections and the consequent level of services needed in particular urban and urbanizable areas. This service will include early-warning systems on expected dysfunctions in a particular urban area due to population increases, decreases, or age structure changes."}},{"id":"PH-H5767-A38","no":38,"noLabel":{"en":"Section 38."},"text":{"en":"Urban-rural Interdependence. - To minimize rural to urban migration and pursue urban decentralization, the local government units shall coordinate with the National Economic and Development Authority and other government agencies in the formulation of national development programs that will stimulate economic growth and promote socioeconomic development in the countryside.\nARTICLE X\nPROGRAM IMPLEMENTATION"}},{"id":"PH-H5767-A39","no":39,"noLabel":{"en":"Section 39."},"text":{"en":"Role of Local Government Units. - The local government units shall be charged with the implementation of this Act in their respective localities, in coordination with the Housing and Urban Development Coordinating Council, the national housing agencies, the Presidential Commission for the Urban Poor, the private sector and other nongovernment organizations.\nThey shall prepare a comprehensive land use plan for their respective localities in accordance with the provisions of this Act."}},{"id":"PH-H5767-A40","no":40,"noLabel":{"en":"Section 40."},"text":{"en":"Role of Government Housing Agencies. - In addition to their respective existing powers and functions, and those provided for in this Act, the hereunder mentioned housing agencies shall perform the following:\na. The Housing and Urban Development Coordinating Council shall, through the key housing agencies, provide local government units with necessary support such as:\n1. Formulation of standards and guidelines as well as providing technical support in the preparation of town and land use plans;\n2. In coordination with the National Economic and Development Authority and the National Statistics Office, provide data and information for forward-planning by the local government units in their areas, particularly on projections as to the population and development trends in their localities and the corresponding investment programs needed to provide appropriate types and levels of infrastructure, utilities, services and land use patterns; and\n3. Assistance in obtaining funds and other resources needed in the urban development and housing programs in their areas of responsibility.\nb. The National Housing Authority, upon request of local government units, shall provide technical and other forms of assistance in the implementation of their respective urban development and housing programs with the objective of augmenting and enhancing local government capabilities in the provision of housing benefits to their constituents;\nc. The National Home Mortgage Finance Corporation shall administer the Community Mortgage Program under this Act and promulgate rules and regulations necessary to carry out the provisions of this Act; and\nd. The Home Insurance Guaranty Corporation shall design an appropriate guarantee scheme to encourage financial institutions to go into direct lending for housing."}},{"id":"PH-H5767-A41","no":41,"noLabel":{"en":"Section 41."},"text":{"en":"Annual Report. - The Housing and Urban Development Coordinating Council and the local government units shall submit a detailed annual report with respect to the implementation of this Act to the President and the Congress of the Republic of the Philippines.\nARTICLE XI\nFUNDING"}},{"id":"PH-H5767-A42","no":42,"noLabel":{"en":"Section 42."},"text":{"en":"Funding. - Funds for the urban development and housing program shall come from the following sources:\na. A minimum of fifty percent (50%) from the annual net income of the Public Estates Authority, to be used by the National Housing Authority to carry out its programs of land acquisition for resettlement purposes under this Act;\nb. Proceeds from the disposition of ill-gotten wealth, not otherwise previously set aside for any other purpose, shall be applied to the implementation of this Act and shall be administered by the National Home Mortgage Finance Corporation;\nc. Loans, grants, bequests and donations, whether from local or foreign sources;\nd. Flotation of bonds, subject to the guidelines to be set by the Monetary Board;\ne. Proceeds from the social housing tax and, subject to the concurrence of the local government units concerned, idle lands tax as provided in Section 236 of the Local Government Code of 1991 and other existing laws;\nf. Proceeds from the sale or disposition of alienable public lands in urban areas; and\ng. Domestic and foreign investment or financing through appropriate arrangements like the build-operate-and-transfer scheme."}},{"id":"PH-H5767-A43","no":43,"noLabel":{"en":"Section 43."},"text":{"en":"Socialized Housing Tax. - Consistent with the constitutional principle that the ownership and enjoyment of property bear a social function and to raise funds for the Program, all local government units are hereby authorized to impose an additional one-half percent (0.5%) tax on the assessed value of all lands in urban areas in excess of Fifty thousand pesos (P50,000).\nARTICLE XII\nTRANSITORY PROVISIONS"}},{"id":"PH-H5767-A44","no":44,"noLabel":{"en":"Section 44."},"text":{"en":"Moratorium on Eviction and Demolition. - There shall be a moratorium on the eviction of all program beneficiaries and on the demolition of their houses or dwelling units for a period of three (3) years from the effectivity of this Act: Provided, That the moratorium shall not apply to those persons who have constructed their structures after the effectivity of this Act and for cases enumerated in Section 28 hereof.\nARTICLE XIII\nCOMMON PROVISIONS"}},{"id":"PH-H5767-A45","no":45,"noLabel":{"en":"Section 45."},"text":{"en":"Penalty Clause. - Any person who violates any provision of this Act shall be imposed the penalty of not more than six (6) years of imprisonment or a fine of not less than Five thousand pesos (P5,000) but not more than One hundred thousand pesos (P100,000), or both, at the discretion of the court: Provided, That, if the offender is a corporation, partnership, association or other juridical entity, the penalty shall be imposed on the officer or officers of said corporation, partnership, association or juridical entity who caused the violation."}},{"id":"PH-H5767-A46","no":46,"noLabel":{"en":"Section 46."},"text":{"en":"Appropriations. - The amount necessary to carry out the purposes of this Act shall be included in the annual budget of implementing agencies in the General Appropriations Act of the year following its enactment into law and every year thereafter."}},{"id":"PH-H5767-A47","no":47,"noLabel":{"en":"Section 47."},"text":{"en":"Separability Clause . - If for any reason, any provision of this Act is declared invalid or unconstitutional, the remaining provisions not affected thereby shall continue to be in full force and effect."}},{"id":"PH-H5767-A48","no":48,"noLabel":{"en":"Section 48."},"text":{"en":"Repealing Clause . - All laws, decrees, executive orders, proclamations, rules and regulations, and other issuances, or parts thereof which are inconsistent with the provisions of this Act, are hereby repealed or modified accordingly."}},{"id":"PH-H5767-A49","no":49,"noLabel":{"en":"Section 49."},"text":{"en":"Effectivity Clause. - This Act shall take effect upon its publication in at least two (2) national newspapers of general circulation."}}],"pack":"ph-p82","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act to Provide for a Comprehensive and Continuing Urban Development and Housing Program, Establish the Mechanism for Its Implementation, and for Other Purposes","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H5768"] = {"id":"PH-H5768","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1992/ra_7280_1992.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":"设立Talisay市","en":"An Act Declaring March 26 of Every Year a Special Nonworking Holiday in the Municipality of Talisay, Province of Cebu","orig":"An Act Declaring March 26 of Every Year a Special Nonworking Holiday in the Municipality of Talisay, Province of Cebu"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 7280","issuingBody":"Congress of the Philippines","promulgatedDate":"1992-03-24","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1992/ra_7280_1992.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H5768-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"March 26 of every year is hereby declared a special nonworking holiday in the Municipality of Talisay, Province of Cebu."}},{"id":"PH-H5768-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect upon its approval."}}],"pack":"ph-p82"};
  FT["PH-H5769"] = {"id":"PH-H5769","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1992/ra_7281_1992.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":"宣布每年 3 月 10 日为阿布拉省特别非工作假日（名称为阿布拉日）的法案","en":"An Act Declaring March Ten of Every Year as a Special Nonworking Holiday in the Province of Abra to Be Known as Abra Day","orig":"An Act Declaring March Ten of Every Year as a Special Nonworking Holiday in the Province of Abra to Be Known as Abra Day"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 7281","issuingBody":"Congress of the Philippines","promulgatedDate":"1992-03-24","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1992/ra_7281_1992.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H5769-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"March Ten of every year is hereby declared as a special nonworking holiday in the Province of Abra to commemorate the creation of the Province, to be known as Abra Day."}},{"id":"PH-H5769-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect upon its approval."}}],"pack":"ph-p82","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Declaring March Ten of Every Year as a Special Nonworking Holiday in the Province of Abra to Be Known as Abra Day","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
