  FT["PH-H5777"] = {"id":"PH-H5777","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1992/ra_7289_1992.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":"将塔克洛班市医疗中心的名称正式变更为东米沙鄢区域医疗中心的法案","en":"An Act Changing the Name of the Tacloban City Medical Center to Eastern Visayas Regional Medical Center","orig":"An Act Changing the Name of the Tacloban City Medical Center to Eastern Visayas Regional Medical Center"},"level":"law","status":"active","topics":["health"],"docNumber":"Republic Act No. 7289","issuingBody":"Congress of the Philippines","promulgatedDate":"1992-03-24","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1992/ra_7289_1992.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H5777-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The name of the Tacloban City Medical Center in Tacloban City is hereby changed to Eastern Visayas Regional Medical Center."}},{"id":"PH-H5777-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect upon its approval."}}],"pack":"ph-p82","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Changing the Name of the Tacloban City Medical Center to Eastern Visayas Regional Medical Center","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H5778"] = {"id":"PH-H5778","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1992/ra_7290_1992.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":"将保和省伊纳邦阿市镇达戈霍伊市镇医院的名称变更为Francisco Dagohoy市镇医院的法案","en":"An Act Changing the Name of the Dagohoy Municipal Hospital in the Municipality of Inabanga, Province of Bohol, to Francisco Dagohoy Municipal Hospital","orig":"An Act Changing the Name of the Dagohoy Municipal Hospital in the Municipality of Inabanga, Province of Bohol, to Francisco Dagohoy Municipal Hospital"},"level":"law","status":"active","topics":["health"],"docNumber":"Republic Act No. 7290","issuingBody":"Congress of the Philippines","promulgatedDate":"1992-03-24","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1992/ra_7290_1992.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H5778-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The name of the Dagohoy Municipal Hospital in the Municipality of Inabanga, Province of Bohol, is hereby changed to Francisco Dagohoy Municipal Hospital."}},{"id":"PH-H5778-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect upon its approval."}}],"pack":"ph-p82","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Changing the Name of the Dagohoy Municipal Hospital in the Municipality of Inabanga, Province of Bohol, to Francisco Dagohoy Municipal Hospital","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H5779"] = {"id":"PH-H5779","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1992/ra_7291_1992.html","fetchedAt":"2026-10-06","articleCount":3,"structureMode":"ARTICLE","title":{"zh":"恢复菲律宾退伍军人联合会在第2640号共和国法下曾享有的税收与关税优惠的法案","en":"An Act Restoring the Tax and Duty Incentives Previously Enjoyed By the Veterans Federation of the Philippines Under Republic Act Numbered Twenty-six Hundred and Forty","orig":"An Act Restoring the Tax and Duty Incentives Previously Enjoyed By the Veterans Federation of the Philippines Under Republic Act Numbered Twenty-six Hundred and Forty"},"level":"law","status":"active","topics":["tax","defence"],"docNumber":"Republic Act No. 7291","issuingBody":"Congress of the Philippines","promulgatedDate":"1992-03-24","completenessNote":"全文，共 3 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1992/ra_7291_1992.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H5779-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Notwithstanding the provisions of Executive Order No. 93 and Presidential Decree No. 1931, the tax and duty incentives previously enjoyed by the Veterans Federation of the Philippines under Republic Act Numbered Twenty-six hundred and forty are hereby restored: Provided, That no dollar outflow shall in any manner be involved in the exchange of transaction."}},{"id":"PH-H5779-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"All laws, decrees, orders, issuances, rules and regulations, or parts thereof, inconsistent with this Act are hereby repealed or modified accordingly."}},{"id":"PH-H5779-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"This Act shall take effect upon its approval."}}],"pack":"ph-p82","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Restoring the Tax and Duty Incentives Previously Enjoyed By the Veterans Federation of the Philippines Under Republic Act Numbered Twenty-six Hundred and Forty","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H5780"] = {"id":"PH-H5780","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1992/ra_7292_1992.html","fetchedAt":"2026-10-06","articleCount":11,"structureMode":"ARTICLE","title":{"zh":"设立Sipocot市","en":"An Act Converting the Sipocot National School of Arts and Trades in the Municipality of Sipocot, Province of Camarines Sur, Into the Bicol Institute of Science and Technology, and Appropriating Funds Therefor","orig":"An Act Converting the Sipocot National School of Arts and Trades in the Municipality of Sipocot, Province of Camarines Sur, Into the Bicol Institute of Science and Technology, and Appropriating Funds Therefor"},"level":"law","status":"active","topics":["education","culture"],"docNumber":"Republic Act No. 7292","issuingBody":"Congress of the Philippines","promulgatedDate":"1992-03-24","completenessNote":"全文，共 11 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1992/ra_7292_1992.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H5780-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The Sipocot National School of Arts and Trades located in the Municipality of Sipocot, Province of Camarines Sur, is hereby converted into the Bicol Institute of Science and Technology, hereinafter referred to as the Institute."}},{"id":"PH-H5780-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The Institute shall primarily provide higher technological, professional and vocational training consistent with the goals for local, regional and national development. It shall also promote research and provide progressive leadership in the various disciplines and areas of specialization. The Institute shall offer undergraduate courses in the field of arts and trades education and such other courses as may be necessary to meet regional and national needs for trained manpower."}},{"id":"PH-H5780-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"No student shall be denied admission to the Institute by reason of sex, ethnic consideration, or religious belief or affiliation."}},{"id":"PH-H5780-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"The Institute shall be under the direct supervision of the Department of Education, Culture and Sports and shall be headed by a vocational school superintendent II."}},{"id":"PH-H5780-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"The vocational school superintendent II shall have the following powers and duties:\na. To recommend appropriation to the Department of Education, Culture and Sports through the regional office for the operation and maintenance of the Institute;\nb. To recommend the confirmation of titles or degrees in the fields of study stated in Section 2 of this Act to successful candidates for graduation;\nc. To recommend the confirmation of certificates and diplomas to successful candidates for graduation on courses other than degree courses;\nd. To recommend appointments submitted by the screening committee to the regional office;\ne. To recommend the curricula and rules of discipline drawn by the department heads and supervisors;\nf. To provide scholarships to faculty and staff showing special evidence of merit; and\ng. To receive in trust legacies, gifts and donations of real and personal property of all kinds and to administer the same for the benefit of the Institute or of the departments, or for aid to any student or students in accordance with the direction and instruction of the donor or in such other manner as the superintendent may determine, subject to budgeting, accounting and auditing law, rules and regulations."}},{"id":"PH-H5780-A6","no":6,"noLabel":{"en":"Section 6."},"text":{"en":"The faculty of the Sipocot National School of Arts and Trades as well as other personnel shall be absorbed by the new Institute: Provided, That the incumbent vocational school administrator shall be appointed as the first vocational school superintendent II."}},{"id":"PH-H5780-A7","no":7,"noLabel":{"en":"Section 7."},"text":{"en":"The body of teachers, instructors, master teachers, and heads of department shall constitute the faculty of the Institute."}},{"id":"PH-H5780-A8","no":8,"noLabel":{"en":"Section 8."},"text":{"en":"The faculty and other personnel of the Institute shall be covered by the Civil Service Law, rules and regulations."}},{"id":"PH-H5780-A9","no":9,"noLabel":{"en":"Section 9."},"text":{"en":"All the personnel, assets and properties including building sites, and the improvements thereon, obligations, funds and appropriations of the Sipocot National School of Arts and Trades are hereby transferred to the Bicol Institute of Science and Technology."}},{"id":"PH-H5780-A10","no":10,"noLabel":{"en":"Section 10."},"text":{"en":"The amount needed for the implementation of this Act shall be provided in the General Appropriations Act of the year following its enactment into law: Provided, That the new name Bicol Institute of Science and Technology shall take effect upon the approval of this Act. Thereafter, such sums as may be necessary for the continued operation and maintenance of the Institute shall be included in subsequent General Appropriations Acts."}},{"id":"PH-H5780-A11","no":11,"noLabel":{"en":"Section 11."},"text":{"en":"This Act shall take effect upon its approval."}}],"pack":"ph-p82"};
  FT["PH-H5781"] = {"id":"PH-H5781","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1992/ra_7293_1992.html","fetchedAt":"2026-10-06","articleCount":17,"structureMode":"ARTICLE","title":{"zh":"进一步修订第 6030 号共和国法（经第 6531 号共和国法修正），将 Pilipino 电话公司的特许经营权期限自期满起再延长二十五年并为其他目的法案","en":"An Act Further Amending Republic Act Numbered Six Thousand Thirty, as Amended By Republic Act Numbered Six Thousand Five Hundred Thirty-one, Entitled \"An Act Granting the Pilipino Telephone Corporation a Franchise to Install, Operate and Maintain Telephone Systems in Certain Areas Throughout the Philippines,\" Extending the Term of Its Franchise to Another Twenty-five Years From Date of Its Expiration, and for Other Purposes","orig":"An Act Further Amending Republic Act Numbered Six Thousand Thirty, as Amended By Republic Act Numbered Six Thousand Five Hundred Thirty-one, Entitled \"An Act Granting the Pilipino Telephone Corporation a Franchise to Install, Operate and Maintain Telephone Systems in Certain Areas Throughout the Philippines,\" Extending the Term of Its Franchise to Another Twenty-five Years From Date of Its Expiration, and for Other Purposes"},"level":"law","status":"active","topics":["investment"],"docNumber":"Republic Act No. 7293","issuingBody":"Congress of the Philippines","promulgatedDate":"1992-03-27","completenessNote":"全文，共 17 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1992/ra_7293_1992.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。 源文存在同号重出的条款（第 1 条）：该处官方页面确有两段均标同一 Section 号，本库照录其 `no` 值（不改动官方编号），条文 `id` 以 `_2`「_3」后缀保证唯一。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H5781-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Amendment to the Title of Republic Act No. 6030, as Amended. - The title of Republic Act Numbered Six thousand thirty, as amended by Republic Act Numbered Six thousand five hundred thirty-one, is hereby further amended to read as follows:\n\"An Act granting the Pilipino Telephone Corporation a franchise to install, operate and maintain telecommunications systems and services in and between provinces, cities and municipalities throughout the Philippines and between the Philippines and other countries and territories.\""}},{"id":"PH-H5781-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"Amendment to Section One. - Section 1 of the same Act, as amended, is hereby further amended to read as follows:\n\""}},{"id":"PH-H5781-A1-d2","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Subject to the conditions established in this Act and the provisions of Commonwealth Act Numbered One hundred forty-six, as amended, and of the Constitution, applicable thereto, there is hereby granted to the Pilipino Telephone Corporation, hereinafter called the grantee, its successors or assigns, for a period of twenty-five (25) years from the approval of this Act, the right, privilege and authority to install, operate and maintain telecommunications systems and services in and between provinces, cities and municipalities throughout the Philippines and between the Philippines and other countries and territories, as public interest may warrant. The grantee is authorized to carry on the business of transmitting and receiving messages, signals, conversations and pictures by means of electricity, laser beams, microwave, or other means now known to science or which in the future may be developed for the transmission of telecommunications, conversations, messages, pictures, and signals in and between the said provinces, cities and municipalities, and connect systems of other countries and for the purpose of operating said telephone systems and transmitting telecommunications, messages, conversations, pictures, and signals by means of electricity, laser beams, microwave, and other means now known to science or which in the future may be developed; to construct, maintain and operate and use all apparatus, conduits, appliances, receivers, transmitters, antennaes, balloons, satellites, and equipment necessary for the transmission of messages, conversations, pictures, and signals by means of electricity, laser beams, microwave, and other means now known to science or which in the future may be developed; to erect poles, structures, string wires, build conduits, lay cables, float balloons; to construct, maintain, and use such other approved and generally accepted means of electrical, laser beams, microwave, and other means, conduction in, on, over, or under the public roads, government right-of-way, lands, bridges, rivers, streets, lanes and sidewalks of provinces, cities, and municipalities, and overhead or underground or submarine lines or on the surface of the ground or in the atmosphere as may be necessary and best adapted to said transmission and reception: Provided, however, That all cables laid, all poles erected and all conduits constructed or used by the grantee, its successors or assigns, shall be located in places designated by said grantee, with the approval of the provincial or municipal board or council of the province, city or municipality concerned, and poles shall be erected in a workmanlike manner to the satisfaction of the said body: Provided, further, That the poles erected, wires and cables strung or conduits laid by virtue of this franchise shall be so placed as not to impair the efficient and effective transmission of messages and signals by any other company whose wires and cables are strung, or whose conduits are actually laid at the time that the poles are to be erected, wires and cables strung and conduits laid under and by virtue of this franchise: Provided, finally, That poles erected by the grantee shall be of such a height of at least ten feet (10) above the level of the ground providing a height of at least fifteen feet (15) in crossing roads or streets and shall be so placed as not to be a danger to public safety in accordance with a plan approved by the Secretary of Transportation and Communications.\""},"dupIndex":2},{"id":"PH-H5781-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"Amendment to Section Sixteen. - Section 16 of the same Act, as amended, is hereby further amended to read as follows:\n\""}},{"id":"PH-H5781-A16","no":16,"noLabel":{"en":"Section 16."},"text":{"en":"The grantee or its successors may install, maintain, operate, purchase, lease, or manage such telephone stations, lines, cable or telecommunications systems and services as is or are, convenient or necessary to carry out the purpose of this franchise and for that purpose the grantee or its successors, for the duration of this franchise, is hereby authorized to acquire, own, operate and manage by management contract, purchase, merger, consolidation, exchange of its shares of stock, telecommunications systems and services now owned or may hereafter be owned by private persons, firms, corporations, or partnerships, provinces, cities, municipalities and government-owned or -controlled corporations which are all hereby given full power and authority to do and perform any and all acts to effect the authorized management, purchase, consolidation, merger, exchange of shares of stock or other means of acquisitions of the telecommunications systems and services respectively owned or operated by them by the grantee under such terms and conditions as they and the grantee may mutually agree upon: Provided, however, That the grantee, its successors or assigns, shall not, without the permission of the National Telecommunications Commission first had, install, maintain, manage, operate and purchase or lease such stations, lines, cables or telecommunications systems and services.\""}},{"id":"PH-H5781-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"Extension of Term of Franchise . - The term of the franchise granted to the Pilipino Telephone Corporation as herein amended is hereby extended, under the same terms and conditions therein prescribed except as herein provided, for twenty-five (25) years from August 3, 1994."}},{"id":"PH-H5781-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"Responsibility to the Public. - The grantee shall supply telephone service in any municipality in the Philippines where it has established a local telephone exchange to any applicant therefor; and as between such applicant and other like applicants, in the order of the date of their applications up to the limit of the capacity of its telephone exchange as determined by the National Telecommunications Commission in any application made by the grantee for the construction of the relevant telecommunications systems, and should the demand for the telephone service at any time increase beyond the capacity of its local telephone exchange to supply the same, the capacity of said telephone exchange shall be increased by the grantee to meet such demand, in accordance with the decision of the Commission: Provided, That, in case the point at which the telephone service to be supplied is more than fifty meters (50) from the local exchange operated by the grantee, the latter shall not be obliged to furnish said service, unless the applicant for the telephone service defrays the actual expenses for the installation of the telecommunications apparatus necessary for such service and in such cases the National Telecommunications Commission may extend the time within which the grantee shall furnish such service.\nFor the purpose of installing, operating and maintaining its telecommunications lines, it shall be lawful for the grantee to make excavations or lay conduits in any of the public places, highways, streets, lanes, alleys, avenues, sidewalks, and bridges of said municipalities, forest reserves and other similar property of the Government of the Philippines or any of its branches or instrumentalities: Provided, however, That any public place, highway, street, lane, alley, avenue, sidewalk or bridge disturbed, altered, or changed by reason of the installation, operation and maintenance of said telecommunications lines underground shall be repaired and replaced in a workmanlike manner by the said grantee to the satisfaction of the Department of Public Works and Highways. Should the grantee, its successors or assigns, after the lapse of thirty (30) days from receipt of notice from the proper authority, fail, refuse, or neglect to repair or replace any part of a public place, road, highway, street, lane, alley, avenue, sidewalk or bridge altered, changed, or disturbed by said grantee, then the Department of Public Works and Highways shall have the right to have the same repaired and placed in good order and condition at the cost and expense of the grantee.\nThe grantee shall operate and maintain all its stations, lines, cables, systems and equipment for the transmission and reception of messages, signals and pulses in a satisfactory manner at all times and whenever required by the National Telecommunications Commission in the interest of the public good and as far as practicable modify, improve or change such stations, lines, cables, systems, and equipment to keep abreast with the advances in science and technology."}},{"id":"PH-H5781-A6","no":6,"noLabel":{"en":"Section 6."},"text":{"en":"Tax Provisions. - The grantee shall be liable to pay the same taxes on its real estate, buildings, and personal property exclusive of this franchise as other persons or corporations are now or hereafter may be required by law to pay. In addition thereto, the grantee shall pay to the Bureau of Internal Revenue each year, within thirty (30) days after the audit and approval of the accounts, three per centum (3%) of all gross receipts of the telephone or other telecommunications businesses transacted under this franchise by the grantee, and the said percentage shall be in lieu of all taxes on this franchise or earnings thereof: Provided, That the grantee shall continue to be liable for income taxes payable under Title II of the National Internal Revenue Code pursuant to Section 2 of Executive Order No. 72 unless the latter enactment is amended or repealed, in which case the amendment or repeal shall be applicable thereto.\nThe grantee shall file the return with and pay the tax due thereon to the Commissioner of Internal Revenue or his duly authorized representative in accordance with the National Internal Revenue Code and the return shall be subject to audit by the Bureau of Internal Revenue."}},{"id":"PH-H5781-A7","no":7,"noLabel":{"en":"Section 7."},"text":{"en":"Listing of Shares. - The grantee shall list, subject to the requirements of the Securities and Exchange Commission and the stock exchange concerned, and make a public offering through the stock exchange of the shares representing at least thirty per centum (30%) of its authorized capital stock in any securities exchange in the Philippines within five (5) years from the effectivity of this Act."}},{"id":"PH-H5781-A8","no":8,"noLabel":{"en":"Section 8."},"text":{"en":"Interconnection. - The grantee is hereby authorized to connect its telecommunications systems installed, operated and maintained by any other duly authorized person or entity in the Philippines for the purpose of providing telecommunications services to the public under such terms and conditions mutually agreed upon by the parties: Provided, That the terms and conditions of such interconnection shall be subject to the approval of the National Telecommunications Commission: Provided, further, That, if the parties fail to agree within a period of ninety (90) days from the initial date of interconnection proposal, any interconnection shall be made in accordance with such terms and conditions mandated by the National Telecommunications Commission."}},{"id":"PH-H5781-A9","no":9,"noLabel":{"en":"Section 9."},"text":{"en":"Warranty in Favor of National and Local Governments. - The grantee shall hold the national, provincial, city and municipal governments harmless from all claims, accounts, demands or actions arising out of accidents or injuries, whether to property or to persons, caused by the installation and operation of the telecommunications systems of the grantee."}},{"id":"PH-H5781-A10","no":10,"noLabel":{"en":"Section 10."},"text":{"en":"Rates for Services. - The rates to be charged to the subscribers for telephone service and other telecommunications services, whether flat rates or measured rates, are subject to the approval of the National Telecommunications Commission."}},{"id":"PH-H5781-A11","no":11,"noLabel":{"en":"Section 11."},"text":{"en":"Sale, Lease, Transfer, Assignment, Usufruct, etc. - The grantee shall not lease, transfer, grant the usufruct of, sell or assign this franchise and the rights or privileges acquired thereunder to any person, firm, company, corporation, or legal entity, nor shall the controlling interest in the grantee be transferred whether as a whole or in parts and whether simultaneously or contemporaneously, to any such private person, firm, company, corporation or entity without the prior approval of the Congress of the Philippines.\nAny person or entity to which this franchise is sold, transferred or assigned shall be subject to all the conditions, terms, restrictions and limitations of this Act.\nThe grantee may install, operate, maintain, purchase or lease such telecommunications apparatus and systems as is or are convenient or essential to efficiently carry out the purpose of this franchise: Provided, That in such cases it has the permission of the National Telecommunications Commission first had."}},{"id":"PH-H5781-A12","no":12,"noLabel":{"en":"Section 12."},"text":{"en":"Annual Report to Congress. - The grantee shall file a detailed annual report to the Congress of the Philippines with respect to its programs, operations and/or compliance with the terms and conditions of the franchise."}},{"id":"PH-H5781-A13","no":13,"noLabel":{"en":"Section 13."},"text":{"en":"Right of Government . - The Government shall have the privilege of using without compensation the poles of the grantee to attach, install, operate and maintain wires of its telegraph system: Provided however, That the Bureau of Posts shall have the right to place additional crossarms and wires on the poles of the grantee by paying a compensation, the rate of which is to be agreed upon by the Postmaster General and the grantee: Provided, further, That, in case of disagreement as to the rate of contract rental, the same shall be fixed by the National Telecommunications Commission.\nMunicipalities shall also have the privilege of using, without compensation, the poles of the grantee to attach, install, operate and maintain wires of local police and fire alarm system; but the wires of such telegraph lines, police or fire alarm shall be placed and strung in such manner as to cause no interference with or damage to the wires or the telephone service of the grantee."}},{"id":"PH-H5781-A14","no":14,"noLabel":{"en":"Section 14."},"text":{"en":"Alteration or Repeal of Franchise. - This franchise shall be subject to amendment, alteration or repeal by Congress. All lands or right to use or occupy lands secured by virtue of this franchise shall revert upon its termination to the national, provincial or municipal governments concerned which were the owners thereof on the date of the granting of this franchise."}},{"id":"PH-H5781-A15","no":15,"noLabel":{"en":"Section 15."},"text":{"en":"Effectivity Clause. - This Act shall take effect fifteen (15) days from the date of its publication in at least two (2) newspapers of general circulation in the Philippines."}}],"pack":"ph-p82","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Further Amending Republic Act Numbered Six Thousand Thirty, as Amended By Republic Act Numbered Six Thousand Five Hundred Thirty-one, Entitled \"An Act Granting the Pilipino Telephone Corporation a Franchise to Install, Operate and Maintain Telephone Systems in Certain Areas Throughout the Philippines,\" Extending the Term of Its Franchise to Another Twenty-five Years From Date of Its Expiration, and for Other Purposes","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H5782"] = {"id":"PH-H5782","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1992/ra_7294_1992.html","fetchedAt":"2026-10-06","articleCount":17,"structureMode":"ARTICLE","title":{"zh":"授予 Smart 信息技术公司在菲律宾全境设立、安装、维护和运营综合电信、计算机与电子服务及站点用于公共电信并为其他目的法案","en":"An Act Granting Smart Information Technologies, Inc. (Smart) a Franchise to Establish, Install, Maintain, Lease and Operate Integrated Telecommunications/ Computer/Electronic Services, and Stations Throughout the Philippines for Public Domestic and International Telecommunications, and for Other Purposes","orig":"An Act Granting Smart Information Technologies, Inc. (Smart) a Franchise to Establish, Install, Maintain, Lease and Operate Integrated Telecommunications/ Computer/Electronic Services, and Stations Throughout the Philippines for Public Domestic and International Telecommunications, and for Other Purposes"},"level":"law","status":"active","topics":["investment","data"],"docNumber":"Republic Act No. 7294","issuingBody":"Congress of the Philippines","promulgatedDate":"1992-03-27","completenessNote":"全文，共 17 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1992/ra_7294_1992.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H5782-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Nature and Scope of Franchise. - Subject to the provisions of the Constitution and applicable laws, rules and regulations, there is hereby granted to the Smart Information Technologies, Inc., hereunder referred to as the grantee, its successors or assigns a franchise to establish, install, maintain, lease and operate integrated telecommunications/computer/electronic services, and fixed and mobile stations throughout the Philippines for public domestic and international telecommunications and to install corresponding transmitting and receiving stations at such places in the Philippines as it may consider necessary and convenient."}},{"id":"PH-H5782-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"Manner of Operation of Stations or Facilities. - The stations of the grantee shall be constructed and operated in a manner as will at most result only in the minimum interference on the wavelengths or frequencies of the existing stations or other stations which may be established in accordance with law of other telecommunications services grantees, without in any way diminishing its own right to use its selected wavelengths or frequencies and the quality of transmission or reception thereon as should maximize rendition of the grantee's services and/or the availability thereof."}},{"id":"PH-H5782-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"Prior Approval of the National Telecommunications Commission. - The grantee shall secure from the National Telecommunications Commission the appropriate permits, licenses and certificates for its stations and shall not use any frequency in the radio spectrum without having been authorized by the Commission."}},{"id":"PH-H5782-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"Responsibility to the Public. - The grantee shall conform to the ethics of honest enterprise and shall not use its stations for obscene or indecent transmissions, or for the dissemination of deliberately false information or willful misrepresentation, or assist in subversive or treasonable acts."}},{"id":"PH-H5782-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"Rates for Services. - The subscription charges and rates for services that the grantee shall offer to the public shall be subject to the approval of the National Telecommunications Commission or its legal successors."}},{"id":"PH-H5782-A6","no":6,"noLabel":{"en":"Section 6."},"text":{"en":"Right of Government. - The President of the Philippines, in times of war, rebellion, public peril, calamity, emergency, disaster or disturbance of peace and order, may take over and operate the stations, transmitter systems, facilities and equipment of the grantee, temporarily suspend the operation of any station in the interest of public safety, security and public welfare, or authorize the temporary use and operation thereof by any agency of the Government, upon due compensation to the grantee, for the use of said stations, transmitter systems, facilities and equipment during the period when they shall be so operated."}},{"id":"PH-H5782-A7","no":7,"noLabel":{"en":"Section 7."},"text":{"en":"Term of Franchise. - This franchise shall be for a term of twenty-five (25) years from the date of approval of this Act, unless sooner revoked or cancelled. In the event the grantee fails to operate continuously for two (2) years, this franchise shall be deemed ipso facto revoked."}},{"id":"PH-H5782-A8","no":8,"noLabel":{"en":"Section 8."},"text":{"en":"Acceptance and Compliance. - Acceptance of this franchise shall be given in writing within sixty (60) days after approval of this Act. The grantee shall operate telecommunications systems for which this franchise is granted within two (2) years from the date of its acceptance in writing of this franchise. Refusal or failure to accept the franchise or to operate within the prescribed period shall render the franchise void."}},{"id":"PH-H5782-A9","no":9,"noLabel":{"en":"Section 9."},"text":{"en":"Tax Provisions. - The grantee, its successors or assigns shall be liable to pay the same taxes on their real estate, buildings and personal property, exclusive of this franchise, as other persons or corporations which are now or hereafter may be required by law to pay. In addition thereto, the grantee, its successors or assigns shall pay a franchise tax equivalent to three percent (3%) of all gross receipts of the business transacted under this franchise by the grantee, its successors or assigns and the said percentage shall be in lieu of all taxes on this franchise or earnings thereof: Provided, That the grantee, its successors or assigns shall continue to be liable for income taxes payable under Title II of the National Internal Revenue Code pursuant to Section 2 of Executive Order No. 72 unless the latter enactment is amended or repealed, in which case the amendment or repeal shall be applicable thereto.\nThe grantee shall file the return with and pay the tax due thereon to the Commissioner of Internal Revenue or his duly authorized representative in accordance with the National Internal Revenue Code and the return shall be subject to audit by the Bureau of Internal Revenue."}},{"id":"PH-H5782-A10","no":10,"noLabel":{"en":"Section 10."},"text":{"en":"Warranty in Favor of National and Local Governments. - The grantee shall hold the national, provincial and municipal governments of the Philippines harmless from all claims, accounts, demands or actions arising out of accidents or injuries, whether to property or to persons, caused by the construction or operation of the stations, systems, facilities and equipment of the grantee."}},{"id":"PH-H5782-A11","no":11,"noLabel":{"en":"Section 11."},"text":{"en":"Sale, Lease, Transfer, Usufruct, etc. - The grantee shall not lease, transfer, grant the usufruct of, sell or assign the franchise herein granted or the rights and privileges acquired thereunder to any person, firm, company, corporation or entity, nor merge with any corporation or entity without the prior approval of the Congress of the Philippines. Neither shall the controlling interest in the grantee be transferred, whether as a whole or in part and whether simultaneously or contemporaneously, to any such person, firm, company, corporation or entity without the prior approval of the Congress of the Philippines. Any person or entity to which the franchise herein granted is validly sold, transferred or assigned shall be subject to the same conditions, terms, restrictions and limitations of this Act."}},{"id":"PH-H5782-A12","no":12,"noLabel":{"en":"Section 12."},"text":{"en":"General Telecommunications Policy Law. - The grantee shall comply with and be subject to the provisions of a general telecommunications policy law that may hereafter be enacted."}},{"id":"PH-H5782-A13","no":13,"noLabel":{"en":"Section 13."},"text":{"en":"Listing of Shares. - The grantee shall list, subject to the requirements of the Securities and Exchange Commission and the stock exchange concerned, and make a public offering through the stock exchange of the shares representing at least thirty per centum (30%) of its authorized capital stock in any securities exchange in the Philippines within two (2) years from the effectivity of this Act."}},{"id":"PH-H5782-A14","no":14,"noLabel":{"en":"Section 14."},"text":{"en":"Separability Clause . - If any of the sections or provisions of this Act is held invalid, all the other provisions not affected thereby shall remain valid."}},{"id":"PH-H5782-A15","no":15,"noLabel":{"en":"Section 15."},"text":{"en":"Repealability and Non-exclusivity Clauses. - The franchise herein granted shall be subject to amendment, alteration or repeal by the Congress of the Philippines when the public interest so requires and shall not be interpreted as an exclusive grant of the privileges herein provided for."}},{"id":"PH-H5782-A16","no":16,"noLabel":{"en":"Section 16."},"text":{"en":"Reportorial Requirement. - The grantee shall submit an annual report to the Congress of the Philippines on its compliance with the terms and conditions of the franchise and on its operations within sixty (60) days from the end of every year."}},{"id":"PH-H5782-A17","no":17,"noLabel":{"en":"Section 17."},"text":{"en":"Effectivity Clause. - This Act shall take effect fifteen (15) days from the date of its publication in at least two (2) newspapers of general circulation in the Philippines."}}],"pack":"ph-p82","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Granting Smart Information Technologies, Inc. (Smart) a Franchise to Establish, Install, Maintain, Lease and Operate Integrated Telecommunications/ Computer/Electronic Services, and Stations Throughout the Philippines for Public Domestic and International Telecommunications, and for Other Purposes","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H5783"] = {"id":"PH-H5783","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1992/ra_7295_1992.html","fetchedAt":"2026-10-06","articleCount":16,"structureMode":"ARTICLE","title":{"zh":"授予 Bright Star 广播网络公司在菲律宾为商业目的建设、安装、运营和维护广播电视站并为其他目的法案","en":"An Act Granting the Bright Star Broadcasting Network Corporation a Franchise to Construct, Install, Operate and Maintain for Commercial Purposes Radio and Television Broadcasting Stations in the Philippines and for Other Purposes","orig":"An Act Granting the Bright Star Broadcasting Network Corporation a Franchise to Construct, Install, Operate and Maintain for Commercial Purposes Radio and Television Broadcasting Stations in the Philippines and for Other Purposes"},"level":"law","status":"active","topics":["investment","trade"],"docNumber":"Republic Act No. 7295","issuingBody":"Congress of the Philippines","promulgatedDate":"1992-03-26","completenessNote":"全文，共 16 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1992/ra_7295_1992.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H5783-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Nature and Scope of Franchise. - Subject to the provisions of the Constitution and applicable laws, rules and regulations, there is hereby granted to the Bright Star Broadcasting Network Corporation, its successors or assigns and hereunder referred to as the grantee, a franchise to construct, install, operate and maintain for commercial purposes and in the public interest radio and television broadcasting stations in the Philippines with the corresponding technological auxiliaries or facilities, special broadcast and other broadcast distribution services and relay stations, and to install radio communication facilities for the grantee's private use in its broadcast services."}},{"id":"PH-H5783-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"Manner of Operation of Stations or Facilities. - The stations or facilities of the grantee shall be constructed and operated in a manner as will at most result only in the minimum interference on the wavelengths or frequencies of the existing stations or other stations which may be established by law."}},{"id":"PH-H5783-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"Prior Approval of the National Telecommunications Commission. - The grantee shall secure from the National Telecommunications Commission the appropriate permits and licenses for its stations and shall not use any frequency in the radio/television spectrum without having been authorized by the Commission. The Commission, however, shall not unreasonably withhold or delay the grant of any such authority."}},{"id":"PH-H5783-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"Responsibility to the Public. - The grantee shall provide reasonable public service time to enable the Government, through the said broadcasting stations, to reach the population on important public issues; provide at all times sound and balanced programming; promote public participation such as in community programming; assist in the functions of public information and education; conform to the ethics of honest enterprise; and not use its stations for the broadcasting of obscene and indecent language, speech, act or scene, or for the dissemination of deliberately false information or willful misrepresentation to the detriment of the public interest, or to incite, encourage, or assist in subversive or treasonable acts."}},{"id":"PH-H5783-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"Right of Government. - The President of the Philippines, in times of rebellion, public peril, calamity, emergency, disaster or disturbance of peace and order, may temporarily take over and operate the stations of the grantee, temporarily suspend the operation of any station and the interest of public safety, security and public welfare, or authorize the temporary use and operation thereof by any agency of the Government, upon due compensation to the grantee, for the use of said stations during the period when they shall be so operated."}},{"id":"PH-H5783-A6","no":6,"noLabel":{"en":"Section 6."},"text":{"en":"Term of Franchise. - This franchise shall be for a term of twenty-five (25) years from the date of approval of this Act, unless sooner revoked or canceled. In the event the grantee fails to operate continuously for two (2) years, this franchise shall be deemed ipso facto revoked."}},{"id":"PH-H5783-A7","no":7,"noLabel":{"en":"Section 7."},"text":{"en":"Acceptance and Compliance. - Acceptance of this franchise shall be given in writing within sixty (60) days after approval of this Act. Refusal or failure to accept the franchise or to operate within the prescribed period shall render the franchise void."}},{"id":"PH-H5783-A8","no":8,"noLabel":{"en":"Section 8."},"text":{"en":"Tax Provisions . - The grantee, its successors or assigns shall be liable to pay the same taxes on their real estate, buildings and personal property, exclusive of this franchise, as other persons or corporations which are now or hereafter may be required by law to pay. In addition thereto, the grantee, its successors or assigns shall pay a franchise tax equivalent to three percent (3%) of all gross receipts of the radio/television business transacted under this franchise by the grantee, its successor or assigns and the said percentage shall be in lieu of all taxes on this franchise or earnings thereof: Provided, That the grantee, its successors or assigns shall continue to be liable for income taxes payable under Title II of the National Internal Revenue Code pursuant to Section 2 of Executive Order No. 72 unless the latter enactment is amended or repealed, in which case the amendment or repeal shall be applicable thereto.\nThe grantee shall file the return with and pay the tax due thereon to the Commissioner of Internal Revenue or his duly authorized representative in accordance with the National Internal Revenue Code. The return shall be subject to audit by the Bureau of Internal Revenue."}},{"id":"PH-H5783-A9","no":9,"noLabel":{"en":"Section 9."},"text":{"en":"Public Ownership. - In compliance with the constitutional mandate to democratize ownership of public utilities, the herein grantee shall make public offering through the stock exchanges of at least thirty percent (30%) of its common stocks within a period of three (3) years from the date of effectivity of this Act: Provided, That no single person or entity shall be allowed to own more than five percent (5%) of the stock offerings."}},{"id":"PH-H5783-A10","no":10,"noLabel":{"en":"Section 10."},"text":{"en":"Warranty in Favor of National and Local Governments. - The grantee shall hold the national, provincial and municipal governments of the Philippines harmless from all claims, accounts, demands or actions arising out of accidents or injuries, whether to property or to persons, caused by the construction or operation of the stations of the grantee."}},{"id":"PH-H5783-A11","no":11,"noLabel":{"en":"Section 11."},"text":{"en":"Sale, Lease, Transfer, Usufruct, etc . - The grantee shall not lease, transfer, grant the usufruct of, sell or assign this franchise or the rights and privileges acquired thereunder to any person, firm, company, corporation or entity, nor merge with any other corporation or entity without the prior approval of the Congress of the Philippines. Neither shall the controlling interest in the grantee be transferred, whether as a whole or in parts and whether simultaneously or contemporaneously, to any such person, firm, company, corporation or entity without the prior approval of the Congress of the Philippines. Any person or entity to which this franchise is validly sold, transferred or assigned shall be subject to all the same conditions, terms, restrictions and limitations of this Act."}},{"id":"PH-H5783-A12","no":12,"noLabel":{"en":"Section 12."},"text":{"en":"Separability Clause . - If any of the sections or provisions of this Act is held invalid, all the other provisions not affected thereby shall remain valid."}},{"id":"PH-H5783-A13","no":13,"noLabel":{"en":"Section 13."},"text":{"en":"Repealing and Non-exclusivity Clause. - The franchise shall be subject to amendment, alteration or repeal by the Congress of the Philippines when the public interest so requires and shall not be interpreted as an exclusive grant of the privileges herein provided for."}},{"id":"PH-H5783-A14","no":14,"noLabel":{"en":"Section 14."},"text":{"en":"General Broadcast Policy . - The grantee shall comply with and be subject to the provisions of a general broadcast policy law that may hereafter be enacted."}},{"id":"PH-H5783-A15","no":15,"noLabel":{"en":"Section 15."},"text":{"en":"Reportorial Requirement. - The grantee shall submit an annual report to the Congress of the Philippines on its compliance with the terms and conditions of the franchise and on its operations within sixty (60) days from the end of every year."}},{"id":"PH-H5783-A16","no":16,"noLabel":{"en":"Section 16."},"text":{"en":"Effectivity Clause. - This Act shall take effect fifteen (15) days from the date of its publication in at least two (2) newspapers of general circulation in the Philippines."}}],"pack":"ph-p82","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Granting the Bright Star Broadcasting Network Corporation a Franchise to Construct, Install, Operate and Maintain for Commercial Purposes Radio and Television Broadcasting Stations in the Philippines and for Other Purposes","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H5784"] = {"id":"PH-H5784","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1992/ra_7296_1992.html","fetchedAt":"2026-10-06","articleCount":19,"structureMode":"ARTICLE","title":{"zh":"授予 Davao Agritech，Inc. 以 Davao 为主要枢纽设立、运营和维护国内航空喷洒服务的特许经营权法案","en":"An Act Granting Davao Agritech, Inc., a Franchise to Establish, Operate and Maintain Domestic Air Spraying Services With Davao as Its Major Hub","orig":"An Act Granting Davao Agritech, Inc., a Franchise to Establish, Operate and Maintain Domestic Air Spraying Services With Davao as Its Major Hub"},"level":"law","status":"active","topics":["investment"],"docNumber":"Republic Act No. 7296","issuingBody":"Congress of the Philippines","promulgatedDate":"1992-03-26","completenessNote":"全文，共 19 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1992/ra_7296_1992.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H5784-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Nature and Scope of Franchise. - Subject to the provisions of the Constitution and applicable laws, rules and regulations, there is hereby granted to the Davao Agritech, Inc., hereunder referred to as the grantee, its successors or assigns a franchise to establish, operate and maintain domestic air spraying services with Davao as its major hub.\nAir spraying services shall include the maintenance and operation of hangars and aircraft service stations and facilities and other services of similar nature which may be necessary, convenient or useful as an auxiliary to air spraying services.\nThe grantee shall be given the right at its terminals and landing fields, as well as in its aircraft, to construct, operate and maintain stations or transmitting sets for wireless telegraphy and direction findings, and other radio aids to air navigation, using wavelengths in accordance with the rules and regulations issued from time to time by the proper agencies of the Government. The wireless communication facilities shall be used solely for receiving and transmitting weather forecasts and other matters in connection with the grantee's services."}},{"id":"PH-H5784-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"Prior Approval of the Civil Aeronautics Board. - The grantee shall secure from the Civil Aeronautics Board the appropriate permits and licenses for its operations.\nAll aircraft used by the grantee and the flight crew members operating such aircraft shall be licensed by the Government of the Philippines and, together with its accessories and equipment, shall at all times be in airworthy condition. They shall be equipped with radio communication, safety and other equipment and shall be operated and maintained in accordance with the regulations and technical requirements of the Air Transportation Office or such other regulatory bodies as the Government may prescribe for this purpose.\nThe grantee's equipment and the operation of such equipment shall at all times be subject to inspection and regulation by the Air Transportation Office.\nThe grantee shall comply with the provisions of Republic Act Numbered Seven hundred and seventy-six, and the regulations promulgated thereunder from time to time."}},{"id":"PH-H5784-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"Responsibility to the Public. - Excepting cases of force majeure and whenever weather conditions permit, the grantee shall maintain air spraying services within Davao and any and all points and places throughout the Philippines as traffic needs may require."}},{"id":"PH-H5784-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"Rates for Services. - The grantee shall fix just and reasonable rates for its air spraying operation, subject to the regulations and approval of the Civil Aeronautics Board and other proper regulatory agencies of the Government."}},{"id":"PH-H5784-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"Term of Franchise. - This franchise shall be for a term of forty (40) years from the date of the approval of this Act, unless sooner revoked or cancelled. In the event that the grantee fails to operate continuously for two (2) years, this franchise shall be deemed ipso facto revoked."}},{"id":"PH-H5784-A6","no":6,"noLabel":{"en":"Section 6."},"text":{"en":"Landing Facilities. - The grantee may use the landing and other airport facilities on land and water as may be maintained or owned by the Government within the Philippines or the grantee's lines subject to such terms and conditions, restrictions and national policy consideration as the Philippine Government may prescribe and, reciprocally, the Philippine Government shall have the right to use the landing and other airport facilities as may be maintained or owned by the grantee in the Philippines."}},{"id":"PH-H5784-A7","no":7,"noLabel":{"en":"Section 7."},"text":{"en":"Contracts. - The grantee is authorized to enter into air spraying and air spraying maintenance and/or servicing contracts, and such other contracts relating to air spraying activities. The grantee shall give preferential consideration to contracts with the Philippine Government."}},{"id":"PH-H5784-A8","no":8,"noLabel":{"en":"Section 8."},"text":{"en":"Right of Government. - In case of war, insurrection, domestic trouble, public calamity or national emergency, the Philippine Government, upon order of the President, shall have the right to take over and operate the equipment of grantee, paying for its use or damages."}},{"id":"PH-H5784-A9","no":9,"noLabel":{"en":"Section 9."},"text":{"en":"Eminent Domain. - With the approval of the President of the Republic of the Philippines and subject to the limitations and procedures prescribed by law, the grantee shall be authorized to exercise the right of eminent domain as may be reasonably necessary for its stations, landing fields, hangars, docks, ramps, wireless stations and other structures in connection with the grantee's activities.\nNo private property shall be taken for any purpose by the grantee without proper condemnation proceedings and just compensation paid or tendered therefor, and any authority to take and occupy land contained herein shall not apply to the taking, use or occupation of any land except such as is required for the actual purposes for which this franchise is granted."}},{"id":"PH-H5784-A10","no":10,"noLabel":{"en":"Section 10."},"text":{"en":"Warranty in Favor of National and Local Governments. - The grantee shall hold the national, provincial and municipal governments of the Philippines harmless from all claims, accounts, demands or actions arising out of accidents or injuries, whether to property or to persons, caused by the operation of the services under the franchise hereby granted."}},{"id":"PH-H5784-A11","no":11,"noLabel":{"en":"Section 11."},"text":{"en":"Public Equity Participation. - In compliance with the constitutional mandate to democratize ownership of public utilities, the herein grantee shall make a public offering through the stock exchanges of at least thirty percent (30%) of its common stock within a period of ten (10) years from the date of the effectivity of this Act: Provided, That no single person or entity shall be allowed to own more than five percent (5%) of the stock offering."}},{"id":"PH-H5784-A12","no":12,"noLabel":{"en":"Section 12."},"text":{"en":"Tax Provisions. - In consideration of the franchise and rights hereby granted, the grantee shall pay to the Philippine Government during the life of this franchise a franchise tax of five percent (5%) of the gross receipts derived by the grantee from its air spraying operations.\nThe grantee shall, however, be subject to income tax levied under Title II of the National Internal Revenue Code, as amended, and the tax on its real property under existing law."}},{"id":"PH-H5784-A13","no":13,"noLabel":{"en":"Section 13."},"text":{"en":"Interpretation of Franchise. - This franchise shall not be interpreted to mean as an exclusive grant of the privileges herein provided for. However, in the event that any competing individual, partnership, or corporation shall receive a similar permit or franchise with terms and/or provisions more favorable than those herein granted or which tend to place the grantee herein at any disadvantage, then such terms and/or provisions shall be deemed part hereof and shall operate equally in favor of the grantee herein."}},{"id":"PH-H5784-A14","no":14,"noLabel":{"en":"Section 14."},"text":{"en":"Sale, Lease, Transfer, Assignment, Usufruct, etc. - The grantee shall not lease, transfer, grant the usufruct of, sell or assign this franchise and the rights and privileges acquired thereunder to any person, firm, company, corporation or legal entity, nor shall the controlling interest in the grantee be transferred to any such private person, firm, company, corporation or entity without the prior approval of the Congress of the Philippines.\nAny person or entity to which this franchise is sold, transferred or assigned shall be subject to all the conditions, terms, restrictions and limitations of this Act."}},{"id":"PH-H5784-A15","no":15,"noLabel":{"en":"Section 15."},"text":{"en":"Reportorial Requirement. - The grantee shall submit an annual report to the Congress of the Philippines on its compliance with the terms and conditions of the franchise and on its operations within sixty (60) days from the end of every year."}},{"id":"PH-H5784-A16","no":16,"noLabel":{"en":"Section 16."},"text":{"en":"Legislative Amendment. - This franchise is subject to amendment or repeal by the Congress of the Philippines when the common good so requires."}},{"id":"PH-H5784-A17","no":17,"noLabel":{"en":"Section 17."},"text":{"en":"Separability Clause . - If any section or provision of this franchise, as amended, is held or declared unconstitutional or invalid by a competent court in a final judgment, the other sections or provisions hereof shall continue to be in force as if the section or provision so annulled or voided had never been incorporated in this franchise."}},{"id":"PH-H5784-A18","no":18,"noLabel":{"en":"Section 18."},"text":{"en":"Repealing Clause . - All laws, decrees, orders, instructions, and rules and regulations or parts thereof which are inconsistent herewith are hereby repealed or modified accordingly."}},{"id":"PH-H5784-A19","no":19,"noLabel":{"en":"Section 19."},"text":{"en":"Effectivity Clause. - This Act shall take effect fifteen (15) days from the date of its publication in at least two (2) newspapers of general circulation in the Philippines."}}],"pack":"ph-p82","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Granting Davao Agritech, Inc., a Franchise to Establish, Operate and Maintain Domestic Air Spraying Services With Davao as Its Major Hub","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H5785"] = {"id":"PH-H5785","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1992/ra_7297_1992.html","fetchedAt":"2026-10-06","articleCount":16,"structureMode":"ARTICLE","title":{"zh":"授予 Zoe 广播网络公司在吕宋岛建设、安装、运营和维护广播电视站并为其他目的法案","en":"An Act Granting Zoe Broadcasting Network, Inc., a Franchise to Construct, Install, Operate and Maintain Radio and Television Broadcasting Stations in the Island of Luzon and for Other Purposes","orig":"An Act Granting Zoe Broadcasting Network, Inc., a Franchise to Construct, Install, Operate and Maintain Radio and Television Broadcasting Stations in the Island of Luzon and for Other Purposes"},"level":"law","status":"active","topics":["investment"],"docNumber":"Republic Act No. 7297","issuingBody":"Congress of the Philippines","promulgatedDate":"1992-03-26","completenessNote":"全文，共 16 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1992/ra_7297_1992.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H5785-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Nature and Scope of Franchise. - Subject to the provisions of the Constitution and applicable laws, rules and regulations, there is hereby granted to ZOE Broadcasting Network, Inc., its successors or assigns, hereunder referred to as the grantee, a franchise to construct, install, operate and maintain for commercial purposes and in the public interest radio and television stations in the island of Luzon with the corresponding auxiliary, special broadcast and other program and distribution services and relay stations, and to install radio communication facilities for the grantee's private use in its broadcast services."}},{"id":"PH-H5785-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"Manner of Operation of Stations or Facilities. - The stations or facilities of the grantee shall be constructed and operated in a manner as will at most result only in the minimum interference on the wavelengths or frequencies of the other existing stations or stations which may be established by law, without in any way diminishing its own right to use its selected wavelengths or frequencies and the quality of transmission or reception thereon as should maximize rendition of the grantee's and/or the availability thereof."}},{"id":"PH-H5785-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"Prior Approval of the National Telecommunications Commission. - The grantee shall secure from the National Telecommunications Commission the appropriate permits and licenses for its stations and shall not use any frequency in the radio/television spectrum without having been authorized by the Commission."}},{"id":"PH-H5785-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"Responsibility to the Public. - The grantee shall provide adequate public service time to enable the Government, through the said broadcasting stations, to reach the population on important public issues; provide at all times sound and balanced programming; promote public participation such as in community programming; assist in the functions of public information and education; conform to the ethics of honest enterprise; and not use its station for the broadcasting of obscene and indecent language, speech, act or scene, or for the dissemination of deliberately false information or willful misrepresentation or to the detriment of the public interest, or to incite, encourage, or assist in subversive or treasonable acts."}},{"id":"PH-H5785-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"Right of Government. - The President of the Philippines, in times of rebellion, public peril calamity, emergency, disaster or disturbance of peace and order, may temporarily take over the stations of the grantee, temporarily suspend the operation of any station in the interest of public safety, security and public welfare, or authorize the temporary use and operation thereof by any agency of the Government, upon due compensation to the grantee, for the use of the said stations during the period when they shall be so operated."}},{"id":"PH-H5785-A6","no":6,"noLabel":{"en":"Section 6."},"text":{"en":"Term of Franchise. - This franchise shall be for a term of twenty-five (25) years from the date of effectivity of this Act, unless sooner revoked or cancelled. In the event the grantee fails to operate continuously for two (2) years, this franchise shall be deemed ipso facto revoked."}},{"id":"PH-H5785-A7","no":7,"noLabel":{"en":"Section 7."},"text":{"en":"Acceptance and Compliance. - Acceptance of this franchise shall be given in writing sixty (60) days after the approval of this Act. Upon giving such acceptance, the grantee shall exercise the privileges granted under this Act. Nonacceptance shall render the franchise void."}},{"id":"PH-H5785-A8","no":8,"noLabel":{"en":"Section 8."},"text":{"en":"Tax Provisions. - The grantee, its successors or assigns shall be liable to pay the same taxes on its real estate, buildings and personal property, exclusive of this franchise, as other persons or corporations are now or hereafter may be required by law to pay. In addition thereto, the grantee, its successors or assigns shall pay a franchise tax equivalent to three percent (3%) of all gross receipts of the radio/television business transacted under this franchise by the grantee, its successors or assigns and the said percentage shall be in lieu of all taxes on this franchise or earnings thereof: Provided, That the grantee, its successors or assigns shall continue to be liable for income taxes payable under Title II of the National Internal Revenue Code pursuant to Section 2 of Executive Order No. 72 unless the latter enactment is amended or repealed, in which case the amendment or repeal shall be applicable thereto.\nThe grantee shall file the return with and pay the tax due thereon to the Commissioner of Internal Revenue or his duly authorized representative in accordance with the National Internal Revenue Code and the return shall be subject to audit by the Bureau of Internal Revenue."}},{"id":"PH-H5785-A9","no":9,"noLabel":{"en":"Section 9."},"text":{"en":"Self-regulation by and Undertaking of Grantee. - The grantee shall not require any previous censorship of any speech, play, act or scene, or other matter to be broadcast and/or telecast from its stations; but if any such speech, play, act or scene, or other matter should constitute a violation of the law or infringement of a private right, the grantee shall be free from any liability, civil or criminal for such speech, play, act or scene, or other matter: Provided, That the grantee, during any broadcast and/or telecast, shall cut off from the air the speech, play, act or scene, or other matter being broadcast if the tendency thereof is to propose and/or incite treason, rebellion or sedition; or the language used therein or the theme thereof is indecent or immoral; and willful failure to do so shall constitute a valid cause for the cancellation of this franchise."}},{"id":"PH-H5785-A10","no":10,"noLabel":{"en":"Section 10."},"text":{"en":"Warranty in Favor of National and Local Government. - The grantee shall hold the national, provincial and municipal governments of the Philippines harmless from all claims, accounts, demands or actions arising out of accidents or injuries, whether to property or to persons, caused by the construction or operation of the stations of the grantee."}},{"id":"PH-H5785-A11","no":11,"noLabel":{"en":"Section 11."},"text":{"en":"Sale, Lease, Transfer, Usufruct, etc. - The grantee shall not lease, transfer, grant the usufruct of, sell or assign this franchise nor the rights and privileges acquired thereunder to any person, firm, company, corporation, or other commercial or legal entity, nor shall the controlling interest in the grantee be transferred to any such private person, firm, company, corporation or entity without the prior approval of the Congress of the Philippines. Any person or entity to which this franchise is sold, transferred, or assigned shall be subject to all the same conditions, terms, restrictions and limitations of this Act."}},{"id":"PH-H5785-A12","no":12,"noLabel":{"en":"Section 12."},"text":{"en":"Separability Clause . - If any of the sections or provisions of this Act is held invalid, all the other provisions not affected thereby shall remain valid."}},{"id":"PH-H5785-A13","no":13,"noLabel":{"en":"Section 13."},"text":{"en":"Repealing Clause . - This franchise shall be subject to amendment, alteration or repeal by the Congress of the Philippines when the public interest so requires and shall not be interpreted as an exclusive grant of the privileges herein provided for."}},{"id":"PH-H5785-A14","no":14,"noLabel":{"en":"Section 14."},"text":{"en":"General Broadcast Policy. - The grantee shall comply with and be subject to the provisions of a general broadcast policy law that may hereafter be enacted."}},{"id":"PH-H5785-A15","no":15,"noLabel":{"en":"Section 15."},"text":{"en":"Reportorial Requirement. - The grantee shall submit an annual report to the Congress of the Philippines on its compliance with the terms and conditions of the franchise and on its operations within sixty (60) days from the end of every year."}},{"id":"PH-H5785-A16","no":16,"noLabel":{"en":"Section 16."},"text":{"en":"Effectivity Clause. - This Act shall take effect fifteen (15) days from the date of its publication in at least two (2) newspapers of general circulation in the Philippines."}}],"pack":"ph-p82","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Granting Zoe Broadcasting Network, Inc., a Franchise to Construct, Install, Operate and Maintain Radio and Television Broadcasting Stations in the Island of Luzon and for Other Purposes","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H5786"] = {"id":"PH-H5786","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1992/ra_7298_1992.html","fetchedAt":"2026-10-06","articleCount":17,"structureMode":"ARTICLE","title":{"zh":"授予 Omninet Philippines，Inc. 在菲律宾境内外设立、安装、维护、租赁和运营有线及无线电信系统、线路、电路和站点的特许经营权并为其他目的法案","en":"An Act Granting to Omninet Philippines, Inc., a Franchise to Establish, Install, Maintain, Lease and Operate Wire And/Or Wireless Telecommunication Systems, Lines, Circuits and Stations Within and Without the Philippines and for Other Purposes","orig":"An Act Granting to Omninet Philippines, Inc., a Franchise to Establish, Install, Maintain, Lease and Operate Wire And/Or Wireless Telecommunication Systems, Lines, Circuits and Stations Within and Without the Philippines and for Other Purposes"},"level":"law","status":"active","topics":["investment"],"docNumber":"Republic Act No. 7298","issuingBody":"Congress of the Philippines","promulgatedDate":"1992-03-26","completenessNote":"全文，共 17 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1992/ra_7298_1992.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H5786-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Nature and Scope of Franchise. - Subject to the provisions of the Constitution and applicable laws, rules and regulations, there is hereby granted to the Omninet Philippines, Inc., hereunder referred to as the grantee, its successors or assigns a franchise to establish, install, maintain, lease and operate for commercial purposes and in the public interest wire and/or wireless telecommunication systems, lines, circuits and stations, fibre optics, microwave and other facilities that are appropriate to the provision of up-to-date telecommunication facilities within and without the Philippines for public communications including but not limited to two-way radio communications systems, paging, mobile/cellular services, packet switched system, satellite transmit and receive systems, switches, pay television and/or program services by wire or wireless means and other telecommunication systems and their value-added services."}},{"id":"PH-H5786-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"Manner of Operation of Stations or Facilities. - The stations of the grantee shall be constructed and operated in a manner as will at most result only in the minimum interference on the wavelengths or frequencies of the existing stations or other stations which may be established in accordance with law of other telecommunication services grantees, without in any way diminishing its own right to use its selected wavelengths or frequencies and the quality of transmission or reception thereon as should maximize rendition of the grantee's services and/or the availability thereof."}},{"id":"PH-H5786-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"Prior Approval of the National Telecommunications Commission. - The grantee shall secure from the National Telecommunications Commission the appropriate permits and licenses for its stations and shall not use any frequency in the radio spectrum without having been authorized by the Commission."}},{"id":"PH-H5786-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"Responsibility to the Public. - The grantee shall conform to the ethics of honest enterprise and shall not use its stations for obscene or indecent transmissions or for the dissemination of deliberately false information or willful misrepresentation or assist in subversive or treasonable acts."}},{"id":"PH-H5786-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"Rates for Services. - The subscription charges and rates for services, excluding the sale or lease of equipment or units, that the grantee shall offer to the public shall be subject to the approval of the National Telecommunications Commission or its legal successors."}},{"id":"PH-H5786-A6","no":6,"noLabel":{"en":"Section 6."},"text":{"en":"Right of Government. - The President of the Philippines in times of war, rebellion, public peril, calamity, emergency, disaster or disturbance of peace and order, may take over and operate the stations, transmitter systems, facilities and equipment of the grantee temporarily suspend the operation of any station in the interest of public safety, security and public welfare, or authorize the temporary use and operation thereof by any agency of the Government, upon due compensation to the grantee, for the use of said stations, transmitter systems, facilities and equipment during the period when they shall be so operated."}},{"id":"PH-H5786-A7","no":7,"noLabel":{"en":"Section 7."},"text":{"en":"Term of Franchise. - This franchise shall be for a term of twenty-five (25) years from the date of effectivity of this Act, unless sooner revoked or cancelled. In the event the grantee fails to operate continuously for two (2) years, this franchise shall be deemed ipso facto revoked."}},{"id":"PH-H5786-A8","no":8,"noLabel":{"en":"Section 8."},"text":{"en":"Acceptance and Compliance. - Acceptance of the franchise shall be given in writing within sixty (60) days after effectivity of this Act. The grantee shall operate telecommunication systems for which this franchise is granted within two (2) years from the date of its acceptance in writing of this franchise. Refusal or failure to accept the franchise or to operate within the prescribed period shall render the franchise void."}},{"id":"PH-H5786-A9","no":9,"noLabel":{"en":"Section 9."},"text":{"en":"Tax Provisions. - The grantee, its successors or assigns shall be liable to pay the same taxes on their real estate, buildings and personal property, exclusive of this franchise, as other persons or corporations which are now or hereafter may be required by law to pay. In addition thereto, the grantee, its successors or assigns shall pay a franchise tax equivalent to three percent (3%) of all gross receipts of the business transacted under this franchise by the grantee, its successors or assigns and the said percentage shall be in lieu of all taxes on this franchise or earnings thereof: Provided, That the grantee, its successors or assigns shall continue to be liable for income taxes payable under Title II of the National Internal Revenue Code pursuant to Section 2 of Executive Order No. 72 unless the latter enactment is amended or repealed, in which case the amendment or repeal shall be applicable thereto.\nThe grantee shall file the return with and pay the tax due thereon to the Commissioner of Internal Revenue or his duly authorized representative in accordance with the National Internal Revenue Code. The return shall be subject to audit by the Bureau of Internal Revenue."}},{"id":"PH-H5786-A10","no":10,"noLabel":{"en":"Section 10."},"text":{"en":"Warranty in Favor of National and Local Governments. - The grantee shall hold the national, provincial and municipal governments of the Philippines harmless from all claims, accounts, demands or actions arising out of accidents or injuries, whether to property or to persons, caused by the construction or operation of the stations, systems, facilities and equipment of the grantee."}},{"id":"PH-H5786-A11","no":11,"noLabel":{"en":"Section 11."},"text":{"en":"Sale, Lease, Transfer, Usufruct, etc . - The grantee shall not lease, transfer, grant the usufruct of, sell or assign the franchise herein granted or the rights and privileges acquired thereunder to any person, firm, company, corporation or entity nor merge with any corporation or entity without the prior approval of the Congress of the Philippines. Neither shall the controlling interest in the grantee be transferred, whether as a whole or in parts and whether simultaneously or contemporaneously to any such person, firm, company, corporation or entity without the prior approval of the Congress of the Philippines. Any person or entity to which the franchise herein granted is validly sold, transferred or assigned, shall be subject to the same conditions, terms, restrictions and limitations of this Act."}},{"id":"PH-H5786-A12","no":12,"noLabel":{"en":"Section 12."},"text":{"en":"General Telecommunications Policy Law. - The grantee shall comply with and be subject to the provisions of a general telecommunications policy law that may hereafter be enacted."}},{"id":"PH-H5786-A13","no":13,"noLabel":{"en":"Section 13."},"text":{"en":"Public Offering of Stocks. - In compliance to the constitutional mandate to democratize ownership of public utilities, the herein grantee shall make a public offering through the stock exchange of at least thirty percent (30%) of its common stocks within a period of three (3) years from the date of effectivity of this Act: Provided, That no single person or entity shall be allowed to own more than five percent (5%) of the stock offering."}},{"id":"PH-H5786-A14","no":14,"noLabel":{"en":"Section 14."},"text":{"en":"Separability Clause . - If any of the sections or provisions of this Act is held invalid, all the other provisions not affected thereby shall remain valid."}},{"id":"PH-H5786-A15","no":15,"noLabel":{"en":"Section 15."},"text":{"en":"Repealability and Non-exclusivity Clause. - The franchise herein granted shall be subject to amendment, alteration or repeal by the Congress of the Philippines when the public interest so requires and shall not be interpreted as an exclusive grant of the privileges herein provided for."}},{"id":"PH-H5786-A16","no":16,"noLabel":{"en":"Section 16."},"text":{"en":"Reportorial Requirement. - The grantee shall submit an annual report to the Congress of the Philippines on its compliance with the terms and conditions of the franchise and on its operations within sixty (60) days from the end of every year."}},{"id":"PH-H5786-A17","no":17,"noLabel":{"en":"Section 17."},"text":{"en":"Effectivity Clause. - This Act shall take effect fifteen (15) days from the date of its publication in at least two (2) newspapers of general circulation in the Philippines."}}],"pack":"ph-p82","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Granting to Omninet Philippines, Inc., a Franchise to Establish, Install, Maintain, Lease and Operate Wire And/Or Wireless Telecommunication Systems, Lines, Circuits and Stations Within and Without the Philippines and for Other Purposes","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H5787"] = {"id":"PH-H5787","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1992/ra_7299_1992.html","fetchedAt":"2026-10-06","articleCount":16,"structureMode":"ARTICLE","title":{"zh":"将依第 4916 号共和国法授予 Eagle 广播公司在菲律宾设立、运营和维护无线电广播与电视站的特许经营权自 1993 年 11 月 2 日起再延长二十五年并为其他目的法案","en":"An Act Extending the Franchise Granted to the Eagle Broadcasting Corporation to Establish, Operate and Maintain Radio Broadcasting and Television Stations in the Philippines Under Republic Act Numbered Forty-nine Hundred and Sixteen, to Another Twenty-five (25) Years From November 2, 1993 and for Other Purposes","orig":"An Act Extending the Franchise Granted to the Eagle Broadcasting Corporation to Establish, Operate and Maintain Radio Broadcasting and Television Stations in the Philippines Under Republic Act Numbered Forty-nine Hundred and Sixteen, to Another Twenty-five (25) Years From November 2, 1993 and for Other Purposes"},"level":"law","status":"active","topics":["investment"],"docNumber":"Republic Act No. 7299","issuingBody":"Congress of the Philippines","promulgatedDate":"1992-03-26","completenessNote":"全文，共 16 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1992/ra_7299_1992.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H5787-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Extension of Life of Franchise. - The life of the franchise of the Eagle Broadcasting Corporation to establish, operate and maintain radio broadcasting and television stations in the Philippines under Republic Act No. 4916 is hereby extended to another twenty-five (25) years from November 2, 1993."}},{"id":"PH-H5787-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"Incorporation of Other Provisions of Republic Act No. 4916. - Subject to the provisions of Section 24 (C) of the National Internal Revenue Code, as amended, and the provisions of Executive Order No. 72, all other provisions, terms and conditions contained in Republic Act No. 4916 which are still in force and are not affected by this Act, are hereby made integral parts of this Act."}},{"id":"PH-H5787-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"Parity Clause. - In the event any competing individual, partnership or corporation has received or shall receive from the Congress a similar franchise containing any term or terms more favorable than those herein granted or tending to place the herein grantee at any disadvantage, then such term or terms shall ipso facto become a part of the terms hereof and shall operate equally in favor of the grantee as in the case of said competing individual, partnership or corporation."}},{"id":"PH-H5787-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"Manner of Operation of Stations or Facilities. - The stations or facilities of the grantee shall be constructed and operated in a manner as will at most result only in the minimum interference on the wavelengths or frequencies of the other existing stations or stations which may be established by law, without in any way diminishing its own right to use its selected wavelengths or frequencies and the quality of transmission or reception thereon as should maximize rendition of the grantee's services and/or the availability thereof."}},{"id":"PH-H5787-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"Prior Approval of the National Telecommunications Commission. - The grantee shall secure from the National Telecommunications Commission the appropriate permits and licenses for its stations and shall not use any frequency in the radio spectrum without having been authorized by the Commission. The Commission, however, shall not unreasonably withhold or delay the grant of any such authority."}},{"id":"PH-H5787-A6","no":6,"noLabel":{"en":"Section 6."},"text":{"en":"Responsibility to the Public. - The grantee shall provide reasonable public service time to enable the Government, through the said broadcasting stations, to reach the population on important public issues; provide at all times sound and balanced programming; promote public participation such as in community programming assist in the functions of public information and education; conform to the ethics of honest enterprise; and not use its stations for the broadcasting of obscene and indecent language, or speech, for the dissemination of deliberately false information or willful misrepresentation, or to the detriment of the public interest, or to incite, encourage, or assist in subversive or treasonable acts."}},{"id":"PH-H5787-A7","no":7,"noLabel":{"en":"Section 7."},"text":{"en":"Right of Government. - The President of the Philippines, in times of rebellion, public peril, calamity, emergency, disaster or disturbance of peace and order, may temporarily take over and operate the stations of the grantee, temporarily suspend the operation of any station in the interest of public safety, security and public welfare, or authorize the temporary use and operation thereof by any agency of the Government, upon due compensation to the grantee, for the use of said stations during the period when they shall be so operated."}},{"id":"PH-H5787-A8","no":8,"noLabel":{"en":"Section 8."},"text":{"en":"Tax Provisions. - The grantee, its successors or assigns shall be liable to pay the same taxes on their real estate, buildings and personal property, exclusive of this franchise, as other persons or corporations which are now or hereafter may be required by law to pay. In addition thereto, the grantee, its successors or assigns shall pay a franchise tax equivalent to three percent (3%) of all gross receipts of the radio business transacted under this franchise by the grantee, its successors or assigns and the said percentage shall be in lieu of all taxes on this franchise or earnings thereof: Provided, That the grantee, its successors or assigns shall continue to be liable for income taxes payable under Title II of the National Internal Revenue Code pursuant to Section 2 of Executive Order No. 72 unless the latter enactment is amended or repealed, in which case the amendment or repeal shall be applicable thereto.\nThe grantee shall file the return with and pay the tax due thereon to the Commissioner of Internal Revenue or his duly authorized representative in accordance with the National Internal Revenue Code and the return shall be subject to audit by the Bureau of Internal Revenue."}},{"id":"PH-H5787-A9","no":9,"noLabel":{"en":"Section 9."},"text":{"en":"In compliance with the constitutional mandate to democratize ownership of public utilities, the herein grantee shall make public offering through the stock exchanges of at least thirty percent (30%) of its common stocks within a period of three (3) years from the date of effectivity of this Act: Provided, That no single person or entity shall be allowed to own more than five percent (5%) of the stock offering."}},{"id":"PH-H5787-A10","no":10,"noLabel":{"en":"Section 10."},"text":{"en":"Warranty in Favor of National and Local Governments. - The grantee shall hold the national, provincial and municipal governments of the Philippines harmless from all claims, accounts, demands or actions arising out of accidents or injuries, whether to property or to persons, caused by the construction or operation of the stations of the grantee."}},{"id":"PH-H5787-A11","no":11,"noLabel":{"en":"Section 11."},"text":{"en":"Sale, Lease, Transfer, Usufruct, etc. - The grantee shall not lease, transfer, grant the usufruct of, sell or assign this franchise or the rights and privileges acquired thereunder to any person, firm, company, corporation or entity, nor merge with any other corporation or entity without the prior approval of the Congress of the Philippines. Neither shall the controlling interest in the grantee be transferred whether as a whole or in parts and whether simultaneously or contemporaneously, to any such person, firm, company, corporation or entity without the prior approval of the Congress of the Philippines. Any person or entity to which this franchise is validly sold, transferred or assigned shall be subject to all the same conditions, terms, restrictions and limitations of this Act."}},{"id":"PH-H5787-A12","no":12,"noLabel":{"en":"Section 12."},"text":{"en":"General Broadcast Policy Law. - The grantee shall comply with and be subject to the provisions of a general broadcast policy law that may hereafter be enacted."}},{"id":"PH-H5787-A13","no":13,"noLabel":{"en":"Section 13."},"text":{"en":"Separability Clause . - If any of the sections or provisions of this Act is held invalid, all the other provisions not affected thereby shall remain valid."}},{"id":"PH-H5787-A14","no":14,"noLabel":{"en":"Section 14."},"text":{"en":"Repealability and Non-exclusivity Clause. - This franchise shall be subject to amendment, alteration or repeal by the Congress of the Philippines when the public interest so requires and shall not be interpreted as an exclusive grant of the privileges herein provided for."}},{"id":"PH-H5787-A15","no":15,"noLabel":{"en":"Section 15."},"text":{"en":"Reportorial Requirement. - The grantee shall submit an annual report to the Congress of the Philippines on its compliance with the terms and conditions of the franchise and on its operations within sixty (60) days from the end of every year."}},{"id":"PH-H5787-A16","no":16,"noLabel":{"en":"Section 16."},"text":{"en":"Effectivity Clause. - This Act shall take effect fifteen (15) days from the date of its publication in at least two (2) newspapers of general circulation in the Philippines."}}],"pack":"ph-p82","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Extending the Franchise Granted to the Eagle Broadcasting Corporation to Establish, Operate and Maintain Radio Broadcasting and Television Stations in the Philippines Under Republic Act Numbered Forty-nine Hundred and Sixteen, to Another Twenty-five (25) Years From November 2, 1993 and for Other Purposes","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H5788"] = {"id":"PH-H5788","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1992/ra_7300_1992.html","fetchedAt":"2026-10-06","articleCount":4,"structureMode":"ARTICLE","title":{"zh":"设立Bacolod市","en":"An Act Establishing a National High School in Patricia Homes, Barangay Granada, City of Bacolod, to Be Known as the Generoso Villanueva, Sr. National High School, and Appropriating Funds Therefor","orig":"An Act Establishing a National High School in Patricia Homes, Barangay Granada, City of Bacolod, to Be Known as the Generoso Villanueva, Sr. National High School, and Appropriating Funds Therefor"},"level":"law","status":"active","topics":["administrative","education"],"docNumber":"Republic Act No. 7300","issuingBody":"Congress of the Philippines","promulgatedDate":"1992-03-26","completenessNote":"全文，共 4 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1992/ra_7300_1992.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H5788-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"There shall be established, under the supervision of the Department of Education, Culture and Sports, a national high school in Patricia Homes, Barangay Granada, City of Bacolod, to be known as the Generoso Villanueva, Sr. National High School."}},{"id":"PH-H5788-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The Secretary of Education, Culture and Sports shall issue the necessary rules and regulations for the effective implementation of this Act."}},{"id":"PH-H5788-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"The amount necessary for the implementation of this Act shall be included in the General Appropriations Act of the year following its enactment into law and thereafter."}},{"id":"PH-H5788-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"This Act shall take effect upon its approval."}}],"pack":"ph-p82"};
  FT["PH-H5789"] = {"id":"PH-H5789","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1992/ra_7301_1992.html","fetchedAt":"2026-10-06","articleCount":15,"structureMode":"ARTICLE","title":{"zh":"授予 Satellite Paging Systems Philippines，Inc. 在菲律宾境内运营无线电寻呼与集群无线电系统、为期二十五年的特许经营权法案","en":"An Act Granting Satellite Paging Systems Philippines, Inc., a Franchise to Construct, Establish, Operate and Maintain Radio Paging Systems and Trunked Radio Systems Within the Philippines for a Period of Twenty-five (25) Years, and for Other Purposes","orig":"An Act Granting Satellite Paging Systems Philippines, Inc., a Franchise to Construct, Establish, Operate and Maintain Radio Paging Systems and Trunked Radio Systems Within the Philippines for a Period of Twenty-five (25) Years, and for Other Purposes"},"level":"law","status":"active","topics":["investment"],"docNumber":"Republic Act No. 7301","issuingBody":"Congress of the Philippines","promulgatedDate":"1992-03-26","completenessNote":"全文，共 15 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1992/ra_7301_1992.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H5789-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Nature and Scope of Franchise. - Subject to the provisions of the Constitution and applicable laws, rules and regulations of the National Telecommunications Commission, there is hereby granted to Satellite Paging Systems Philippines, Inc., hereunder referred to as the grantee or its successors, a franchise to construct, establish, operate and maintain for commercial purposes and in the public interest, radio paging systems and mobile communication services limited to trunked radio technology within the Philippines and to install corresponding transmitting and receiving stations and communication facilities at such places in the Philippines as may be necessary and convenient."}},{"id":"PH-H5789-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"Prior Approval of the National Telecommunications Commission. - The grantee shall secure from the National Telecommunications Commission the appropriate permits and licenses for its stations and shall not use any frequency in the radio spectrum without having been authorized by the Commission. The stations of the grantee shall be constructed and operated in a manner as will at most result only in the minimum interference on the wavelengths or frequencies of the existing stations or other stations which may be established in accordance with law of other telecommunications services grantees, without in any way diminishing its own right to use its selected wavelengths or frequencies and the quality of transmission or reception thereon as would maximize rendition of the grantee's services and/or the availability thereof."}},{"id":"PH-H5789-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"Responsibility to the Public. - The grantee shall conform to the ethics of honest enterprise and shall not use its stations for obscene or indecent transmissions or for the dissemination of deliberately false information or willful misrepresentation or assist in subversive or treasonable acts."}},{"id":"PH-H5789-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"Rates for Services. - The subscription charges and rates for services excluding the sale or lease of the equipment or unit that the grantee shall offer to the public shall be subject to the approval of the National Telecommunications Commission or its legal successors."}},{"id":"PH-H5789-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"Right of Government. - A special right is hereby reserved to the President of the Philippines in times of war, rebellion, public peril, calamity, emergency, disaster or disturbance of peace and order to take over and operate the stations, transmitter systems, facilities and equipment of the grantee or to authorize the temporary use and operation thereof by any department of the Government upon due compensation to the grantee, for the use of said stations, transmitter systems, facilities and equipment during the period when they shall be so operated."}},{"id":"PH-H5789-A6","no":6,"noLabel":{"en":"Section 6."},"text":{"en":"Term of Franchise. - This franchise shall be for a term of twenty-five (25) years from the date of effectivity of this Act, unless sooner revoked or cancelled. In the event the grantee fails to operate continuously for two (2) years or to commence operation within two (2) years from the date of effectivity of this Act, this franchise shall be deemed ipso facto revoked."}},{"id":"PH-H5789-A7","no":7,"noLabel":{"en":"Section 7."},"text":{"en":"Acceptance and Compliance. - Acceptance of this franchise shall be given in writing to the National Telecommunications Commission within sixty (60) days after the effectivity of this Act. The grantee shall operate the radio paging systems and mobile communication services based on trunked radio technology for which this franchise is granted within two (2) years from the date of its acceptance in writing of this franchise. Refusal or failure to accept the franchise or to operate within the prescribed periods shall render the franchise void."}},{"id":"PH-H5789-A8","no":8,"noLabel":{"en":"Section 8."},"text":{"en":"Ownership. - In compliance with the constitutional mandate to democratize ownership of public utilities, the herein grantee shall make public offering through the stock exchanges of at least thirty percent (30%) of its common stocks within a period of three (3) years from the date of approval of this Act: Provided, That no single person or entity shall be allowed to own more than five percent (5%) of the stock offerings."}},{"id":"PH-H5789-A9","no":9,"noLabel":{"en":"Section 9."},"text":{"en":"Tax Provisions. - The grantee or its successors shall be liable to pay the same taxes on their real estate, buildings and personal property, exclusive of this franchise, as other persons or corporations are now or hereafter may be required by law to pay. In addition thereto, the grantee or its successors shall pay a franchise tax equivalent to three percent (3%) of all gross receipts of the business transacted under this franchise by the grantee or its successors, and the said percentage shall be in lieu of all taxes on this franchise or earnings thereof: Provided, That the grantee or its successors shall continue to be liable for income taxes payable under Title II of the National Internal Revenue Code pursuant to Section 2 of Executive Order No. 72 unless the latter enactment is amended or repealed, in which case the amendment or repeal shall be applicable thereto.\nThe grantee shall file the return with and pay the tax due thereon to the Commissioner of Internal Revenue or his duly authorized representative in accordance with the National Internal Revenue Code and the return shall be subject to audit by the Bureau of Internal Revenue."}},{"id":"PH-H5789-A10","no":10,"noLabel":{"en":"Section 10."},"text":{"en":"Warranty in Favor of National and Local Governments. - The grantee shall hold the national, provincial and municipal governments of the Philippines harmless from all claims, accounts, demands or actions arising out of accidents or injuries, whether to property or to persons, caused by the construction or operation of the stations, systems, facilities and equipment of the grantee."}},{"id":"PH-H5789-A11","no":11,"noLabel":{"en":"Section 11."},"text":{"en":"Sale, Lease, Transfer, Usufruct, etc. - The grantee shall not lease, transfer, grant the usufruct of, sell the franchise herein granted or the rights and privileges acquired thereunder to any person, firm, company, corporation or entity without prior approval of the Congress of the Philippines. Any person or entity to which the franchise herein granted is sold or transferred shall be subject to the same conditions, terms, restrictions and limitations of this Act.\nThe herein grantee shall not contract out its management or its operations to another entity, natural or juridical, not otherwise enfranchised by the law."}},{"id":"PH-H5789-A12","no":12,"noLabel":{"en":"Section 12."},"text":{"en":"Annual Report. - In addition to the terms and conditions of the franchise as provided herein, the Satellite Paging Systems Philippines, Inc., shall submit an annual report of its operations to the National Telecommunications Commission, copy furnished the Congress of the Philippines."}},{"id":"PH-H5789-A13","no":13,"noLabel":{"en":"Section 13."},"text":{"en":"Separability Clause . - If any of the sections or provisions of this Act is held invalid, all the other provisions not affected thereby shall remain valid."}},{"id":"PH-H5789-A14","no":14,"noLabel":{"en":"Section 14."},"text":{"en":"Repealing Clause . - The franchise herein granted shall be subject to amendment, alteration or repeal by the Congress of the Philippines when the public interest so requires and shall not be interpreted as an exclusive grant of the privileges herein provided for."}},{"id":"PH-H5789-A15","no":15,"noLabel":{"en":"Section 15."},"text":{"en":"Effectivity Clause. - This Act shall take effect fifteen (15) days from the date of its publication in at least two (2) newspapers of general circulation."}}],"pack":"ph-p82","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Granting Satellite Paging Systems Philippines, Inc., a Franchise to Construct, Establish, Operate and Maintain Radio Paging Systems and Trunked Radio Systems Within the Philippines for a Period of Twenty-five (25) Years, and for Other Purposes","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H5790"] = {"id":"PH-H5790","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1992/ra_7302_1992.html","fetchedAt":"2026-10-06","articleCount":19,"structureMode":"ARTICLE","title":{"zh":"授予 House of Travel，Incorporated 以 Davao 为主要枢纽设立、运营和维护国内客运与货运包机航空运输服务的特许经营权法案","en":"An Act Granting House of Travel, Incorporated, a Franchise to Establish, Operate and Maintain Domestic Passengers and Cargo Air Chartered Transport Services With Davao as Its Major Hub","orig":"An Act Granting House of Travel, Incorporated, a Franchise to Establish, Operate and Maintain Domestic Passengers and Cargo Air Chartered Transport Services With Davao as Its Major Hub"},"level":"law","status":"active","topics":["investment","company"],"docNumber":"Republic Act No. 7302","issuingBody":"Congress of the Philippines","promulgatedDate":"1992-03-26","completenessNote":"全文，共 19 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1992/ra_7302_1992.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H5790-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Nature and Scope of Franchise. - Subject to the provisions of the Constitution and applicable laws, rules and regulations, there is hereby granted to the House of Travel, Inc., hereunder referred to as the grantee, its successors or assigns a franchise to establish, operate and maintain passenger and cargo air charter transport services with Davao as its major hub.\nDomestic air transport for tourist services shall include the maintenance and operation of hangars and aircraft service stations and facilities and other services of similar nature which may be necessary, convenient or useful as an auxiliary to tourist air transport services.\nThe grantee shall be given the right at its terminals and landing fields, as well as in its aircraft, to construct, operate and maintain stations or transmitting sets for wireless telegraphy and direction findings, and other radio aids to air navigation, using wavelengths in accordance with the rules and regulations issued from time to time by the proper agencies of the Government. The wireless communication facilities shall be used solely for receiving and transmitting weather forecasts and other matters in connection with the grantee's services."}},{"id":"PH-H5790-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"Prior Approval of the Civil Aeronautics Board. - The grantee shall secure from the Civil Aeronautics Board the appropriate permits and licenses for its operations.\nAll aircraft used by the grantee and the flight crew members operating such aircraft shall be licensed by the Government of the Philippines and, together with its accessories and equipment, shall at all times be in airworthy condition. They shall be equipped with radio communication, safety and other equipment and shall be operated and maintained in accordance with the regulations and technical requirements of the Air Transportation Office or such other regulatory bodies as the Government may prescribe for this purpose.\nThe grantee's equipment and the operation of such equipment shall at all times be subject to inspection and regulation by the Air Transportation Office.\nThe grantee shall comply with the provisions of Republic Act Numbered Seven hundred seventy-six, and the regulations promulgated thereunder from time to time."}},{"id":"PH-H5790-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"Responsibility to the Public. - Excepting cases of force majeure and whenever weather conditions permit, the grantee shall maintain passenger and cargo air charter transport services within Davao and any and all points and places throughout the Philippines as traffic needs may require."}},{"id":"PH-H5790-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"Rates for Services. - The grantee shall fix just and reasonable rates for its air transport services, mail, goods and freight, subject to the regulations and approval of the Civil Aeronautics Board and other proper regulatory agencies of the Government."}},{"id":"PH-H5790-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"Term of Franchise . - This franchise shall be for a term of forty (40) years from the date of the approval of this Act, unless sooner revoked or cancelled. In the event that the grantee fails to operate continuously for two (2) years, this franchise shall be deemed ipso facto revoked."}},{"id":"PH-H5790-A6","no":6,"noLabel":{"en":"Section 6."},"text":{"en":"Landing Facilities. - The grantee may use the landing and other airport facilities on land and water as may be maintained or owned by the Government within the Philippines or the grantee's lines subject to such terms and conditions, restrictions and national policy consideration as the Philippine Government may prescribe and, reciprocally the Philippine Government shall have the right to use the landing and other airport facilities as may be maintained or owned by the grantee in the Philippines."}},{"id":"PH-H5790-A7","no":7,"noLabel":{"en":"Section 7."},"text":{"en":"Contracts. - The grantee is authorized to enter into transportation contracts with the Philippine Government, including the carrying of mail, upon terms and conditions to be mutually agreed upon. The grantee shall give preferential consideration to contracts with the Philippine Government. The grantee may likewise enter into such other contracts relating to air transport activities."}},{"id":"PH-H5790-A8","no":8,"noLabel":{"en":"Section 8."},"text":{"en":"Right of Government. - In case of war, insurrection, domestic trouble, public calamity or national emergency, the Philippine government, upon order of the President, shall have the right to take over and operate the equipment of the grantee, paying for its use or damages."}},{"id":"PH-H5790-A9","no":9,"noLabel":{"en":"Section 9."},"text":{"en":"Eminent Domain. - With the approval of the President of the Republic of the Philippines and subject to the limitations and procedures prescribed by law, the grantee shall be authorized to exercise the right of eminent domain as may be reasonably necessary for its stations and other structures in connection with the grantee's activities.\nNo private property shall be taken for any purpose by the grantee without proper condemnation proceedings and just compensation paid or tendered therefor, and any authority to take and occupy land contained herein shall not apply to the taking, use or occupation of any land except such as is required for the actual purposes for which this franchise is granted."}},{"id":"PH-H5790-A10","no":10,"noLabel":{"en":"Section 10."},"text":{"en":"Warranty in Favor of National and Local Governments. - The grantee shall hold the national, provincial and municipal governments of the Philippines harmless from all claims, accounts, demands or actions arising out of accidents or injuries, whether to property or to persons, caused by the operation of the services under the franchise hereby granted."}},{"id":"PH-H5790-A11","no":11,"noLabel":{"en":"Section 11."},"text":{"en":"Public Equity Participation. - In compliance with the constitutional mandate to democratize ownership of public utilities, the herein grantee shall make a public offering through the stock exchanges of at least thirty percent (30%) of its common stock within a period of ten (10) years from the date of the effectivity of this Act: Provided, That no single person or entity shall be allowed to own more than five percent (5%) of the stock offering."}},{"id":"PH-H5790-A12","no":12,"noLabel":{"en":"Section 12."},"text":{"en":"Tax Provisions. - In consideration of the franchise and rights hereby granted, the grantee shall pay to the Philippine Government during the life of this franchise a franchise tax of five percent (5%) of the gross receipts derived by the grantee from its domestic air transport operations.\nThe grantee shall, however, be subject to income tax levied under Title II of the National Internal Revenue Code, as amended, and the tax on its real property under existing law."}},{"id":"PH-H5790-A13","no":13,"noLabel":{"en":"Section 13."},"text":{"en":"Interpretation of Franchise. - This franchise shall not be interpreted to mean as an exclusive grant of the privileges herein provided for. However, in the event that any competing individual, partnership, or corporation shall receive a similar permit or franchise with terms and/or provisions more favorable than those herein granted or which tend to place the grantee herein at any disadvantage, then such terms and/or provisions shall be deemed part hereof and shall operate equally in favor of the grantee herein."}},{"id":"PH-H5790-A14","no":14,"noLabel":{"en":"Section 14."},"text":{"en":"Sale, Lease, Transfer, Assignment, Usufruct, etc. - The grantee shall not lease, transfer, grant the usufruct of, sell or assign this franchise and the rights and privileges acquired thereunder to any person, firm, company, corporation or legal entity, nor shall the controlling interest in the grantee be transferred to any such private person, firm, company, corporation or entity without the prior approval of the Congress of the Philippines.\nAny person or entity to which this franchise is sold, transferred, or assigned shall be subject to all the conditions, terms, restrictions and limitations of this Act."}},{"id":"PH-H5790-A15","no":15,"noLabel":{"en":"Section 15."},"text":{"en":"Reportorial Requirement. - The grantee shall submit an annual report to the Congress of the Philippines on its compliance with the terms and conditions of the franchise and on its operations within sixty (60) days from the end of every year."}},{"id":"PH-H5790-A16","no":16,"noLabel":{"en":"Section 16."},"text":{"en":"Legislative Amendment. - This franchise is subject to amendment or repeal by the Congress of the Philippines when the common good so requires."}},{"id":"PH-H5790-A17","no":17,"noLabel":{"en":"Section 17."},"text":{"en":"Separability Clause . - If any section or provision of this franchise, as amended, is held or declared unconstitutional or invalid by a competent court in a final judgment, the other sections or provisions hereof shall continue to be in force as if the section or provision so annulled or voided had never been incorporated in this franchise."}},{"id":"PH-H5790-A18","no":18,"noLabel":{"en":"Section 18."},"text":{"en":"Repealing Clause . - All laws, decrees, orders, instructions, and rules and regulations or parts thereof which are inconsistent herewith are hereby repealed or modified accordingly."}},{"id":"PH-H5790-A19","no":19,"noLabel":{"en":"Section 19."},"text":{"en":"Effectivity Clause. - This Act shall take effect fifteen (15) days from the date of its publication in at least two (2) newspapers of general circulation in the Philippines."}}],"pack":"ph-p82","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Granting House of Travel, Incorporated, a Franchise to Establish, Operate and Maintain Domestic Passengers and Cargo Air Chartered Transport Services With Davao as Its Major Hub","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H5791"] = {"id":"PH-H5791","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1992/ra_7303_1992.html","fetchedAt":"2026-10-06","articleCount":16,"structureMode":"ARTICLE","title":{"zh":"授予 Kalayaan 广播系统公司在棉兰老岛建设、安装、运营和维护无线电广播站并为其他目的法案","en":"An Act Granting the Kalayaan Broadcasting System, Incorporated, a Franchise to Construct, Install, Operate and Maintain Radio Broadcasting Stations in the Island of Mindanao and for Other Purposes","orig":"An Act Granting the Kalayaan Broadcasting System, Incorporated, a Franchise to Construct, Install, Operate and Maintain Radio Broadcasting Stations in the Island of Mindanao and for Other Purposes"},"level":"law","status":"active","topics":["investment","company"],"docNumber":"Republic Act No. 7303","issuingBody":"Congress of the Philippines","promulgatedDate":"1992-03-26","completenessNote":"全文，共 16 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1992/ra_7303_1992.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H5791-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Nature and Scope of Franchise. - Subject to the provisions of the Constitution and applicable laws, rules and regulations, there is hereby granted to the Kalayaan Broadcasting System, incorporated, hereunder referred to as the grantee, its successors or assigns a franchise to construct, install, operate and maintain for commercial purposes and in the public interest radio broadcasting stations in the island of Mindanao with the corresponding technological auxiliaries or facilities, special broadcast and other program and distribution services and relay stations, and to install radio communication facilities for the grantee's private use in its broadcast services."}},{"id":"PH-H5791-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"Manner of Operation of Stations or Facilities. - The stations or facilities of the grantee shall be constructed and operated in a manner as will at most result only in the minimum interference on the wavelengths or frequencies of the other existing stations or stations which may be established by law without in any way diminishing its own right to use its selected wavelengths or frequencies and the quality of transmission or reception thereon as should maximize rendition of the grantee's services and/or the availability thereof."}},{"id":"PH-H5791-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"Prior Approval of the National Telecommunications Commission. - The grantee shall secure from the National Telecommunications Commission the appropriate permits and licenses for its stations and shall not use any frequency in the radio spectrum without having been authorized by the Commission. The Commission, however, shall not unreasonably withhold or delay the grant of any such authority."}},{"id":"PH-H5791-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"Responsibility to the Public. - The grantee shall provide reasonable public service time to enable the government, through the said broadcasting stations, to reach the population on important public issues; provide at all times sound and balanced programming; promote public participation such as in community programming; assist in the functions of public information and education; conform to the ethics of honest enterprise; and not use its stations for the broadcasting of obscene and indecent language, speech, act or scene, or for the dissemination of deliberately false information or willful misrepresentation, or to the detriment of the public interest, or to incite, encourage, or subversive or treasonable acts."}},{"id":"PH-H5791-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"Right of Government. - A special right is hereby reserved to the President of the Philippines, in times of rebellion, public peril, calamity, emergency, disaster or disturbance of peace and order, to temporarily take over and operate the stations of the grantee, to temporarily suspend the operation of any station in the interest of public safety, security and public welfare or to authorize the temporary use and operation thereof by any agency of the Government, upon due compensation to the grantee, for the use of said stations during the period when they shall be so operated."}},{"id":"PH-H5791-A6","no":6,"noLabel":{"en":"Section 6."},"text":{"en":"Term of Franchise. - This franchise shall be for a term of twenty-five (25) years from the date of effectivity of this Act, unless sooner revoked or cancelled. In the event the grantee fails to operate continuously for two (2) years, this franchise shall be deemed ipso facto revoked."}},{"id":"PH-H5791-A7","no":7,"noLabel":{"en":"Section 7."},"text":{"en":"Acceptance and Compliance. - Acceptance of this franchise shall be given in writing within sixty (60) days after the effectivity of this Act. Upon giving such acceptance, the grantee shall exercise the privileges granted under this Act. Nonacceptance shall render the franchise void."}},{"id":"PH-H5791-A8","no":8,"noLabel":{"en":"Section 8."},"text":{"en":"Tax Provisions. - The grantee, its successors or assigns shall be have to pay the same taxes on their real estate, buildings and personal property, exclusive of this franchise, as other persons or corporations are now or hereafter may be required by law to pay. In addition thereto, the grantee, its successors or assigns shall pay a franchise tax equivalent to three percent (3%) of all gross receipts of the radio business transacted under this franchise by the grantee, its successors or assigns and the said percentage shall be in lieu or all taxes on this franchise or earnings thereof: Provided, That the grantee, its successors or assigns shall continue to be liable for income taxes payable under Title II of the National Internal Revenue Code pursuant to Section 2 of Executive Order No. 72 unless the latter enactment is amended or repealed, in which case the amendment or repeal shall be applicable thereto.\nThe grantee shall file the return with and pay the tax due thereon to the Commissioner of Internal Revenue or his duly authorized representative in accordance with the National Internal Revenue Code and the return shall be subject to audit by the Bureau of Internal Revenue."}},{"id":"PH-H5791-A9","no":9,"noLabel":{"en":"Section 9."},"text":{"en":"Democratization of Ownership. - In compliance with the constitutional mandate to democratize ownership of public utilities, the herein grantee shall make the public offering through the stock exchange of at least thirty percent (30%) of its common stock within a period of three (3) years from the date of effectivity of this Act: Provided, That no single person or entity shall be allowed to own more than five percent (5%) of the stock offerings."}},{"id":"PH-H5791-A10","no":10,"noLabel":{"en":"Section 10."},"text":{"en":"Warranty in Favor of National and Local Governments. - The grantee shall hold the national, provincial and municipal governments of the Philippines harmless from all claims, accounts, demands or actions arising out of accidents or injuries, whether to property or to persons, caused by the construction or operation of the stations of the grantee."}},{"id":"PH-H5791-A11","no":11,"noLabel":{"en":"Section 11."},"text":{"en":"Sale, Lease, Transfer, Usufruct, etc. - The grantee shall not lease, transfer, grant the usufruct of, sell or assign this franchise or the rights and privileges acquired thereunder to any person, firm, company, corporation or other commercial or legal entity, nor shall the controlling interest in the grantee be transferred, whether as a whole or in parts and whether simultaneously or contemporaneously, to any such private person, firm, company, corporation or entity without the prior approval of the Congress of the Philippines. Any person or entity to which this franchise is sold, transferred or assigned shall be subject to all the same conditions, terms, restrictions and limitations of this Acts."}},{"id":"PH-H5791-A12","no":12,"noLabel":{"en":"Section 12."},"text":{"en":"Separability Clause . - If any of the sections or provisions of this Act is held invalid, all the other provisions not affected thereby shall remain valid."}},{"id":"PH-H5791-A13","no":13,"noLabel":{"en":"Section 13."},"text":{"en":"Repealing and Non-exclusivity Clause. - This franchise shall be subject to amendment, alteration or repeal by the Congress of the Philippines when the public interest so requires and shall not be interpreted as an exclusive grant of the privileges herein provided for."}},{"id":"PH-H5791-A14","no":14,"noLabel":{"en":"Section 14."},"text":{"en":"General Broadcast Policy. - The grantee shall comply with and be subject to the provisions of a general broadcast policy law that may hereafter be enacted."}},{"id":"PH-H5791-A15","no":15,"noLabel":{"en":"Section 15."},"text":{"en":"Reportorial Requirement. - The grantee shall submit an annual report to the Congress of the Philippines on its compliance with the terms and conditions of the franchise and on its operations within sixty (60) days from the end of every year."}},{"id":"PH-H5791-A16","no":16,"noLabel":{"en":"Section 16."},"text":{"en":"Effectivity Clause. - This Act shall take effect fifteen days (15) days from the date of its publication in at least two (2) newspapers of general circulation in the Philippines."}}],"pack":"ph-p82","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Granting the Kalayaan Broadcasting System, Incorporated, a Franchise to Construct, Install, Operate and Maintain Radio Broadcasting Stations in the Island of Mindanao and for Other Purposes","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H5792"] = {"id":"PH-H5792","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1992/ra_7304_1992.html","fetchedAt":"2026-10-06","articleCount":15,"structureMode":"ARTICLE","title":{"zh":"授予 Astro Air International，Inc. 设立、运营和维护国内与国际航空运输服务及空运旅客、邮件、货物与财产的相关服务并为其他目的法案","en":"An Act Granting the Astro Air International, Inc., a Franchise to Establish, Operate and Maintain Domestic and International Air Transportation Services and Other Allied Services for the Carriage and Transfer of Passengers, Mail, Goods and Other Property By Air and for Other Purposes","orig":"An Act Granting the Astro Air International, Inc., a Franchise to Establish, Operate and Maintain Domestic and International Air Transportation Services and Other Allied Services for the Carriage and Transfer of Passengers, Mail, Goods and Other Property By Air and for Other Purposes"},"level":"law","status":"active","topics":["investment","trade"],"docNumber":"Republic Act No. 7304","issuingBody":"Congress of the Philippines","promulgatedDate":"1992-03-26","completenessNote":"全文，共 15 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1992/ra_7304_1992.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H5792-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Nature and Scope of Franchise. - Subject to the provisions of the Constitution and applicable laws, rules and regulations, there is hereby granted to the Astro Air International, Inc., hereunder referred to as the grantee, its successors or assigns a franchise to establish, operate and maintain domestic and international air transportation services and other allied services for the carriage and transfer of passengers, mail, goods and other property by air.\nAir transport services shall include the maintenance and operation of hangars- and aircraft service stations and facilities and other services of similar nature which may be necessary, convenient or useful as an auxiliary to aircraft transportation.\nThe grantee shall have the right at its terminals and landing fields, as well as in its aircraft, to construct, operate and maintain stations or transmitting sets for wireless telegraphy and direction findings, and other radio aids to air navigation, using wavelengths in accordance with the rules and regulations issued from time to time by the proper agencies of the Government. The wireless communication facilities shall be used solely for receiving and transmitting weather forecasts and other matters in connection with the grantee's services."}},{"id":"PH-H5792-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"Prior Approval of the Civil Aeronautics Board. - The grantee shall secure from the Civil Aeronautics Board the appropriate permits and licenses for its operations.\nAll aircraft used by the grantee including their accessories and equipment shall at all times be airworthy and the crew members shall be licensed by the Government of the Philippines.\nThe grantee's equipment and the operation of such equipment shall at all times be subject to inspection and regulation by the Air Transportation Office.\nThe grantee shall comply with the provisions of Republic Act Numbered Seven hundred and seventy-six, and the regulations promulgated thereunder from time to time."}},{"id":"PH-H5792-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"Responsibility to the Public. - Excepting cases of force majeure and whenever weather conditions permit, the grantee shall maintain scheduled and/or nonscheduled and/or charter airtransport services between Manila and any and all points and places throughout the Philippines and between Manila and other countries at such frequencies as traffic needs may require: Provided,however, That at least twenty-five percent (25%) of all its frequencies shall be for the domestic market."}},{"id":"PH-H5792-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"Rates for Services. - The grantee shall fix and charge reasonable rates for the transportation of passengers, mail, goods and freight, subject to the regulations and approval of the Civil Aeronautics Board and other proper regulatory agencies of the Government."}},{"id":"PH-H5792-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"Term of Franchise. - This franchise shall be for a term of forty (40) years from the date of the effectivity of this Act, unless sooner revoked or cancelled. In the event that the grantee fails to operate within two (2) years from the effectivity of this Act, this franchise shall be deemed ipso facto revoked."}},{"id":"PH-H5792-A6","no":6,"noLabel":{"en":"Section 6."},"text":{"en":"Landing Facilities. - The grantee may use the landing and other airport facilities on land and water as may be maintained or owned by the Government within the Philippines on the grantee's lines subject to such terms and conditions, restrictions and national policy considerations as the Philippine Government may impose: Provided, That the Philippine Government shall have the right to use such landing and other airport facilities as may be maintained or owned by the grantee in the Philippines."}},{"id":"PH-H5792-A7","no":7,"noLabel":{"en":"Section 7."},"text":{"en":"Contracts. - The grantee is hereby authorized to enter into transportation contracts with the Philippine Government, including the carrying of mail, upon terms and conditions to be mutually agreed upon. The grantee shall give preferential consideration to contracts with the Philippine Government. The grantee may likewise enter into transportation maintenance and/or service contracts, and such other contracts relating to air transport with other foreign-owned airlines, particularly with those which have international routes."}},{"id":"PH-H5792-A8","no":8,"noLabel":{"en":"Section 8."},"text":{"en":"Right of Government. - In case of war, insurrection, domestic trouble, public calamity or national emergency, the Philippine Government, upon order of the President, shall have the right to take over and operate the grantee, paying for its use or damages."}},{"id":"PH-H5792-A9","no":9,"noLabel":{"en":"Section 9."},"text":{"en":"Public Equity Participation. - In compliance with the constitutional mandate to democratize ownership of public utilities, the herein grantee shall make a public offering through the stock exchanges of at least thirty percent (30%) of its common stocks within a period of ten (10) years from the date of effectivity of this Act: Provided, That no single person or entity shall be allowed to own more than five percent (5%) of the stock offerings."}},{"id":"PH-H5792-A10","no":10,"noLabel":{"en":"Section 10."},"text":{"en":"Warranty in Favor of National and Local Governments. - The grantee shall hold the national, provincial, and municipal governments of the Philippines harmless from all claims, accounts, demands, or actions arising out of accidents or injuries, whether to property or to persons, caused by the operation of the services under the franchise hereby granted, attributable solely to an act or omission of the grantee."}},{"id":"PH-H5792-A11","no":11,"noLabel":{"en":"Section 11."},"text":{"en":"Tax Provisions. - The grantee shall pay to the Philippine Government during the life of this franchise a franchise tax of five percent (5%) of the gross revenues derived by the grantee from transport operations.\nIn the event that any competing individual, partnership and corporation receives and enjoys tax privileges which tend to place the grantee herein at any disadvantage, then such provisions shall be deemed part hereof and shall operate equally in favor of the grantee.\nThe grantee shall however be subject to income tax levied under Title II of the National Internal Revenue Code, as amended, and tax on its real property under existing laws on revenues earned from activities other than air transportation."}},{"id":"PH-H5792-A12","no":12,"noLabel":{"en":"Section 12."},"text":{"en":"Sale, Lease, Transfer, Assignment, Usufruct, etc. - The grantee shall not lease, transfer, grant the usufruct of, sell or assign this franchise and the rights and privileges acquired thereunder to any person, firm, company, corporation, or legal entity, nor shall the controlling interest in the grantee be transferred to any such private person, firm, company, corporation, or entity without the prior approval of Congress.\nAny person or entity to which this franchise is sold, transferred, or assigned shall be subject to all the conditions, terms, restrictions, and limitations of this Act."}},{"id":"PH-H5792-A13","no":13,"noLabel":{"en":"Section 13."},"text":{"en":"Legislative Amendment/Repeal. - This franchise is subject to amendment or repeal by Congress when the common good so requires."}},{"id":"PH-H5792-A14","no":14,"noLabel":{"en":"Section 14."},"text":{"en":"Separability Clause . - If any section or provision of this franchise is held or declared unconstitutional or invalid by a competent court in a final judgment, the other sections or provisions hereof shall continue to be in force as if the section or provision so annulled or voided had never been incorporated in this Act."}},{"id":"PH-H5792-A15","no":15,"noLabel":{"en":"Section 15."},"text":{"en":"Effectivity Clause. - This Act shall take effect fifteen (15) days after its publication in at least two (2) national newspapers of general circulation in the Philippines."}}],"pack":"ph-p82","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Granting the Astro Air International, Inc., a Franchise to Establish, Operate and Maintain Domestic and International Air Transportation Services and Other Allied Services for the Carriage and Transfer of Passengers, Mail, Goods and Other Property By Air and for Other Purposes","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H5793"] = {"id":"PH-H5793","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1992/ra_7305_1992.html","fetchedAt":"2026-10-06","articleCount":42,"structureMode":"ARTICLE","title":{"zh":"公共卫生工作者大宪章","en":"The Magna Carta of Public Health Workers","orig":"The Magna Carta of Public Health Workers"},"level":"law","status":"active","topics":["labor","health"],"docNumber":"Republic Act No. 7305","issuingBody":"Congress of the Philippines","promulgatedDate":"1992-03-26","completenessNote":"全文，共 42 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1992/ra_7305_1992.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H5793-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Title. - This Act shall be known as the \" Magna Carta of Public Health Workers \""}},{"id":"PH-H5793-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"Declaration of Policy and Objective. - The State shall instill health consciousness among our people to effectively carry out the health programs and projects of the government essential for the growth and health of the nation. Towards this end, this Act aims: (a) to promote and improve the social and economic well-being of the health workers, their living and working conditions and terms of employment; (b) to develop their skills and capabilities in order that they will be more responsive and better equipped to deliver health projects and programs; and (c) to encourage those with proper qualifications and excellent abilities to join and remain in government service."}},{"id":"PH-H5793-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"Definition. - For purposes of this Act, \"health workers\" shall mean all persons who are engaged in health and health-related work, and all persons employed in all hospitals, sanitaria, health infirmaries, health centers, rural health units, barangay health stations, clinics and other health-related establishments owned and operated by the Government or its political subdivisions with original charters and shall include medical, allied health professional, administrative and support personnel employed regardless of their employment status."}},{"id":"PH-H5793-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"Recruitment and Qualification. - Recruitment policy and minimum requirements with respect to the selection and appointment of a public health worker shall be developed and implemented by the appropriate government agencies concerned in accordance with policies and standards of the Civil Service Commission: provided, that in the absence of appropriate eligibles and it becomes necessary in the public interest to fill a vacancy, a temporary appointment shall be issued to the person who meets all the requirements for the position to which he/she is being appointed except the appropriate civil service eligibility: provided, further, that such temporary appointment shall not exceed twelve (12) months nor be less than three (3) months renewable thereafter but that the appointee may be replaced sooner if (a) a qualified civil service eligible becomes available or (b) the appointee is found wanting in performance or conduct befitting a government employee."}},{"id":"PH-H5793-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"Performance Evaluation and Merit Promotion. - The Secretary of Health, upon consultation with the proper government agency concerned and the Management-Health Workers' Consultative Councils, as established under Section 33 of this Act, shall prepare a uniform career and personnel development plan applicable to all public health personnel. Such career and personnel development plan shall include provisions on merit promotion, performance evaluation, in-service training grants, job rotation, suggestions and incentive award system.\nThe performance evaluation plan shall consider foremost the improvement of individual employee efficiency and organizational effectiveness: provided. That each employee shall be informed regularly by his/her supervisor of his/her performance evaluation.\nThe merit promotion plan shall be in consonance with the rules of the Civil Service Commission."}},{"id":"PH-H5793-A6","no":6,"noLabel":{"en":"Section 6."},"text":{"en":"Transfer of Geographical Reassignment of Public Health Workers. -\na) a transfer is a movement from one position to another which is of equivalent rank, level or salary without break in service;\nb) a geographical reassignment, hereinafter referred to as \"reassignment\" is a movement from one geographical location to another; and\nc) a public health worker shall not be transferred and/or reassigned, except when made in the interest of public service, in which case, the employee concerned shall be informed of the reasons therefore in writing. If the public health worker believes that there is no justification for the transfer and/or reassignment, he/she may appeal his/her case to the Civil Service Commission, which shall cause his/her transfer and/or reassignment to be held in abeyance: provided, that no transfer and/or reassignment whatsoever shall be made three (3) months before any local or national elections: provided, further, that the necessary expenses of the transfer and/or reassignment of the public health worker and his/her immediate family shall be paid for by the Government."}},{"id":"PH-H5793-A7","no":7,"noLabel":{"en":"Section 7."},"text":{"en":"Married Public Health Workers. - Whenever possible, the proper authorities shall take steps to enable married couples, both of whom are public health workers, to be employed or assigned in the same municipality, but not in the same office."}},{"id":"PH-H5793-A8","no":8,"noLabel":{"en":"Section 8."},"text":{"en":"Security of Tenure. - In case of regular employment of public health workers, their services shall not be terminated except for cause provided by law and after due process: provided, that if a public health worker is found by the Civil Service Commission to be unjustly dismissed from work, he/she shall be entitled to reinstatement without loss of seniority rights and to his/her back wages with twelve percent (12%) interest computed from the time his/her compensation was withheld from his/her up to the time of reinstatement."}},{"id":"PH-H5793-A9","no":9,"noLabel":{"en":"Section 9."},"text":{"en":"Discrimination Prohibited. - A public health worker shall not be discriminated against with regard to gender, civil status, creed, religious or political beliefs and ethnic groupings in the exercise of his/her profession."}},{"id":"PH-H5793-A10","no":10,"noLabel":{"en":"Section 10."},"text":{"en":"No Understaffing/Overloading of Health Staff . - There shall be no understaffing or overloading of public health workers. The ratio of health staff to patient load shall be such as to reasonably effect a sustained delivery of quality health care at all times without overworking the public health workers and over extending his/her duty and service. Health students and apprentices shall be allowed only for purposes of training and education.\nIn line with the above policy, substitute officers or employees shall be provided in place of officers or employees who are on leave for over three (3) months. Likewise, the Secretary of Health or the proper government official shall assign a medico-legal officer in every province.\nIn places where there is no such medico-legal officer, rural physicians who are required to render medico-legal services shall be entitled to additional honorarium and allowances."}},{"id":"PH-H5793-A11","no":11,"noLabel":{"en":"Section 11."},"text":{"en":"Administrative Charges. - Administrative charges against a public health workers shall be heard by a committee composed of the provincial health officer of the province where the public health worker belongs, as chairperson, a representative of any existing national or provincial public health workers' organization or in its absence its local counterpart and a supervisor of the district, the last two (2) to be designated by the provincial health officer mentioned above. The committee shall submit its findings and recommendations to the Secretary of Health within thirty (30) days from the termination of the hearings. Where the provincial health officer is an interested party, all the members of the committee shall be appointed by the Secretary of Health."}},{"id":"PH-H5793-A12","no":12,"noLabel":{"en":"Section 12."},"text":{"en":"Safeguards in Disciplinary Procedures. - In every disciplinary proceeding, the public health worker shall have:\na) the right to be informed, in writing, of the charges;\nb) the right to full access to the evidence in the case;\nc) the right to defend himself/herself and to be defended by a representative of his/her choice and/or by his/her organization, adequate time being given to the public health worker for the preparation of his/her defense;\nd) the right to confront witnesses presented against him/her and summon witnesses in his/her behalf;\ne) the right to appeal to designated authorities;\nf) the right to reimbursement of reasonable expenses incurred in his/her defense in case of exoneration or dismissal of the charges; and\ng) such other rights as will ensure fairness and impartiality during proceedings."}},{"id":"PH-H5793-A13","no":13,"noLabel":{"en":"Section 13."},"text":{"en":"Duties and Obligations. - The public health workers shall:\na) discharge his/her duty humanely with conscience and dignity;\nb) perform his/her duty with utmost respect for life; and\nc) exercise his/her functions without consideration to race, gender, religion, nationality, party politics, social standing or capacity to pay."}},{"id":"PH-H5793-A14","no":14,"noLabel":{"en":"Section 14."},"text":{"en":"Code of Conduct. - Within six (6) months from the approval of this Act, the Secretary of Health, upon consultation with other appropriate agencies, professional and health worker's organization, shall formulate and prepare a Code of Conduct for Public Health Workers, which shall be disseminated as widely as possible."}},{"id":"PH-H5793-A15","no":15,"noLabel":{"en":"Section 15."},"text":{"en":"Normal Hours of Work. - The normal hours of work of any public health worker shall not exceed eight (8) hours a day or forty (40) hours a week.\nHours worked shall include: a) all the time during which a public health worker is required to be on active duty or to be at a prescribed workplace; and b) all the time during which a public health worker is suffered or permitted to work; Provided, that, the time when a public health worker is placed on \"On Call\" status shall not be considered as hours worked but shall entitle the public health worker to an \"On Call\" pay equivalent to fifty percent (50%) of his/her regular wage. \"On Call\" status refers to a condition when public health workers are called upon to respond to urgent or immediate need for health/medical assistance or relief work during emergencies such that he/shall cannot devote the time for his/her own use."}},{"id":"PH-H5793-A16","no":16,"noLabel":{"en":"Section 16."},"text":{"en":"Overtime Work. - Where the exigencies of the service so require, any public health worker may be required to render service beyond the normal eight (8) hours a day. In such a case, the workers shall be paid an additional compensation in accordance with existing laws and prevailing practices."}},{"id":"PH-H5793-A17","no":17,"noLabel":{"en":"Section 17."},"text":{"en":"Work During Rest Day. -\na) Where a public health worker is made to work on his/her scheduled rest day, he/she shall be paid an additional compensation in accordance with existing laws.\nb) Where a public health worker is made to work on any special holiday he/she shall be paid an additional compensation in accordance with existing laws. Where such holiday work falls on the worker's scheduled rest day, he/she shall be entitled to an additional compensation as may be provided by existing laws."}},{"id":"PH-H5793-A18","no":18,"noLabel":{"en":"Section 18."},"text":{"en":"Night-Shift Differential. - a) Every public health worker shall be paid a night-shift differential of ten percent (10%) of his/her regular wage for each hour of work performed during the night-shifts customarily adopted by hospitals.\nb) Every health worker required to work on the period covered after his/her regular schedule shall be entitled to his/her regular wage plus the regular overtime rate and an additional amount of ten percent (10%) of such overtime rate for each hour of work performed between ten (10) o'clock in the evening to six (6) o'clock in the morning."}},{"id":"PH-H5793-A19","no":19,"noLabel":{"en":"Section 19."},"text":{"en":"Salaries. - In the determination of the salary scale of public health workers, the provisions of Republic Act No. 6758 shall govern, except that the benchmark for Rural Health Physicians shall be upgraded to Grade 24.\na) Salary Scale - Salary scales of public health workers shall be provided progression: provided, that the progression from the minimum to maximum of the salary scale shall not extend over a period of ten (10) years: provided, further, that the efficiency rating of the public health worker concerned is at least satisfactory.\nb) Equality in Salary Scale - The salary scales of public health workers whose salaries are appropriated by a city, municipality, district, or provincial government shall not be less than those provided for public health workers of the National Government: provided, that the National Government shall subsidize the amount necessary to pay the difference between that received by nationality-paid and locally-paid health workers of equivalent positions.\nc) Salaries to be Paid in Legal Tender - Salaries of public health workers shall be paid in legal tender of the Philippines or the equivalent in checks or treasury warrants: provided, however, that such checks or treasury warrants shall be convertible to cash in any national, provincial, city or municipal treasurers' office or any banking institution operating under the laws of the Republic of the Philippines.\nd) Deductions Prohibited - No person shall make any deduction whatsoever from the salaries of public health workers except under specific provision of law authorizing such deductions: provided, however, that upon written authority executed by the public health worker concerned, a) lawful dues or fees owing to any organization/ association where such public health worker is an officer or member; and b) premiums properly due all insurance policies, retirement and medicare shall be considered deductible."}},{"id":"PH-H5793-A20","no":20,"noLabel":{"en":"Section 20."},"text":{"en":"Additional Compensation. - Notwithstanding Section 12 of Republic Act No. 6758, public health workers shall receive the following allowances: hazard allowance, subsistence allowance, longevity pay, laundry allowance and remote assignment allowance."}},{"id":"PH-H5793-A21","no":21,"noLabel":{"en":"Section 21."},"text":{"en":"Hazard Allowance. - Public health workers in hospitals, sanitaria, rural health units, main health centers, health infirmaries, barangay health stations, clinics and other health-related establishments located in difficult areas, strife-torn or embattled areas, distressed or isolated stations, prisons camps, mental hospitals, radiation-exposed clinics, laboratories or disease-infested areas or in areas declared under state of calamity or emergency for the duration thereof which expose them to great danger, contagion, radiation, volcanic activity/eruption, occupational risks or perils to life as determined by the Secretary of Health or the Head of the unit with the approval of the Secretary of Health, shall be compensated hazard allowances equivalent to at least twenty-five percent (25%) of the monthly basic salary of health workers receiving salary grade 19 and below, and five percent (5%) for health workers with salary grade 20 and above."}},{"id":"PH-H5793-A22","no":22,"noLabel":{"en":"Section 22."},"text":{"en":"Subsistence Allowance. - Public health workers who are required to render service within the premises of hospitals, sanitaria, health infirmaries, main health centers, rural health units and barangay health stations, or clinics, and other health-related establishments in order to make their services available at any and all times, shall be entitled to full subsistence allowance of three (3) meals which may be computed in accordance with prevailing circumstances as determined by the Secretary of Health in consultation with the Management-Health Worker's Consultative Councils, as established under Section 33 of this Act: provided, that representation and travel allowance shall be given to rural health physicians as enjoyed by municipal agriculturists, municipal planning and development officers and budget officers."}},{"id":"PH-H5793-A23","no":23,"noLabel":{"en":"Section 23."},"text":{"en":"Longevity Pay. - A monthly longevity pay equivalent to five percent (5%) of the monthly basic pay shall be paid to a health worker for every five (5) years of continuous, efficient and meritorious services rendered as certified by the chief of office concerned, commencing with the service after the approval of this Act."}},{"id":"PH-H5793-A24","no":24,"noLabel":{"en":"Section 24."},"text":{"en":"Laundry Allowance. - All public health workers who are required to wear uniforms regularly shall be entitled to laundry allowance equivalent to One hundred twenty-five pesos (P125.00) per month: provided, that this rate shall be reviewed periodically and increased accordingly by the Secretary of Health in consultation with the appropriate government agencies concerned taking into account existing laws and prevailing practices."}},{"id":"PH-H5793-A25","no":25,"noLabel":{"en":"Section 25."},"text":{"en":"Remote Assignment Allowance. - Doctors, dentists, nurses, and midwives who accept assignments as such in remote areas or isolated stations, which for reasons of far distance or hard accessibility, such positions had not been filled for the last two (2) years prior to the approval of this Act, shall be entitled to an incentive bonus in the form of remote assignment allowance equivalent to fifty percent (50%) of their basic pay, and shall be entitled to reimbursement of the cost of reasonable transportation to and from such remote post or station, upon assuming or leaving such position and during official trips.\nIn addition to the above, such doctors, dentists, nurses, and midwives mentioned in the preceding paragraph shall be given priority in promotion or assignment to better areas. Their tour of duties in the remote areas shall not exceed two (2) years, except when there are no positions for their transfer or they prefer to stay in such posts in excess of two (2) years."}},{"id":"PH-H5793-A26","no":26,"noLabel":{"en":"Section 26."},"text":{"en":"Housing. - All public health workers who are on tour of duty and those who, because of unavoidable circumstances are forced to stay in the hospital, sanitaria or health infirmary premises shall be entitled to free living quarters within the hospital, sanitarium or health infirmary or if such quarters are not available, shall receive quarters allowance as may be determined by the Secretary of Health and other appropriate government agencies concerned: provided, that this rate shall be reviewed periodically and increased accordingly by the Secretary of Health in consultation with the appropriate government agencies concerned.\nFor purposes of this Section, the Department of Health is authorized to develop housing projects in its own lands, not otherwise devoted for other uses, for public health workers in coordination with appropriate government agencies."}},{"id":"PH-H5793-A27","no":27,"noLabel":{"en":"Section 27."},"text":{"en":"Medical Examination. - Compulsory medical examination shall be provided free of charge to all public health workers before entering the service in the Government or its subdivisions and shall be repeated once a year during the tenure of employment of all public health workers: provided, that where medical examination shows that medical treatment and/or hospitalization is necessary for those already in government service, the treatment and/or hospitalization including medicines shall be provided free either in a government or a private hospital by the government entity paying the salary of the public health worker: provided, further, that the cost of such medical examination and treatment shall be included as automatic appropriation in said entity's annual budget."}},{"id":"PH-H5793-A28","no":28,"noLabel":{"en":"Section 28."},"text":{"en":"Compensation for Injuries. - Public health workers shall be protected against the consequences of employment injuries in accordance with existing laws. Injuries incurred while doing overtime work shall be presumed work-connected."}},{"id":"PH-H5793-A29","no":29,"noLabel":{"en":"Section 29."},"text":{"en":"Leave Benefits for Public Health Workers. - Public health workers are entitled to such vacation and sick leaves as provided by existing laws and prevailing practices: provided, that in addition to the leave privilege now enjoyed by public health workers, women health workers are entitled to such maternity leaves provided by existing laws and prevailing practices: provided, further, that upon separation of the public health workers from service, they shall be entitled to all accumulated leave credits with pay."}},{"id":"PH-H5793-A30","no":30,"noLabel":{"en":"Section 30."},"text":{"en":"Highest Basic Salary Upon Retirement. - Three (3) months prior to the compulsory retirement, the public health worker shall automatically be granted one (1) salary range or grade higher than his/her basic salary and his/her retirement benefit thereafter computed on the basis of his/her highest salary: provided, that he/she has reached the age and fulfilled service requirements under existing laws."}},{"id":"PH-H5793-A31","no":31,"noLabel":{"en":"Section 31."},"text":{"en":"Right to Self-Organization. - Public health workers shall have the right to freely form, join or assist organizations or unions for purposes not contrary to law in order to defend and protect their mutual interests and to obtain redress of their grievances through peaceful concerted activities.\nHowever, while the State recognizes the right of public health workers to organize or join such organizations, public health workers on-duty cannot declare, stage or join any strike or cessation of their service to patients in the interest of public health, safety or survival of patients."}},{"id":"PH-H5793-A32","no":32,"noLabel":{"en":"Section 32."},"text":{"en":"Freedom from Interference or Coercion. - It shall be unlawful for any person to commit any of the following acts of interference or coercion:\na) to require as a condition of employment that a public health worker shall not join a health workers' organization or union or shall relinquish membership therein:\nb) to discriminate in regard to hiring or tenure of employment or any item or condition of employment in order to encourage or discourage membership in any health workers' organization or union;\nc) to prevent a health worker from carrying out duties laid upon him/her by his/her position in the organization or union, or to penalize him/her for the action undertaken in such capacity:\nd) to harass or interfere with the discharge of the functions of the health worker when these are calculated to intimidate or to prevent the performance of his/her duties and responsibilities; and\ne) to otherwise interfere in the establishment, functioning, or administration of health worker's organizations or unions through acts designed to place such organization or union under the control of government authority."}},{"id":"PH-H5793-A33","no":33,"noLabel":{"en":"Section 33."},"text":{"en":"Consultation With Health Workers' Organizations. - In the formulation of national policies governing the social security of public health workers, professional and health workers' organizations or unions as well as other appropriate government agencies concerned shall be consulted by the Secretary of Health. For this purpose, Management-Health Workers' Consultative Councils for national, regional and other appropriate levels shall be established and operationalized."}},{"id":"PH-H5793-A34","no":34,"noLabel":{"en":"Section 34."},"text":{"en":"Health Human Resource Development/ Management Study. - The Department of Health shall conduct a periodic health human resource development/management study into, among others, the following areas:\na) adequacy of facilities and supplies to render quality health care to patients and other client population:\nb) opportunity for health workers to grow and develop their potentials and experience a sense of worth and dignity in their work. Public health workers who undertake postgraduate studies in a degree course shall be entitled to an upgrading in their position or raise in pay: provided, that it shall not be more often than every two (2) years;\nc) mechanisms for democratic consultation in government health institutions;\nd) staffing patterns and standards of health care to ensure that the people receive quality care. Existing recommendations on staffing and standards of health care shall be immediately and strictly enforced;\ne) ways and means of enabling the rank-and-file workers to avail of educational opportunities for personal growth and development;\nf) upgrading of working conditions, reclassification of positions and salaries of public health workers to correct disparity vis-a-vis other professions such that positions requiring longer study be upgraded and given corresponding pay scale; and\ng) assessment of the national policy on exportation of skilled health human resource to focus on how these resources could instead be utilized productively for the country's needs.\nThere is hereby created a Congressional Commission on Health (HEALTHCOM) to review and assess health human resource development, particularly on continuing professional education and training and the other areas described above. The Commission shall be composed of five (5) members of the House of Representatives and five (5) members of the Senate. It shall be co-chaired by the chairpersons of the Committee on Health of both houses. It shall render a report and recommendation to Congress which shall be the basis for policy legislation in the field of health. Such a congressional review shall be undertaken once every five (5) years."}},{"id":"PH-H5793-A35","no":35,"noLabel":{"en":"Section 35."},"text":{"en":"Rules and Regulations. - The Secretary of Health after consultation with appropriate agencies of the Government as well as professional and health workers' organizations or unions, shall formulate and prepare the necessary rules and regulations to implement the provisions of this Act. Rules and regulations issued pursuant to this Section shall take effect thirty (30) days after publication in a newspaper of general circulation."}},{"id":"PH-H5793-A36","no":36,"noLabel":{"en":"Section 36."},"text":{"en":"Prohibition Against Double Recovery of Benefits. - Whenever other laws provide for the same benefits covered by this Act, the public health worker shall have the option to choose which benefits will be paid to him/her, However, in the event that the benefits chosen are less than that provided under this Act, the worker shall be paid only the difference."}},{"id":"PH-H5793-A37","no":37,"noLabel":{"en":"Section 37."},"text":{"en":"Prohibition Against Elimination and/or Diminution. - Nothing in this law shall be construed to eliminate or in any way diminish benefits being enjoyed by public health workers at the time of the effectivity of this Act."}},{"id":"PH-H5793-A38","no":38,"noLabel":{"en":"Section 38."},"text":{"en":"Budgetary Estimates. - The Secretary of Health shall submit annually the necessary budgetary estimates to implement the provisions of this Act in staggered basis of implementation of the proposed benefits until the total of Nine hundred forty-six million six hundred sixty-four thousand pesos (P946,664,000.00) is attained within five (5) years.\nBudgetary estimates for the succeeding years should be reviewed and increased accordingly by the Secretary of Health in consultation with the Department of Budget and Management and the Congressional Commission on Health (HEALTHCOM)."}},{"id":"PH-H5793-A39","no":39,"noLabel":{"en":"Section 39."},"text":{"en":"Penal Provision. - Any person who shall willfully interfere with, restrain or coerce any public health worker in the exercise of his/her rights or shall in any manner commit any act in violation of any of the provisions of this Act, upon conviction, shall be punished by a fine of not less than Twenty thousand pesos (P20,000.00) but not more than Forty thousand pesos (P40,000.00) or imprisonment of not more than one (1) year or both at the discretion of the court.\nIf the offender is a public official, the court, in addition to the penalties provided in the preceding paragraph, may impose the additional penalty of disqualification from office."}},{"id":"PH-H5793-A40","no":40,"noLabel":{"en":"Section 40."},"text":{"en":"Separability Clause. - If any provision of this Act is declared invalid, the remainder of this Act or any provision not affected thereby shall remain in force and effect."}},{"id":"PH-H5793-A41","no":41,"noLabel":{"en":"Section 41."},"text":{"en":"Repealing Clause. - All laws, presidential decrees, executive orders and their implementing rules, inconsistent with the provisions of this Act are hereby repealed, amended or modified accordingly."}},{"id":"PH-H5793-A42","no":42,"noLabel":{"en":"Section 42."},"text":{"en":"Effectivity. - This Act shall take effect fifteen (15) days after its publication in at least two (2) national newspapers of general circulation."}}],"pack":"ph-p82","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"The Magna Carta of Public Health Workers","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H5794"] = {"id":"PH-H5794","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1992/ra_7306_1992.html","fetchedAt":"2026-10-06","articleCount":30,"structureMode":"ARTICLE","title":{"zh":"设立 People's Television Network，Incorporated 这一机构，界定其权力与职能，规定其资金来源与用途，并为其他目的作出规定的法案","en":"An Act Providing for the Establishment of the People's Television Network, Incorporated, Defining Its Powers and Functions, Providing for Its Sources of Funding and for Other Purposes","orig":"An Act Providing for the Establishment of the People's Television Network, Incorporated, Defining Its Powers and Functions, Providing for Its Sources of Funding and for Other Purposes"},"level":"law","status":"active","topics":["company"],"docNumber":"Republic Act No. 7306","issuingBody":"Congress of the Philippines","promulgatedDate":"1992-03-26","completenessNote":"全文，共 30 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1992/ra_7306_1992.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H5794-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Title . - This Act shall be known as the \"Charter of the People's Television Network, Incorporated\"."}},{"id":"PH-H5794-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"Declaration of Policies - In consonance with the Constitutional recognition of the vital role of communication and information in nation-building, and the important aspect played by the broadcasting industry, it is hereby declared as the policy . of the State to:\na. Fully develop communication structures suitable to the needs and aspirations of the nation and in accordance with a policy that respects the freedom of speech and of the press;\nb. Give priority to education, science and technology, arts, culture, and sports to foster patriotism and nationalism, accelerate social progress, and promote total human liberation and development;\nc. Develop the broadcasting industry as a medium for the development, promotion and advancement of Filipino nationalism, culture and values that serve as an instrument in the struggle for Filipino sovereignty, identity, national unity and integration;\nd. Harness the resources of the government and the private sector towards a close, continuous and balanced cooperation in order to take advantage of technological advances in the broadcasting industry;\ne. Maintain a broadcast industry system that serves as a vital link for participative democarcy and effective government information dissemination through developmental communication, free from any political or partisan influence and held accountable directly to the people;\nf. Encourage the development and broadcast of balanced programs which feature, among others, educational, wholesome entertainment, cultural, public affairs and sports; and\ng. Detach government television from advertising and commercial interest as far as practicable so as not to unduly compete with the private television sector and ensure that government television shall provide quality alternative programs for the benefit and moral upliftment of the citizenry.\nTITLE II - CREATION AND DOMICILE"}},{"id":"PH-H5794-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"Creation. - There shall be created a body corporate to be called \"The People's Television Network, Incorporated,\" hereinafter referred to as the \"Network,\" which shall engage in television broadcasting in the Philippines. The Network shall be a government-owned and controlled corporation under a Board of Directors to be appointed by the President of the Philippines."}},{"id":"PH-H5794-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"Corporate Existence. - The legal existence of the Network shall be for a period of fifty (50) years from the effectivity of this Act."}},{"id":"PH-H5794-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"Domicile. - The Network shall have its principal office and domicile in the Metropolitan Manila area. It may also establish offices, branches and/or stations in any part of the Philippines as its Board of Directors may see fit.\nTITLE III - FRANCHISE AND LICENSE TO OPERATE"}},{"id":"PH-H5794-A6","no":6,"noLabel":{"en":"Section 6."},"text":{"en":"Franchise Grant. - Subject to the provision of the Constitution, laws, orders, decrees not inconsistent herewith, the network is hereby granted a franchise to construct, maintain and operate television broadcasting stations and satellite receiving and transmitting facilities in the Philippines for a period co-terminous with the corporate existence of the Network."}},{"id":"PH-H5794-A7","no":7,"noLabel":{"en":"Section 7."},"text":{"en":"License to Operate. - The National Telecommunications Commission (NTC) shall forthwith cause the issuance to the Network of the corresponding licenses to operate upon compliance with all its requirements.\nTITLE IV - POWERS AND FUNCTIONS"}},{"id":"PH-H5794-A8","no":8,"noLabel":{"en":"Section 8."},"text":{"en":"Powers of the Network. - The Network shall have the following powers:\na. to sue or be sued in its corporate name;\nb. to have continuous succession in its corporate name;\nc. to adopt and use a corporate seal;\nd. to adopt by-laws, not contrary to law, morals, or public policy, and to amend or repeal the same in accordance with the provisions of existing laws;\ne. to purchase, receive, take or grant, hold, convey, sell lease, pledge, mortgage and otherwise deal with such real and personal property;\nf. to establish, purchase, install, construct, use and maintain national, regional, provincial and community stations and facilities for television broadcasting throughout and in any part of the country;\ng. to enter into joint ventures or partnerships with other broadcasting authorities and stations or international agencies or private organizations for the purpose of promoting its broadcasting services;\nh. to raise, borrow or obtain funds, from any source, private or government, foreign or domestic and to enter any financial or credit arrangements in order to support or carry out its objectives and purposes, subject to the pertinent laws governing public debt and expenditure;\ni. to receive donations and grants from any source whether local or foreign and avail of official development assistance and concessional loans provided by foreign governments, foundations, or financial institutions;\nj. to enter into, make, perform and carry out contracts of any kind and description in furtherance of the corporate purpose with any person, firm, association or corporation;\nk. to accept corporate institutional support for developmental programs and to determine the conditions subject to which the said programs may be accepted for television transmission; and\nl. to exercise the general powers outlined in the Corporation Code of the Philippines, as well as such other incidental powers as may be necessary to carry on its activities."}},{"id":"PH-H5794-A9","no":9,"noLabel":{"en":"Section 9."},"text":{"en":"Functions of the Network. - The Network shall have the following functions:\na. to serve primarily as a vehicle for the State for purposes of education, science and technology, arts, culture, and sports in order to foster national pride and identity;\nb. to serve as a vehicle for bringing the Government closer to the people in order to enhance their awareness of the programs, policies, thrusts, and directions of the Government;\nc. to ensure that the programs broadcast by the Network maintain a high general standard in all respects, and in particular, in respect to their content and quality and proper balance of educational, news, public affairs, entertainment, and sports programs;\nd. to serve as an effective outlet for alternative programming;\ne. to provide subsidized air time to legitimate people's organizations and NGOs in the promotion of their programs and projects;\nf. to serve as an effective medium for national unity and political stability by reaching as much of the Filipino population as possible through the effective use of modern broadcasting technology; and\ng. to ensure that nothing is included in the programs broadcast by the Network which shall:\n1. offend public morals, good taste, or decency;\n2. offend any racial group or promote ill-will between different races or different public groups, prescribing such programs as would promote strictly partisan politics and propaganda;\n3. offend the followers of any religious faith, sect, or order; or\n4. outrage public feeling in general.\nTITLE V - CORPORATE STRUCTURE"}},{"id":"PH-H5794-A10","no":10,"noLabel":{"en":"Section 10."},"text":{"en":"The Board of Directors. - The corporate powers of the Network shall be exercised, all its business conducted and all its property controlled and held by the Board of Directors. It shall be composed of five (5) members who shall be appointed by the President of the Philippines. The Board shall be made up of the following:\na. two (2) members from the Government sector;\nb. two (2) members from the private sector, one (1) of whom shall have at least ten (10) years of experience in the broadcast industry; and\nc. one (1) member from the education sector."}},{"id":"PH-H5794-A11","no":11,"noLabel":{"en":"Section 11."},"text":{"en":"Qualifications of the Members of the Board. - The members of the Board shall be of proven and unquestionable probity, integrity, honesty, impartiality, reputation, and knowledgeable of the broadcast industry. They shall not be, in any way, connected with any other broadcasting corporation or hold any position that may conflict with their functions and duties as Directors of the Network.\nIf a member shall be appointed to another government office or runs for any elective position, he shall be deemed to have vacated membership in the Board on the day of his appointment or filing of his candidacy, as the case maybe."}},{"id":"PH-H5794-A12","no":12,"noLabel":{"en":"Section 12."},"text":{"en":"Term of the Members of the Board. - The initial appointees of the President of the Philippines shall have the following terms:\na. Three (3) directors, one from each sector, for two (2) years; and\nb. The other two (2) directors, one (1) each from the government and private sector, for four (4) years.\nSubsequent appointees shall serve a term of four (4) years, without reappointment. Appointment to any vacancy in the Board shall be for the unexpired portion of the term of the predecessor.\nThe members shall elect among themselves one who will serve as Chairman of the Board. The Board shall meet at least twice a month to discuss matters of policy in order to effectively carry out the provisions of this Act."}},{"id":"PH-H5794-A13","no":13,"noLabel":{"en":"Section 13."},"text":{"en":"Functions and Duties of the Board of Directors. - The general functions and duties of the Board of Directors shall be as follows:\na. to carry out the provisions of this Act;\nb. to exercise the corporate powers, and conduct all business of the Network;\nc. to decide matters of policy; and\nd. to submit to the President of the Philippines and the Congress a comprehensive annual report on the operation of the Network within the first sixty (60) days of the fiscal year."}},{"id":"PH-H5794-A14","no":14,"noLabel":{"en":"Section 14."},"text":{"en":"The Network General Manager. - The Network General Manager shall be elected by the Board, of which he need not be a member. In the latter cases, he shall serve as an ex officio member of the Board. He shall also be the Chief Operating Officer of the Network, who shall be responsible for the proper administration and management of the Network in accordance with the policies laid down by the Board.\nIf the Network General Manager is absent, or is incapacitated by reason of illness or for any other cause, is temporarily unable to perform his duties, the Board of Directors may designate an officer-in-charge to act in his place and stead during such absence from duty."}},{"id":"PH-H5794-A15","no":15,"noLabel":{"en":"Section 15."},"text":{"en":"Powers and Functions of the Network General Manager. - Subject to the control and supervision of the Board, the Network General Manager shall have the following powers and functions:\na. submit policy recommendations and propose measures necessary to carry out the objectives and functions of the Network for the consideration of the Board;\nb. recommend to the Board for approval an organizational structure and plantilla for personnel of the Network, in accordance with existing laws, rules and regulations;\nc. execute, administer and implement policies and measures approved by the Board;\nd. Submit to the Board an annual budget and such supplemental budgets as may be necessary for its consideration and approval;\ne. represent the Network, its dealings with other persons, entities, agencies and institutions, whether public or private, domestic or foreign, subject to the limitations and conditions herein provided;\nf. appoint, subject to the confirmation by the Board, discipline or remove for cause, officers and personnel of the Network in accordance with the Civil Service Law, rules and regulations; and\ng. perform such other functions and duties which may be assigned to him by the Board.\nTITLE VI - PROGRAM AND STANDARDS"}},{"id":"PH-H5794-A16","no":16,"noLabel":{"en":"Section 16."},"text":{"en":"General Program Standards. - The Board of Directors is mandated to set up a Code of Standards, inclusive of the following aspects:\na. Presentations of news\nb. Public Affairs Programs and Commentaries\nc. Public Service Programs\nd. Educational Programs\ne. Children's Programs\nf. Agriculture and Livelihood Programs\ng. Women and Youth Issues\nh. Locally - produced and foreign produced programs."}},{"id":"PH-H5794-A17","no":17,"noLabel":{"en":"Section 17."},"text":{"en":"Use of Blocktimers. - The use of blocktimers shall be allowed but limited to education and sports programs only. The Network shall assume solidary liability with each of the individual producers, for the content of all programs shown by blocktimers.\nTITLE VII - FINANCIAL PROVISIONS"}},{"id":"PH-H5794-A18","no":18,"noLabel":{"en":"Section 18."},"text":{"en":"Capitalization. - The authorized capital stock of the Network shall be One Billion Pesos (P1,000,000,000.00) divided into one million (1,000,000.00) shares with the par value of One Thousand Pesos (P1,000.00) per share, which shall be subscribed in full by the Government.\nThe initial paid-up capital shall be One Hundred Million Pesos (P100,000,000.00) which shall be released from funds of the National Treasury upon the effectivity of this Act. The sums of One Hundred Million Pesos (P100,000,000.00) and Three Hundred Million Pesos (P300,000,000.00) are authorized to be appropriated as paid-up capital in the General Appropriations Act of the second and third years following the date of effectivity of this Act, respectively.\nThe unpaid balance of the authorized capital stock shall be appropriated as and when deemed necessary by Congress in the subsequent years."}},{"id":"PH-H5794-A19","no":19,"noLabel":{"en":"Section 19."},"text":{"en":"Revenue Generation. - The Network shall be allowed to generate funds from advertising and air time sales in accordance with the policies and rates set by the Board of Directors: Provided, That in the three (3) year period after the effectivity of this Act and every three (3) years thereafter, advertising sales shall not exceed seventy-five percent (75%), fifty percent (50%), and twenty-five percent (25%), respectively, of the average advertising sales of individual commercial stations: Provided, further, That no commercial advertising shall be allowed nine (9) years after the effectivity of this Act: Provided, finally, That institutional advertising and blocktime sales shall not be covered by this limitations. All fees or other revenues collected or received by the Network shall be retained by it and utilized solely for its operations.\nTITLE VIII - ADMINISTRATIVE PROVISIONS"}},{"id":"PH-H5794-A20","no":20,"noLabel":{"en":"Section 20."},"text":{"en":"Record of Transactions. - The Network shall keep proper accounts and records of all its transactions and affairs, and shall do all things necessary to ensure that all payments made out of its money are correctly made and properly authorized, and that adequate control is maintained over the assets of, or in the custody of, the Network and the expenditures incurred by the Network. The Network shall be subject to audit by the Commission on Audit.\nTITLE IX - TAX EXEMPTIONS"}},{"id":"PH-H5794-A21","no":21,"noLabel":{"en":"Section 21."},"text":{"en":"Tax Exemptions on Importations. - The importations of equipment, apparatus and materials to be actually, directly and exclusively used in the operation of the Network, whether purchased from or donated by any foreign government and/or private entity shall be free from the payment of any and all forms of taxes, license fees and customs duties that may be levied upon them. Such equipment and apparatus shall include cameras, TV monitors and recorders, TV transmitters, electronic tubes, editing machines, and all such necessary equipment required for television broadcasting: Provided, That the subsequent importation of the equipment, apparatus and materials shall be subject to review by the Department of Finance: Provided, further, That in the event the equipment, apparatus and materials are sold to non-tax exempt persons or entities, the buyers shall be considered the exporters and who shall then be subject to tax.\nTITLE X - EMPLOYEES OF THE NETWORK"}},{"id":"PH-H5794-A22","no":22,"noLabel":{"en":"Section 22."},"text":{"en":"Civil Service Law Coverage for Employees. - The hiring, appointment, employment, promotion, disciplinary control, and other terms and conditions of the service of all employees of the Network, and such other matter affecting its employees shall be consistent with the provisions of the Civil Service Law, rules and regulations."}},{"id":"PH-H5794-A23","no":23,"noLabel":{"en":"Section 23."},"text":{"en":"Salary Scale for Officials and Employees. - The rates of compensation and classes of positions in the Network shall not be covered by Republic Act No. 6758 and the Compensation and Position Classification Board (CPCB)."}},{"id":"PH-H5794-A24","no":24,"noLabel":{"en":"Section 24."},"text":{"en":"GSIS Coveragefor Employees. - All employees hired by the Network shall be deemed members of the Government Service Insurance System (GSIS) for the purpose of employees benefits.\nTITLE XI - MISCELLANEOUS PROVISIONS"}},{"id":"PH-H5794-A25","no":25,"noLabel":{"en":"Section 25."},"text":{"en":"Transition Clause. - All the powers, functions, assets and liabilities, capital, accounts, contracts, and facilities pertaining to the People's Television-4 (PTV-4), and all equipment relating to television broadcasting owned by the government shall be transferred to the Network."}},{"id":"PH-H5794-A26","no":26,"noLabel":{"en":"Section 26."},"text":{"en":"Transitory Provision. - The Network General Manager shall recommend to the Board of Directors a corporate plan that includes programming direction, budget, organizational plan and structure, a staffing pattern and compensation plan within ninety (90) days from the effectivity of this Act. Said corporate structure shall be implemented by the Network General Manager within thirty (30) days after its approval by the Board of Directors: Provided, That the current and incumbent employees of the People's Television-4 (PTV-4) shall be absorbed and accommodated by the Network."}},{"id":"PH-H5794-A27","no":27,"noLabel":{"en":"Section 27."},"text":{"en":"Amendments. - The provisions of this Act shall be subject to amendments, alteration or repeal by the Congress of the Philippines, when public interest so requires."}},{"id":"PH-H5794-A28","no":28,"noLabel":{"en":"Section 28."},"text":{"en":"Separability Clause . - If any provision or part of this Act is declared invalid or unconstitutional, the remainder shall not be effected thereby and shall continue to be in full force and effect."}},{"id":"PH-H5794-A29","no":29,"noLabel":{"en":"Section 29."},"text":{"en":"Repealing Clause . - All laws, decrees, executive orders, administrative orders, rules and regulations, and other issuances or parts thereof inconsistent herewith are hereby repealed, amended or modified accordingly."}},{"id":"PH-H5794-A30","no":30,"noLabel":{"en":"Section 30."},"text":{"en":"Effectivity Clause. - This Act shall take effect fifteen (15) days after its publication in two (2) national newspapers of general circulation."}}],"pack":"ph-p82","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Providing for the Establishment of the People's Television Network, Incorporated, Defining Its Powers and Functions, Providing for Its Sources of Funding and for Other Purposes","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H5795"] = {"id":"PH-H5795","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1992/ra_7307_1992.html","fetchedAt":"2026-10-06","articleCount":22,"structureMode":"ARTICLE","title":{"zh":"设立菲律宾水牛中心以繁殖推广菲律宾水牛并为其他目的法案","en":"An Act Creating the Philippine Carabao Center to Propagate and Promote the Philippine Carabao and for Other Purposes","orig":"An Act Creating the Philippine Carabao Center to Propagate and Promote the Philippine Carabao and for Other Purposes"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 7307","issuingBody":"Congress of the Philippines","promulgatedDate":"1992-03-27","completenessNote":"全文，共 22 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1992/ra_7307_1992.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H5795-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Title . - This Act shall be known as the \"Philippine Carabao Act of 1992\"."}},{"id":"PH-H5795-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"Declaration of Policy . - The Constitution provides that the State shall develop a self-reliant and independent national economy effectively controlled by Filipinos. It also provides that the State shall support indigenous, appropriate, and self-reliant scientific and technological capabilities, and their application to the country's productive systems and national life. Towards this end, the State shall establish various programs to conserve, propagate and promote the Philippine carabao as a source of draft animal power, meat, milk and hide."}},{"id":"PH-H5795-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"Definition of Terms. - As used in this Act, the following terms shall mean:\na. \"Philippine Carabao Center\" refers to the National Carabao Center at the University of the Philippines at Los Baños, the other carabao centers in Luzon, Visayas and Mindanao, and those that will be created pursuant to this Act;\nb. \"Draft animal power\" refers to power provided by the carabao as a farm animal;\nc. \"Smallholder farmer\" refers to a farmer owning or cultivating five (5) hectares or less of farmland;\nd. \"Semi-Commercial Production\" refers to the raising of twenty (20) to forty-nine (49) carabaos."}},{"id":"PH-H5795-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"Creation of the Philippine Carabao Center. - There is hereby created a Philippine Carabao Center, hereinafter referred to as the PCC which shall be under the supervision and control of the Department of Agriculture."}},{"id":"PH-H5795-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"Powers and Functions of the PCC. - The PCC shall have the following powers and functions:\na. Conserve, propagate and promote the Philippine carabao as a source of draft animal power, meat, milk and hide;\nb. Enable the farmers, particularly smallholder farmers and CARP beneficiaries to avail themselves of good quality carabao stocks at all times and at reasonable prices through an organized program of production, breeding, training and dispersal;\nc. Undertake training programs for farmers, particularly smallholder farmers and CARP beneficiaries, designed to transfer technology on the proper care and reproduction of the carabao and the processing of its meat and milk;\nd. Encourage backyard dairy development in rural areas by raising carabaos so as to meet the nutritional needs of the smallholder farmers and their families and reduce dependence on imported milk by-products;\ne. Undertake research activities in all disciplines that lead to the improvements of the over-all productivity of the Philippine carabao;\nf. Increase the existing annual population growth of the Philippine carabao to keep pace with human population growth; and\ng. Enter into memoranda of agreement and receive donations through the Department of Agriculture from local and foreign sources. Upon the recommendation of the PCC Advisory Board, the individual carabao centers may enter into agreements directly with funding agencies through their respective board regents or head of agency."}},{"id":"PH-H5795-A6","no":6,"noLabel":{"en":"Section 6."},"text":{"en":"Priorities. - The PCC shall give priority to the following activities:\na. Increase in carabao population and productivity;\nb. Development of feeding systems for backyard and semi-commercial production, improving reproductive efficiency, physiology and schemes to reduce losses caused by parasites and diseases;\nc. Reproduction, breeding, nutrition and animal health;\nd. Socioeconomic researches to ensure economic viability and acceptance of technology by farmers; and\ne. Development of appropriate technologies that are cost-effective, simple and practical.\nAt least thirty (30) to fifty (50) percent of the carabaos maintained/propagated by each carabao center shall be of the pure native/indigenous stock to ensure the preservation of the Philippine carabao and provide option to the farmers."}},{"id":"PH-H5795-A7","no":7,"noLabel":{"en":"Section 7."},"text":{"en":"PCC Advisory Board. - The PCC Advisory Board shall be composed of the following:\na. Secretary of the Department of Agriculture or his representative, as Chairman;\nb. Undersecretary for Regional Operations, Department of Agriculture, as Vice Chairman;\nc. Executive Director, Philippine Council for Agriculture, Forestry and Natural Resources, Research and Development (PCARRD);\nd. Chancellor of the University of the Philippines in Los Baños (UPLB) and presidents of Central Luzon State University (CLSU), Central Mindanao University (CMU), Cagayan State University (CSU), Don Mariano Marcos Memorial State University (DMMMSU) in La Union, Visayas State College of Agriculture (VISCA), West Visayas State University in Iloilo, University of Southern Mindanao (USM), and the president of the state college or university where a carabao center may be established pursuant to this Act;\ne. Director of the Bureau of Animal Industry;\nf. Executive Director of PCC; and\ng. Farmers' representative to be appointed by the Board."}},{"id":"PH-H5795-A8","no":8,"noLabel":{"en":"Section 8."},"text":{"en":"Functions of the PCC Advisory Board. - The PCC Advisory Board shall perform the following functions:\na. Formulate policies, programs and projects for the development of the Philippine carabao;\nb. Review and recommend the annual budget of the PCC;\nc. Evaluate the implementation, efficiency and effectiveness of the programs and projects of the PCC; and\nd. Recommend the establishment or abolition of carabao centers as may be deemed necessary."}},{"id":"PH-H5795-A9","no":9,"noLabel":{"en":"Section 9."},"text":{"en":"Executive Director of PCC. - The Executive Director of the PCC shall be appointed by the Secretary of the Department of Agriculture.\nThe Executive Director of the PCC shall perform the following functions:\na. Oversee the implementation of the policies, programs and projects of the PCC;\nb. Assist the PCC Advisory Board in the review, evaluation and monitoring of the Carabao Program; and\nc. Perform such other functions as may be assigned by the PCC Advisory Board."}},{"id":"PH-H5795-A10","no":10,"noLabel":{"en":"Section 10."},"text":{"en":"Appointment of Directors or Project Leaders of Other Carabao Centers. - The Directors or Project Leaders of the carabao centers shall be appointed by the respective board of regents or head of agency."}},{"id":"PH-H5795-A11","no":11,"noLabel":{"en":"Section 11."},"text":{"en":"Functions of the Directors or Project Leaders of Other Carabao Centers. - Subject to the policies of the PCC, the Directors or Project Leaders of other carabao centers shall perform the following functions:\na. Administer the policies, programs and projects of the PCC in their respective centers;\nb. Recommend the creation of divisions and sections including the staffing pattern of the centers;\nc. Prepare the budget of their centers;\nd. Approve the expenditures of their respective budgets;\ne. Recommend to their respective head of agency the appointment of personnel or consultants;\nf. Recommend policies, programs and projects to the Executive Director of the PCC; and\ng. Perform such other functions as may be assigned by the Executive Director of the PCC."}},{"id":"PH-H5795-A12","no":12,"noLabel":{"en":"Section 12."},"text":{"en":"Implementation and Coordination of the Program. -The PCC Advisory Board through the Executive Director shall coordinate, monitor and evaluate the implementation of the carabao program.\nIt shall identify, through the Directors of carabao centers and Project Leaders from the various implementing stations, the programs and projects in the areas of reproduction, breeding, distribution, nutrition, animal health, and processing of carabao meat and milk. It shall formulate strategies relative to the reproduction and distribution of the Philippine carabao.\nLuzon, Visayas and Mindanao shall initially have a total of thirteen (13) carabao centers. The centers in Luzon shall be located at U.P. Los Baños (UPLB) in Laguna; Central Luzon State University (CLSU) in Nueva Ecija; Cagayan State University (CSU) in Cagayan; Don Mariano Marcos Memorial State University (DMMMSU) in Ilocos Norte; and Don Mariano Marcos Memorial State University (DMMMSU), in La Union. The centers in Visayas shall be at La Carlota Stock Farm in Negros Occidental; Ubay Stock Farm in Bohol; Visayas State College of Agriculture (VISCA) in Leyte; and West Visayas State University in Iloilo. The centers in Mindanao shall be at Central Mindanao University (CMU) in Bukidnon; University of Southern Mindanao (USM) in Cotabao; Mindanao State University in Marawi City and Mindanao Livestock Development Complex in Kalawit, Labason, Zamboanga del Norte. These centers shall specialize in the development of technology on reproduction, breeding, nutrition, animal health and processing of meat and milk."}},{"id":"PH-H5795-A13","no":13,"noLabel":{"en":"Section 13."},"text":{"en":"Farmer's Participation. - The farmer-participants shall be encouraged to establish strong farmers' associations or cooperatives to serve as focal point for government assistance in the propagation and dispersal of Philippine carabaos and the dissemination of technology on the carabao."}},{"id":"PH-H5795-A14","no":14,"noLabel":{"en":"Section 14."},"text":{"en":"Beneficiaries. - The beneficiaries of the CARP and those under Presidential Decree No. 27, and other smallholder farmers shall be given priority in the carabao dispersal program."}},{"id":"PH-H5795-A15","no":15,"noLabel":{"en":"Section 15."},"text":{"en":"Participation of the Department of Agriculture and Local Government Units. - The carabao centers, the regional and provincial offices of the Department of Agriculture, specifically the Bureau of Animal Industry, and the local government units shall implement a carabao dispersal and propagation program within their respective areas in accordance with the national policy and program of the PCC. The PCC shall adopt a national dispersal program to primarily benefit the smallholder farmers and CARP beneficiaries.\nAny income from the sale of the carabao shall be placed in a revolving fund to be used in the propagation and distribution of carabaos."}},{"id":"PH-H5795-A16","no":16,"noLabel":{"en":"Section 16."},"text":{"en":"Use of Funds. - Not more than thirty percent (30%) of funds allocated under this Act and in subsequent annual appropriations shall be used for personal services, and maintenance and operating expenses, ten percent (10%) for research and development, sixty percent (60%) for carabao dispersal and distribution."}},{"id":"PH-H5795-A17","no":17,"noLabel":{"en":"Section 17."},"text":{"en":"Annual Report. - The PCC shall submit an annual report to the Office of the President, the Senate, and the House of Representatives indicating among others the number of carabaos distributed and the names of the beneficiaries."}},{"id":"PH-H5795-A18","no":18,"noLabel":{"en":"Section 18."},"text":{"en":"Transfer of Carabao Programs to the PCC. - Upon approval of this Act, the existing carabao programs and projects implemented by various agencies shall be transferred to the PCC."}},{"id":"PH-H5795-A19","no":19,"noLabel":{"en":"Section 19."},"text":{"en":"Appropriation. - The amount necessary to carry out the provisions of this Act shall be included in the General Appropriations Act of the year following its enactment into law and thereafter."}},{"id":"PH-H5795-A20","no":20,"noLabel":{"en":"Section 20."},"text":{"en":"Separability Clause . - If any part, section, or provision of this Act shall be held invalid or unconstitutional, the rest of the provisions shall not be affected thereby."}},{"id":"PH-H5795-A21","no":21,"noLabel":{"en":"Section 21."},"text":{"en":"Repealing Clause . - All laws, executive orders, rules and regulations, or part thereof which are inconsistent with this Act are hereby repealed or modified accordingly: Provided; however, That nothing in this Act shall amend, modify or repeal the provisions of Republic Act No. 7160, otherwise known as the Local Government Code."}},{"id":"PH-H5795-A22","no":22,"noLabel":{"en":"Section 22."},"text":{"en":"Effectivity . - This Act shall take effect fifteen (15) days from the date of its publication in the Official Gazette or in at least two (2) newspapers of general circulation."}}],"pack":"ph-p82","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Creating the Philippine Carabao Center to Propagate and Promote the Philippine Carabao and for Other Purposes","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H5796"] = {"id":"PH-H5796","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1992/ra_7308_1992.html","fetchedAt":"2026-10-06","articleCount":23,"structureMode":"ARTICLE","title":{"zh":"促进并发展菲律宾种子产业、设立国家种子产业委员会并为其他目的法案","en":"An Act to Promote and Develop the Seed Industry in the Philippines and Create a National Seed Industry Council and for Other Purposes","orig":"An Act to Promote and Develop the Seed Industry in the Philippines and Create a National Seed Industry Council and for Other Purposes"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 7308","issuingBody":"Congress of the Philippines","promulgatedDate":"1992-03-27","completenessNote":"全文，共 23 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1992/ra_7308_1992.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H5796-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Short Title . - This Act shall be known as the Seed Industry Development Act of 1992."}},{"id":"PH-H5796-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"Declaration of Policy . - It is hereby declared the policy of the State to promote and accelerate the development of the seed industry and, for this purpose, the Government shall:\na. conserve, preserve and develop the plant genetic resources of the nation;\nb. encourage and hasten the organization of all sectors engaged in the industry, integrate all their activities, and provide assistance to them;\nc. consider the seed industry as a preferred area of investment;\nd. encourage the private sector to engage in seed research and development and in mass production and distribution of good quality seeds; and\ne. provide the local seed industry protection against unfair competition from imported seeds."}},{"id":"PH-H5796-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"Definition of Terms. - When used in this Act, the following terms shall mean as follows:\na. \"Seed\" shall mean plant material used for the production of food, forage, fibers, industrial crops, oil, flowers, grasses, herbs and aquatic plants, including but not limited to meristem, and clonal propagules such as tubers, corms, cuttings, and micro-propagated plantlets;\nb. \"Seed lot\" shall mean a definite quantity of seeds identified by a lot number or other identification marks, or every portion of the bag or any container, the contents of which uniformly represent the factors which appear in the label within allowable tolerance;\nc. \"Breeder Seed\" shall mean a seed directly controlled by the originating, or in certain cases, the sponsoring plant, breeder or institution and which provide the source for the initial and recurring increase of foundation seeds;\nd. \"Foundation Seed\" shall mean seed that is a progeny of breeder seeds so handled as to maintain a minimum acceptable level of genetic purity and identity;\ne. \"Registered Seed\" shall mean the progeny of foundation seeds so handled as to maintain satisfactory genetic identity and purity;\nf. \"Seed Industry\" shall mean the different components of the chain of activities undertaken by an individual, association, cooperative, corporation or firm, academic institutions, public agricultural research institutes in the production, processing, testing, handling, grading, storage, distribution, and marketing of seeds for agricultural production with economic benefits;\ng. \"Seed Testing\" shall mean the accurate and prompt analysis of a seed sample based on methodologies prescribed by the Council to determine its quality;\nh. \"Seed Certification\" shall mean a system of seed production geared toward maintaining genetic identity, varietal purity and standards of quality seeds of superior crop varieties;\ni. \"Quality Control\" shall mean a systematic approach to determine, achieve and maintain desired standards of seed quality;\nj. \"Seed Sample\" shall mean a quantity of seeds drawn from seed lots in accordance with the rules for seed sampling to be promulgated under this Act, properly identified, labeled, and submitted for seed testing;\nk. \"Label\" shall mean any written, printed or graphic presentation in any manner on the seed container giving information as required in the rules and regulations promulgated under this Act;\nl. \"Seed Dealer/Trader/Merchant\" shall mean any person, firm, agency, cooperative or corporation engaged in the processing and/or marketing of seeds;\nm. \"Seed Grower/Producer\" shall mean any person, natural or juridical, engaged in the production, processing and/or marketing of seeds;\nn. \"Seed control\" shall mean the regulation of seed marketing through registration of seed merchants/dealers compulsory labeling and establishment of minimum standards of seed quality."}},{"id":"PH-H5796-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"National Seed Industry Council. - There is hereby created a National Seed Industry Council, hereinafter referred to as the \"Council\", to replace the existing Philippine Seed Board. The Council shall be composed of the following who, except for the representatives of the private sector shall serve is ex officio capacity.\na. Secretary, Department of Agriculture - Chairman\nb. Director, Bureau of Plant Industry - Vice Chairman and Executive Director.\nc. Dean, College of Agriculture University of the Philippines at Los Ba-os, Laguna - Member\nd. Director, Institute of Plant Breeding - Member\ne. Crop Research Director, Philippine Council for Agriculture Forestry and Natural Resources Research and Development - Member\nf. Director, Philippine Rice Research Institute - Member\ng. Two (2) representatives from accredited farmers' organizations.\nh. One (1) representative from the seed industry - Member The representatives of the sectors enumerated herein, who shall be nominated by their respective sectors or associations, shall be appointed by the Secretary of Agriculture and shall serve for a term of three (3) years. Only citizens of the Philippines shall be members of the Council. In case of vacancy the appointed successor shall serve only the unexpired portion of the term of his predecessor."}},{"id":"PH-H5796-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"Duties, Powers and Functions. - The Council shall have the following duties, powers and functions:\na. to formulate policies that will stimulate plant breeding activities for the development of the genetic resources of the country in accordance with the provisions of this Act;\nb. to encourage persons, associations, cooperatives and corporations engaged in genetic resources conservation, varietal development, production and processing, quality control, storage, marketing, and distribution of seeds to adopt systems and practices which improve the quality of seeds for distribution to farmers;\nc. to promote the establishment of infrastructures and other support services in priority areas geared toward the development of the seed industry;\nd. to formulate a comprehensive medium and long-term national seed industry development program in order to achieve self-sufficiency in the supply of high quality seeds;\ne. to grant awards, subsidies and other forms of assistance to seed or plant breeders who develop or are developing outstanding varieties or cultivars;\nf. to formulate policies that will stimulate plant breeding activities; and\ng. to promulgate rules and regulations to implement the provisions of this Act."}},{"id":"PH-H5796-A6","no":6,"noLabel":{"en":"Section 6."},"text":{"en":"Council Meetings. - The Council shall hold regular quarterly meetings: Provided, That it may hold special meetings when necessary upon the call of the Chairman or upon written request of at least three (3) members. The presence of five (5) members shall constitute a quorum.\nThe members of the Council shall not receive any compensation: Provided, That they shall be entitled to per diems and travel allowances, to be determined by the Council for every attendance in the meetings."}},{"id":"PH-H5796-A7","no":7,"noLabel":{"en":"Section 7."},"text":{"en":"Chairman, Duties and Responsibilities. - The Chairman of the Board shall have the following duties and responsibilities:\na. to preside over the meetings of the Council;\nb. to supervise the operations and administration of the Council; and\nc. to exercise such other functions and perform such other duties as may be vested in him by the Council."}},{"id":"PH-H5796-A8","no":8,"noLabel":{"en":"Section 8."},"text":{"en":"Executive Director, Duties and Responsibilities. - The Executive Director shall have the following duties and responsibilities:\na. to execute, direct and implement the policies, regulations and resolutions issued by the Council;\nb. to assist in the administration, management and supervision of the functional activities of the Council;\nc. to coordinate, monitor and evaluate the seed program of the different government agencies;\nd. to administer and manage the budgetary appropriations and financial disbursements of the Council; and\ne. to supervise the Council Secretariat and maintain official records, files and proceedings of the Council."}},{"id":"PH-H5796-A9","no":9,"noLabel":{"en":"Section 9."},"text":{"en":"Council Secretariat. - The Council shall have a Secretariat which shall furnish the necessary administration, secretarial and other support services to the Council. The Secretariat shall be under the direction and supervision of the Executive Director. The personnel of the Secretariat shall be appointed, and their compensation fixed by the Chairman upon the recommendation of the Executive Director in accordance with Civil Service rules and regulations."}},{"id":"PH-H5796-A10","no":10,"noLabel":{"en":"Section 10."},"text":{"en":"Technical Secretariat. - There is hereby created under the Council a Technical Secretariat which shall assume the functions of the existing Philippine Seed Board Technical Working Groups. The heads and the members of the Technical Secretariat shall be appointed and their compensation and tenure fixed by the Chairman upon the recommendation of the Executive Director.\nThe Technical Secretariat shall establish seed standards and formulate systems and procedures for varietal identification, evaluation, nomination, review and approval for registration, commercial release and discontinuation of crop cultivars or varieties in the National Agricultural Crop Production and Development Program."}},{"id":"PH-H5796-A11","no":11,"noLabel":{"en":"Section 11."},"text":{"en":"National Seed Quality Control Services. - There shall be a National Seed Quality Control Services, hereinafter referred to as \"Services\", which shall be constituted in the Bureau of Plant Industry. It shall have control and supervision over field inspection and control services, and seed testing laboratories which shall be established by the Bureau of Plant Industry in various parts of the country as are necessary to ensure the attainment of the purposes of this Act. All personnel, funds and equipment of the existing Seed Certification Section of the Bureau of Plant Industry, the seed quality control services and the field inspection services of the Department of Agriculture are hereby transferred to the herein created body."}},{"id":"PH-H5796-A12","no":12,"noLabel":{"en":"Section 12."},"text":{"en":"Functions of the National Seed Quality Control Services. - The National Seed Quality Control Services shall perform the following functions:\na. formulate plans and programs on seed quality control services and activities on seed testing, plant/seed material certification and other quality control schemes to be developed;\nb. sample and conduct seed analysis and issue the corresponding report of analysis of samples drawn from locally produced and imported seed within the purview of this Act;\nc. conduct field inspections of seed crops, seed storage and processing facilities and other activities required for seed/plant material certification and issue the corresponding report of inspection within the purview of this Act;\nd. conduct other related functions like seed research and seed technology training for its clientele;\ne. collect reasonable fees for testing of seeds, inspection of crop fields and facilities and for issuance of permits and licenses in relation to the activities of the Services;\nf. supervise and coordinate all official seed testing laboratories in the regions and provincial satellite laboratories and seed certification in all provinces and sub-provinces;\ng. accredit private seed testing laboratories; and\nh. perform such other functions as the Council may direct."}},{"id":"PH-H5796-A13","no":13,"noLabel":{"en":"Section 13."},"text":{"en":"Seed Industry Development Program. - The Council shall adopt within ninety (90) days after it has been constituted, a Seed Industry Development Program hereinafter referred to as the \"Program\", which shall be implemented by its constituent agencies.\na. A network of seed centers to be known as the National Seed Network shall be established at the Bureau of Plant Industry and major agricultural colleges and universities to produce sufficient quantity of breeder, foundation and registered seeds of all varieties developed by the government sector;\nb. The Department of Agriculture shall have the overall task of directing and coordinating the activities of its component agencies in accelerating the development of the seed industry;\nc. The Bureau of Plant Industry shall have the direct responsibility for the production, distribution, regulation of breeder, foundation and registered seeds, and the implementation of the program, including but not limited to the management of the existing research stations and seed farms, seed testing laboratories, and certification services under a self-reliant management scheme;\nd. The University of the Philippines at Los Ba-os shall provide leadership in plant biotechnology activities related to plant improvement, genetic resources conservation, and in vitro mass production of planting materials through the Institute of Plant Breeding (IPB);\ne. The Philippine Rice Research Institute (PHILRICE) shall develop an appropriate rice varieties designed under Philippine conditions and propagate them into breeder, foundation, and registered seeds and extend all necessary technical assistance to ensure the proper utilization of such seeds on the farm level;\nf. The Board of Investment (BOI) shall promulgate necessary rules for the development of the seed industry as preferred area of investment; and\ng. The private sector of the seed industry shall direct their collective efforts towards an increased and more active cooperation and coordination with the government agencies. Farmers' organizations shall take active part in the conservation of the plant genetic resources of the nation."}},{"id":"PH-H5796-A14","no":14,"noLabel":{"en":"Section 14."},"text":{"en":"Incentives. - The private sector may avail of the following incentives to develop the local seed industry:\na. Individuals, farmers' organizations, cooperatives, and corporations, wholly owned by Filipinos shall be entitled to technical assistance from the Government, including training in seed technology, and availment of seeds and results of basic research studies;\nb. Technical equipment used in seed processing, sowing, meristem culture, storage and quality testing by individuals, farmers' organizations, cooperatives and corporations, wholly owned by Filipinos shall be exempted from duties and taxes during their first five (5) years of operation subject to the following conditions:\n1. The equipment are not manufactured domestically in sufficient quantity of comparable quality and at reasonable prices;\n2. They are reasonably needed and will be used exclusively by the importer in the operation of its business;\n3. Approval of the Council was obtained prior to the importation;\n4. In case the importer transfers, sells, or disposes of the equipment within five (5) years from acquisition without prior approval of the Council the former shall be solidarily liable with the transferee to pay double the amount of tax exemption given it. The Council may permit transfer, sale or disposition of said equipment within the said five (5) years if made to another person or entity enjoying similar incentives, or for reason of proven technical obsolescence, or for purposes of replacement to improve and expand the operations of the importer;\n5. The importer shall not enjoy a similar incentive under the Omnibus Investments Code of 1987.\nHowever, cooperatives organized and registered under Republic Act No. 6938 shall be covered by Articles 61, 62, and 63 of the said law pertaining to the tax exemption privileges of cooperatives; and\n6. Expenses for research, development and extension of private Filipino seed producers shall enjoy a two hundred percent (200%) deduction from their gross income for the first five (5) years of operation in accordance with the rules and regulations to be promulgated by the Department of Finance within ninety (90) days from the effectivity of this Act."}},{"id":"PH-H5796-A15","no":15,"noLabel":{"en":"Section 15."},"text":{"en":"Restrictions. - The following acts are prohibited:\na. Importation in commercial quantities of species of seeds that are being produced locally, except seeds difficult to grow under ordinary conditions or when allowed by the Council;\nb. Exportation of rare species, varieties, lines and strains of plants from the country except for scientific or international exchange purposes which shall be determined by the Council; and\nc. Such other activities as the Council may deem fit to prohibit."}},{"id":"PH-H5796-A16","no":16,"noLabel":{"en":"Section 16."},"text":{"en":"Funds of the Council. - There is hereby created a special in the general fund to be known as the Seed Fund which shall be obtained from the following sources:\na. Five million pesos (P5,000,000.00) to be appropriated out of any funds in the National Treasury not otherwise appropriated;\nb. the existing Seed Fund;\nc. revenues from the sale of certified seeds and plant materials, including but not limited to the income derived from the products of research stations and seed farms, seed processing and testing fees, field inspection fees, seed export and import fees, license fees, fees for the issuance of permits to seed growers/producers, fines collected for violations of this Act; and\nd. donations from private or government agencies, either domestic or foreign: Provided, That said fund shall be held in trust by the Bureau of Plant Industry; Provided, further, That the allocation, utilization and disposition of such funds shall be by and under the authority of the Council."}},{"id":"PH-H5796-A17","no":17,"noLabel":{"en":"Section 17."},"text":{"en":"Appropriations. - The amount necessary to carry out the provisions of this Act is hereby authorized to be appropriated in the General Appropriations Act of the year following its enactment into law and thereafter."}},{"id":"PH-H5796-A18","no":18,"noLabel":{"en":"Section 18."},"text":{"en":"Authority to Search and Condemn Unlawful Seed Lots. - In order to carry out effectively the provisions of this Act, the Executive Director of the Council is hereby authorized to search and seize seed lots labeled, identified or imported in violation of this Act; Provided, That a search warrant shall first be secured from the proper court and the same shall be served/enforced with the assistance of the Philippine National Police (PNP) or the National Bureau of Investigation.\nShould the seed lots so searched and seized be found after due hearing, to be suitable for condemnation, in his judgment, the Executive Director is hereby empowered to issue to any of his designated representatives an order for condemnation of unlawful seed lots, in which case the same shall be processed, relabeled or otherwise disposed of in such manner as he may deem appropriate: Provided, That in no case shall the Executive Director order such condemnation without giving the claimant an opportunity to apply for the release of said seed lot or permission to process it in compliance with this Act, subject to the payment of just compensation in the proper case."}},{"id":"PH-H5796-A19","no":19,"noLabel":{"en":"Section 19."},"text":{"en":"Penal Provisions. - Any person, firm, or association who shall violate any provision of this Act or the implementing rules and regulations promulgated pursuant to this Act, shall upon conviction, be punished with a fine of not more than Ten thousand pesos (P10,000.00) or imprisonment of not more than five (5) years, or both, in the discretion of the Court: Provided, That in the case of a firm or association, the penalty of imprisonment shall be imposed upon the officer(s) who knowingly participated, abetted, or consented to the commission of such punishable acts."}},{"id":"PH-H5796-A20","no":20,"noLabel":{"en":"Section 20."},"text":{"en":"Rules and Regulations. - The Council shall, within ninety (90) days from the effectivity of this Act, promulgate the necessary rules and regulations for the enforcement of the provisions of this Act."}},{"id":"PH-H5796-A21","no":21,"noLabel":{"en":"Section 21."},"text":{"en":"Repealing Clause . - All existing laws, rules and regulations or parts thereof inconsistent with the provisions of this Act are hereby repealed, superseded or modified accordingly: Provided,however, That nothing in this Act shall amend, modify or repeal the provisions of Republic Act No. 7160, otherwise known as the Local Government Code."}},{"id":"PH-H5796-A22","no":22,"noLabel":{"en":"Section 22."},"text":{"en":"Separability Clause . - If any part, section, or provision of this Act shall be held invalid or unconstitutional, the rest of the provisions shall not be affected thereby."}},{"id":"PH-H5796-A23","no":23,"noLabel":{"en":"Section 23."},"text":{"en":"Effectivity . - This Act shall take effect fifteen (15) days after its complete publication in the Official Gazette or in at least two (2) newspapers of general circulation."}}],"pack":"ph-p82","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act to Promote and Develop the Seed Industry in the Philippines and Create a National Seed Industry Council and for Other Purposes","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H5797"] = {"id":"PH-H5797","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1992/ra_7309_1992.html","fetchedAt":"2026-10-06","articleCount":12,"structureMode":"ARTICLE","title":{"zh":"在司法部下设立索赔委员会以处理遭不公正监禁或拘留者及暴力犯罪受害者并为其他目的法案","en":"An Act Creating a Board of Claims Under the Department of Justice for Victims of Unjust Imprisonment or Detention and Victims of Violent Crimes and for Other Purposes","orig":"An Act Creating a Board of Claims Under the Department of Justice for Victims of Unjust Imprisonment or Detention and Victims of Violent Crimes and for Other Purposes"},"level":"law","status":"active","topics":["judiciary"],"docNumber":"Republic Act No. 7309","issuingBody":"Congress of the Philippines","promulgatedDate":"1992-03-30","completenessNote":"全文，共 12 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1992/ra_7309_1992.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H5797-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Creation and Composition of the Board. – There is hereby created a Board of Claims under the Department of Justice, hereinafter referred to as the Board, to be composed of one (1) chairman and two (2) members to be appointed by the Secretary of the said department."}},{"id":"PH-H5797-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"Powers and Functions of the Board. – The Board shall have the following powers and functions:\n(a) to receive, evaluate, process and investigate application for claims under this Act;\n(b) to conduct an independent administrative hearing and resolve application for claims, grant or deny the same;\n(c) to deputize appropriate government agencies in order to effectively implement its functions; and\n(d) to promulgate rules and regulations in order to carry out the objectives of this Act."}},{"id":"PH-H5797-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"Who may File Claims. – The following may file claims for compensation before the Board:\n(a) any person who was unjustly accused, convicted and imprisoned but subsequently released by virtue of a judgment of acquittal;\n(b) any person who was unjustly detained and released without being charged;\n(c) any victim of arbitrary or illegal detention by the authorities as defined in the Revised Penal Code under a final judgment of the court; and\n(d) any person who is a victim of violent crimes. For purposes of this Act, violent crimes shall include rape and shall likewise refer to offenses committed with malice which resulted in death or serious physical and/or psychological injuries, permanent incapacity or disability, insanity, abortion, serious trauma, or committed with torture, cruelly or barbarity."}},{"id":"PH-H5797-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"Award Ceiling. – For victims of unjust imprisonment or detention, the compensation shall be based on the number of months of imprisonment or detention and every fraction thereof shall be considered one month; Provided, however, That in no case shall such compensation exceed One Thousand pesos (P1,000.00) per month.\nIn all other cases, the maximum amount for which the Board may approve a claim shall not exceed Ten thousand pesos (P10,000.00) or the amount necessary to reimburse the claimant the expenses incurred for hospitalization, medical treatment, loss of wage, loss of support or other expenses directly related to injury, whichever is lower. This is without prejudice to the right of the claimant to seek other remedies under existing laws."}},{"id":"PH-H5797-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"When to File Claims. – Any person entitled to compensation under this Act must, within six (6) months after being released from imprisonment or detention, or from the date the victim suffered damage or injury, file his claim with the Department, otherwise, he is deemed to have waived the same. Except as provided for in this Act, no waiver of claim whatsoever is valid."}},{"id":"PH-H5797-A6","no":6,"noLabel":{"en":"Section 6."},"text":{"en":"Filing of Claims by Heirs. – In case of death or incapacity of any person entitled to any award under this Act, the claim may be filed by his heirs, in the following order: by his surviving spouse, children, natural parents, brother and/or sister."}},{"id":"PH-H5797-A7","no":7,"noLabel":{"en":"Section 7."},"text":{"en":"Resolution of Claims. – The Board shall resolve the claim within thirty (30) working days after filing of the application.\nThe Board shall adopt an expeditious and inexpensive procedure for the claimants to follow in order to secure their claims under this Act."}},{"id":"PH-H5797-A8","no":8,"noLabel":{"en":"Section 8."},"text":{"en":"Appeal. – Any aggrieved claimant may appeal, within fifteen (15) days from receipt of the resolution of the Board, to the Secretary of Justice whose decision shall be final and executory."}},{"id":"PH-H5797-A9","no":9,"noLabel":{"en":"Section 9."},"text":{"en":"Funding. – For purposes of this Act, the initial amount of Ten million pesos (P10,000,000.00) is hereby authorized to be appropriated from the funds of the National Treasury not otherwise appropriated.\nThe subsequent annual funding shall also partly come from one percent (1%) of the net income of the Philippine Amusement and Gaming Corporation and one percent (1%) of the proceeds and sales and other disposition and military camps ion Metro Manila by the Base Conversion and Development Authority.\nThe proceeds from any contract relating to the depiction of a crime in a movie, book, newspaper, magazine, radio or television production, or live entertainment, of any kind, or in any other form of commercial exploitation of any convict's story, recollection, opinion and emotions with regard to the offense committed shall not be released to convict in a criminal case or his heirs, agents, assignees or successors in interest until full compensation for damages suffered by a awarded to, the victim, his heirs or successors in interest is paid or arranged for, and the state is able to collect/assess fines and costs and any other amounts due it in case of a conviction by final judgment. Such damages shall include, but shall not be limited to, judicial awards, funeral expenses, medical expenses, lost earning and the like.\nTo ensure the continuity of the funding requirements under this Act, the amount of Five pesos (P5.00) shall be set aside from each filing fee in every civil case filed with the court, the total proceeds of which shall constitute the Victim Compensation Fund to be administered by the Department of Justice."}},{"id":"PH-H5797-A10","no":10,"noLabel":{"en":"Section 10."},"text":{"en":"Repealing Clause. – All Laws, executive orders and executive issuances inconsistent with this Act are hereby deemed repealed or modified accordingly."}},{"id":"PH-H5797-A11","no":11,"noLabel":{"en":"Section 11."},"text":{"en":"Separability Clause. – If for any reason any section or provision of this Act shall be declared unconstitutional or invalid, no other section or provision shall be affected thereby."}},{"id":"PH-H5797-A12","no":12,"noLabel":{"en":"Section 12."},"text":{"en":"Effectivity Clause. – This Act shall take effect after its publication in two (2) newspapers of general circulation."}}],"pack":"ph-p82","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Creating a Board of Claims Under the Department of Justice for Victims of Unjust Imprisonment or Detention and Victims of Violent Crimes and for Other Purposes","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H5798"] = {"id":"PH-H5798","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1992/ra_7310_1992.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":"将北拉瑙省 伊利甘市 Pala-o 伊利甘市医院的名称变更为Gregorio T. Lluch，Sr.，纪念医院的法案","en":"An Act Changing the Name of the Iligan City Hospital in Pala-o, Iligan City, Province of Lanao Del Norte, to Gregorio T. Lluch, Sr., Memorial Hospital","orig":"An Act Changing the Name of the Iligan City Hospital in Pala-o, Iligan City, Province of Lanao Del Norte, to Gregorio T. Lluch, Sr., Memorial Hospital"},"level":"law","status":"active","topics":["health"],"docNumber":"Republic Act No. 7310","issuingBody":"Congress of the Philippines","promulgatedDate":"1992-03-30","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1992/ra_7310_1992.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H5798-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The name of the Iligan City Hospital in Pala-o, Iligan City, Province of Lanao del Norte, is hereby changed to Gregorio T. Lluch, Sr., Memorial Hospital."}},{"id":"PH-H5798-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect upon its approval."}}],"pack":"ph-p82","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Changing the Name of the Iligan City Hospital in Pala-o, Iligan City, Province of Lanao Del Norte, to Gregorio T. Lluch, Sr., Memorial Hospital","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H5799"] = {"id":"PH-H5799","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1992/ra_7311_1992.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":"将莱特省 Baybay市镇西部莱特医院的名称变更为Dr. Jose Silao 纪念医院的法案","en":"An Act Changing the Name of the Western Leyte Hospital in the Municipality of Baybay, Province of Leyte, to Dr. Jose Silao Memorial Hospital","orig":"An Act Changing the Name of the Western Leyte Hospital in the Municipality of Baybay, Province of Leyte, to Dr. Jose Silao Memorial Hospital"},"level":"law","status":"active","topics":["health"],"docNumber":"Republic Act No. 7311","issuingBody":"Congress of the Philippines","promulgatedDate":"1992-03-30","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1992/ra_7311_1992.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H5799-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The name of the Western Leyte Hospital in the Municipality of Baybay, Province of Leyte, is hereby changed to Dr. Jose Silao Memorial Hospital."}},{"id":"PH-H5799-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect upon its approval."}}],"pack":"ph-p82","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Changing the Name of the Western Leyte Hospital in the Municipality of Baybay, Province of Leyte, to Dr. Jose Silao Memorial Hospital","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H5800"] = {"id":"PH-H5800","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1992/ra_7312_1992.html","fetchedAt":"2026-10-06","articleCount":3,"structureMode":"ARTICLE","title":{"zh":"将索索贡省Magallanes市镇Magallanes医疗医院由15张床位的医疗医院扩建升级为25张床位的区医院，名称为Magallanes区医院，并为此拨款","en":"An Act Expanding and Upgrading the Magallanes Medicare Hospital in the Municipality of Magallanes, Province of Sorsogon, From a Fifteen-bed Capacity Medicare Hospital Into a Twenty-five-bed Capacity District Hospital, to Be Known as the Magallanes District Hospital, and Appropriating Funds Therefor","orig":"An Act Expanding and Upgrading the Magallanes Medicare Hospital in the Municipality of Magallanes, Province of Sorsogon, From a Fifteen-bed Capacity Medicare Hospital Into a Twenty-five-bed Capacity District Hospital, to Be Known as the Magallanes District Hospital, and Appropriating Funds Therefor"},"level":"law","status":"active","topics":["health"],"docNumber":"Republic Act No. 7312","issuingBody":"Congress of the Philippines","promulgatedDate":"1992-03-30","completenessNote":"全文，共 3 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1992/ra_7312_1992.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H5800-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The Magallanes Medicare Hospital in the Municipality of Magallanes, Province of Sorsogon, is hereby expanded and upgraded from a fifteen-bed capacity medicare hospital into a twenty-five-bed capacity district hospital, to be known as the Magallanes District Hospital."}},{"id":"PH-H5800-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The amount necessary to carry out the provisions of this Act shall be included in the General Appropriations Act of the year following its enactment into law and thereafter."}},{"id":"PH-H5800-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"This Act shall take effect upon its approval."}}],"pack":"ph-p82","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Expanding and Upgrading the Magallanes Medicare Hospital in the Municipality of Magallanes, Province of Sorsogon, From a Fifteen-bed Capacity Medicare Hospital Into a Twenty-five-bed Capacity District Hospital, to Be Known as the Magallanes District Hospital, and Appropriating Funds Therefor","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H5801"] = {"id":"PH-H5801","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1992/ra_7313_1992.html","fetchedAt":"2026-10-06","articleCount":3,"structureMode":"ARTICLE","title":{"zh":"设立Manukan市","en":"An Act Converting the Medicare Community Hospital in the Municipality of Manukan, Province of Zamboanga Del Norte, Into a Twenty-five-bed Capacity Hospital to Be Known as the Manukan District Hospital, and Appropriating Funds Therefor","orig":"An Act Converting the Medicare Community Hospital in the Municipality of Manukan, Province of Zamboanga Del Norte, Into a Twenty-five-bed Capacity Hospital to Be Known as the Manukan District Hospital, and Appropriating Funds Therefor"},"level":"law","status":"active","topics":["health"],"docNumber":"Republic Act No. 7313","issuingBody":"Congress of the Philippines","promulgatedDate":"1992-03-30","completenessNote":"全文，共 3 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1992/ra_7313_1992.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H5801-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The Medicare Community Hospital in the Municipality of Manukan, Province of Zamboanga del Norte, is hereby converted into a twenty-five-bed capacity hospital to be known as the Manukan District Hospital which shall be under the supervision of the Department of Health."}},{"id":"PH-H5801-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The amount necessary to carry out the provisions of this Act shall be charged against the lump-sum appropriations authorized for the purpose under the current General Appropriations Act. Thereafter, such sums as may be necessary for the operation and maintenance of the hospital shall be included in the annual General Appropriations Act."}},{"id":"PH-H5801-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"This Act shall take effect upon its approval."}}],"pack":"ph-p82"};
  FT["PH-H5802"] = {"id":"PH-H5802","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1992/ra_7314_1992.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":"将西内格罗斯省埃斯卡兰特市镇圣安娜描笼涯Sta. Ana小学的名称变更为Rosario C. Valdivia小学的法案","en":"An Act Changing the Name of the Sta. Ana Elementary School in Barangay Sta. Ana, Municipality of Escalante, Province of Negros Occidental, to Rosario C. Valdivia Elementary School","orig":"An Act Changing the Name of the Sta. Ana Elementary School in Barangay Sta. Ana, Municipality of Escalante, Province of Negros Occidental, to Rosario C. Valdivia Elementary School"},"level":"law","status":"active","topics":["administrative","education"],"docNumber":"Republic Act No. 7314","issuingBody":"Congress of the Philippines","promulgatedDate":"1992-03-30","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1992/ra_7314_1992.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H5802-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The name of the Sta. Ana Elementary School in Barangay Sta. Ana, Municipality of Escalante, Province of Negros Occidental, is hereby changed to Rosario C. Valdivia Elementary School."}},{"id":"PH-H5802-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect upon its approval."}}],"pack":"ph-p82","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Changing the Name of the Sta. Ana Elementary School in Barangay Sta. Ana, Municipality of Escalante, Province of Negros Occidental, to Rosario C. Valdivia Elementary School","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H5803"] = {"id":"PH-H5803","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1992/ra_7315_1992.html","fetchedAt":"2026-10-06","articleCount":4,"structureMode":"ARTICLE","title":{"zh":"设立Lutayan市","en":"An Act Establishing a High School in the Municipality of Lutayan, Province of Sultan Kudarat, to Be Known as the Lutayan High School, and Appropriating Funds Therefor","orig":"An Act Establishing a High School in the Municipality of Lutayan, Province of Sultan Kudarat, to Be Known as the Lutayan High School, and Appropriating Funds Therefor"},"level":"law","status":"active","topics":["education"],"docNumber":"Republic Act No. 7315","issuingBody":"Congress of the Philippines","promulgatedDate":"1992-03-30","completenessNote":"全文，共 4 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1992/ra_7315_1992.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H5803-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"There shall be established a high school in the Municipality of Lutayan, Province of Sultan Kudarat, to be known as the Lutayan High School."}},{"id":"PH-H5803-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The Secretary of the Department of Education, Culture and Sports shall issue such rules and regulations as may be necessary to carry out the purpose of this Act."}},{"id":"PH-H5803-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"The amount needed to carry out the provisions of this Act is hereby authorized to be appropriated in the General Appropriations Act of the year following its enactment into law and thereafter,"}},{"id":"PH-H5803-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"This Act shall take effect upon its approval."}}],"pack":"ph-p82"};
  FT["PH-H5804"] = {"id":"PH-H5804","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1992/ra_7316_1992.html","fetchedAt":"2026-10-06","articleCount":4,"structureMode":"ARTICLE","title":{"zh":"设立Kalamansig市","en":"An Act Establishing a High School in the Municipality of Kalamansig, Province of Sultan Kudarat, to Be Known as the Kalamansig High School, and Appropriating Funds Therefor","orig":"An Act Establishing a High School in the Municipality of Kalamansig, Province of Sultan Kudarat, to Be Known as the Kalamansig High School, and Appropriating Funds Therefor"},"level":"law","status":"active","topics":["education"],"docNumber":"Republic Act No. 7316","issuingBody":"Congress of the Philippines","promulgatedDate":"1992-03-30","completenessNote":"全文，共 4 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1992/ra_7316_1992.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H5804-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"There shall be established a high school in the Municipality of Kalamansig, Province of Sultan Kudarat, to be known as the Kalamansig High School."}},{"id":"PH-H5804-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The Secretary of the Department of Education, Culture and Sports shall issue such rules and regulations as may be necessary to carry out the purpose of this Act."}},{"id":"PH-H5804-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"The amount needed to carry out the provisions of this Act is hereby authorized to be appropriated in the General Appropriations Act of the year following its enactment into law and thereafter."}},{"id":"PH-H5804-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"This Act shall take effect upon its approval."}}],"pack":"ph-p82"};
  FT["PH-H5805"] = {"id":"PH-H5805","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1992/ra_7317_1992.html","fetchedAt":"2026-10-06","articleCount":4,"structureMode":"ARTICLE","title":{"zh":"设立Palimbang市","en":"An Act Establishing a High School in the Municipality of Palimbang, Province of Sultan Kudarat, to Be Known as the Palimbang High School, and Appropriating Funds Therefor","orig":"An Act Establishing a High School in the Municipality of Palimbang, Province of Sultan Kudarat, to Be Known as the Palimbang High School, and Appropriating Funds Therefor"},"level":"law","status":"active","topics":["education"],"docNumber":"Republic Act No. 7317","issuingBody":"Congress of the Philippines","promulgatedDate":"1992-03-30","completenessNote":"全文，共 4 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1992/ra_7317_1992.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H5805-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"There shall be established a high school in the Municipality of Palimbang, Province of Sultan Kudarat, to be known as the Palimbang High School."}},{"id":"PH-H5805-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The Secretary of the Department of Education, Culture and Sports shall issue such rules and regulations as may be necessary to carry out the purpose of this Act."}},{"id":"PH-H5805-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"The amount needed to carry out the provisions of this Act is hereby authorized to be appropriated in the General Appropriations Act of the year following its enactment into law and thereafter."}},{"id":"PH-H5805-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"This Act shall take effect upon its approval."}}],"pack":"ph-p82"};
  FT["PH-H5806"] = {"id":"PH-H5806","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1992/ra_7318_1992.html","fetchedAt":"2026-10-06","articleCount":4,"structureMode":"ARTICLE","title":{"zh":"设立Isulan市","en":"An Act Establishing a High School in the Municipality of Isulan, Province of Sultan Kudarat, to Be Known as the Isulan High School, and Appropriating Funds Therefor","orig":"An Act Establishing a High School in the Municipality of Isulan, Province of Sultan Kudarat, to Be Known as the Isulan High School, and Appropriating Funds Therefor"},"level":"law","status":"active","topics":["education"],"docNumber":"Republic Act No. 7318","issuingBody":"Congress of the Philippines","promulgatedDate":"1992-03-30","completenessNote":"全文，共 4 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1992/ra_7318_1992.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H5806-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"There shall be established a high school in the Municipality of Isulan, Province of Sultan Kudarat, to be known as the Isulan High School."}},{"id":"PH-H5806-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The Secretary of the Department of Education, Culture and Sports shall issue such rules and regulations as may be necessary to carry out the purpose of this Act."}},{"id":"PH-H5806-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"The amount needed to carry out the provisions of this Act is hereby authorized to be appropriated in the General Appropriations Act of the year following its enactment into law and thereafter."}},{"id":"PH-H5806-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"This Act shall take effect upon its approval."}}],"pack":"ph-p82"};
  FT["PH-H5807"] = {"id":"PH-H5807","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1992/ra_7319_1992.html","fetchedAt":"2026-10-06","articleCount":6,"structureMode":"ARTICLE","title":{"zh":"在朗布隆省 Torrijos、Gasan 与 Sta. Cruz 市镇设立农学院、渔业学院与朗布隆社区学院，作为朗布隆州立学院分校的法案","en":"An Act Establishing the College of Agriculture in Barangay Poctoy, Municipality of Torrijos; the College of Fisheries in Barangay Pinggan, Municipality of Gasan; and the Marinduque Community College in the Municipality of Sta. Cruz, All in the Province of Marinduque, as Branches of the Marinduque State College, Boac, Marinduque","orig":"An Act Establishing the College of Agriculture in Barangay Poctoy, Municipality of Torrijos; the College of Fisheries in Barangay Pinggan, Municipality of Gasan; and the Marinduque Community College in the Municipality of Sta. Cruz, All in the Province of Marinduque, as Branches of the Marinduque State College, Boac, Marinduque"},"level":"law","status":"active","topics":["environment","administrative","education"],"docNumber":"Republic Act No. 7319","issuingBody":"Congress of the Philippines","promulgatedDate":"1992-03-30","completenessNote":"全文，共 6 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1992/ra_7319_1992.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H5807-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The college of agriculture in Barangay Poctoy, Municipality of Torrijos; the college of fisheries in Barangay Pinggan, Municipality of Gasan; and the Marinduque Community College in the Municipality of Sta. Cruz, all in the Province of Marinduque, are hereby established as branches of the Marinduque State College."}},{"id":"PH-H5807-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"Upon approval of this Act, the college of agriculture in Barangay Poctoy, Municipality of Torrijos; the college of fisheries in Barangay Pinggan, Municipality of Gasan; and the Marinduque Community College in the Municipality of Sta. Cruz shall henceforth be known as the Marinduque State College, Torrijos Branch; the Marinduque State College, Gasan Branch; and the Marinduque State College, Sta. Cruz Branch, respectively."}},{"id":"PH-H5807-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"The personnel of the different colleges, the college of agriculture, the college of fisheries, and the Marinduque Community College, shall be absorbed by the Marinduque State College, subject to existing laws, rules and regulations.\nAll assets, fixed and movable, records, documents and other things of value belonging to the abovementioned colleges including their liabilities shall be turned over to the Marinduque State College."}},{"id":"PH-H5807-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"In addition to the current appropriations of the Marinduque Community College and the Marinduque State College, the amount needed to carry out the provisions of this Act shall be included in the General Appropriations Act of the year following its enactment into law and thereafter."}},{"id":"PH-H5807-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"All laws, decrees, rules and regulations, administrative orders and other issuances inconsistent with the provisions of this Act are hereby repealed or amended accordingly."}},{"id":"PH-H5807-A6","no":6,"noLabel":{"en":"Section 6."},"text":{"en":"This Act shall take effect upon its approval."}}],"pack":"ph-p82","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Establishing the College of Agriculture in Barangay Poctoy, Municipality of Torrijos; the College of Fisheries in Barangay Pinggan, Municipality of Gasan; and the Marinduque Community College in the Municipality of Sta. Cruz, All in the Province of Marinduque, as Branches of the Marinduque State College, Boac, Marinduque","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H5808"] = {"id":"PH-H5808","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1992/ra_7320_1992.html","fetchedAt":"2026-10-06","articleCount":3,"structureMode":"ARTICLE","title":{"zh":"设立Carles市","en":"An Act Converting the Rural Health Unit in the Municipality of Carles, Province of Iloilo, Into a Five-bed Capacity Health Infirmary, to Be Known as the Carles Health Infirmary, and Appropriating Funds Therefor","orig":"An Act Converting the Rural Health Unit in the Municipality of Carles, Province of Iloilo, Into a Five-bed Capacity Health Infirmary, to Be Known as the Carles Health Infirmary, and Appropriating Funds Therefor"},"level":"law","status":"active","topics":["health"],"docNumber":"Republic Act No. 7320","issuingBody":"Congress of the Philippines","promulgatedDate":"1992-03-30","completenessNote":"全文，共 3 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1992/ra_7320_1992.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H5808-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The rural health unit in the Municipality of Carles, Province of Iloilo, is hereby converted into a five-bed capacity health infirmary, to be known as the Carles Health Infirmary."}},{"id":"PH-H5808-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The amount necessary to carry out the provisions of this Act shall be included in the General Appropriations Act of the year following its enactment into law and thereafter."}},{"id":"PH-H5808-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"This Act shall take effect upon its approval."}}],"pack":"ph-p82"};
  FT["PH-H5809"] = {"id":"PH-H5809","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1992/ra_7321_1992.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":"将莱特省希隆戈斯市镇希隆戈斯医院的名称变更为Emiliano Melgazo纪念医院的法案","en":"An Act Changing the Name of the Hilongos Hospital in the Municipality of Hilongos, Province of Leyte, to Emiliano Melgazo Memorial Hospital","orig":"An Act Changing the Name of the Hilongos Hospital in the Municipality of Hilongos, Province of Leyte, to Emiliano Melgazo Memorial Hospital"},"level":"law","status":"active","topics":["health"],"docNumber":"Republic Act No. 7321","issuingBody":"Congress of the Philippines","promulgatedDate":"1992-03-30","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1992/ra_7321_1992.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H5809-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The name of the Hilongos Hospital in the Municipality of Hilongos, Province of Leyte, is hereby changed to Emiliano Melgazo Memorial Hospital."}},{"id":"PH-H5809-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect upon its approval."}}],"pack":"ph-p82","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Changing the Name of the Hilongos Hospital in the Municipality of Hilongos, Province of Leyte, to Emiliano Melgazo Memorial Hospital","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H5810"] = {"id":"PH-H5810","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1992/ra_7322_1992.html","fetchedAt":"2026-10-06","articleCount":4,"structureMode":"ARTICLE","title":{"zh":"提高私营部门女工的产假福利，为此修订经修正的第1161号共和国法第14-a条并为其他目的法案","en":"An Act Increasing Maternity Benefits in Favor of Women Workers in the Private Sector, Amending for the Purpose Section 14-a of Republic Act No. 1161, as Amended, and for Other Purposes","orig":"An Act Increasing Maternity Benefits in Favor of Women Workers in the Private Sector, Amending for the Purpose Section 14-a of Republic Act No. 1161, as Amended, and for Other Purposes"},"level":"law","status":"active","topics":["labor","civil"],"docNumber":"Republic Act No. 7322","issuingBody":"Congress of the Philippines","promulgatedDate":"1992-03-30","completenessNote":"全文，共 4 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1992/ra_7322_1992.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H5810-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Section 14-A of Republic Act No. 1161, as amended, is further amended to read as follows:\n\"Section 14-A. Maternity Leave Benefit. - A covered female employee who has paid at least three monthly maternity contributions in the twelve-month period preceding the semester of her childbirth, abortion or miscarriage and who is currently employed shall be paid a daily maternity benefit equivalent to one hundred percent (100%) of her present basic salary, allowances and other benefits or the cash equivalents of such benefits for sixty (60) days subject to the following conditions:\n\"(a) That the employee shall have notified her employer of her pregnancy and the probable date of her childbirth which notice shall be transmitted to the SSS in accordance with the rules and regulations it may provide;\n\"(b) That the payment shall be advanced by the employer in two equal installments within thirty (30) days from the filing of the maternity leave application;\n\"(c) That in case of caesarian delivery, the employee shall be paid the daily maternity benefit for seventy-eight (78) days;\n\"(d) That payment of daily maternity benefits shall be a bar to the recovery of sickness benefits provided by this Act for the same compensable period of sixty (60) days for the same childbirth, abortion, or miscarriage;\n\"(e) That the maternity benefits provided under this Section shall be paid only for the first four deliveries after March 13, 1973;\n\"(f) That the SSS shall immediately reimburse the employer of one hundred percent (100%) of the amount of maternity benefits advanced to the employee by the employer upon receipt of satisfactory proof of such payment and legality thereof; and \"(g) That if an employee should give birth or suffer abortion or miscarriage without the required contributions having been remitted for her by her employer to the SSS, or without the latter having been previously notified by the employer of the time of the pregnancy, the employer shall pay to the SSS damages equivalent to the benefits which said employee would otherwise have been entitled to, and the SSS shall in turn pay such amount to the employee concerned.\""}},{"id":"PH-H5810-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"Nothing in this Act shall be construed as to diminish existing maternity benefits under present laws and collective bargaining agreements."}},{"id":"PH-H5810-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"All laws, executive orders, proclamations, presidential decrees, rules and regulations, and other issuances, or parts thereof, inconsistent with the provisions of this Act are hereby repealed or modified accordingly."}},{"id":"PH-H5810-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"This Act shall take effect fifteen (15) days after its publication in the Official Gazette or in at least two (2) national newspapers of general circulation, whichever comes earlier."}}],"pack":"ph-p82","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Increasing Maternity Benefits in Favor of Women Workers in the Private Sector, Amending for the Purpose Section 14-a of Republic Act No. 1161, as Amended, and for Other Purposes","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H5811"] = {"id":"PH-H5811","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1992/ra_7323_1992.html","fetchedAt":"2026-10-06","articleCount":6,"structureMode":"ARTICLE","title":{"zh":"通过给予雇主激励，帮助贫困但优秀的学生在暑假及/或圣诞假期就业以继续学业，雇主仅支付其薪金六成、其余四成由政府以教育券支付，并处罚虚假索赔","en":"An Act to Help Poor But Deserving Students Pursue Their Education By Encouraging Their Employment During Summer And/Or Christmas Vacations, Through Incentives Granted to Employers, Allowing Them to Pay Only Sixty Per Centum of Their Salaries or Wages and the Forty Per Centum Through Education Vouchers to Be Paid By the Government, Prohibiting and Penalizing the Filing of Fraudulent or Fictitious Claims, and for Other Purposes","orig":"An Act to Help Poor But Deserving Students Pursue Their Education By Encouraging Their Employment During Summer And/Or Christmas Vacations, Through Incentives Granted to Employers, Allowing Them to Pay Only Sixty Per Centum of Their Salaries or Wages and the Forty Per Centum Through Education Vouchers to Be Paid By the Government, Prohibiting and Penalizing the Filing of Fraudulent or Fictitious Claims, and for Other Purposes"},"level":"law","status":"active","topics":["labor","criminal","education"],"docNumber":"Republic Act No. 7323","issuingBody":"Congress of the Philippines","promulgatedDate":"1992-03-30","completenessNote":"全文，共 6 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1992/ra_7323_1992.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H5811-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Any provision of law to the contrary notwithstanding, any person or entity employing at least fifty (50) persons may during the summer and/or Christmas vacations employ poor but deserving students fifteen (15) years of age but not more than twenty-five (25) years old, paying them a salary or wage not lower than the minimum wage provided by law and other applicable labor rules and regulations.\nFor purposes of this Act, poor but deserving students refer to those whose parents' combined incomes, together with their income, if any, do not exceed Thirty-six thousand pesos (P36,000) per annum. Employment should be at the Labor Exchange Center of the Department of Labor and Employment (DOLE)."}},{"id":"PH-H5811-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"Sixty per centum (60%) of said salary or wage shall be paid by the employer in cash and forty per centum (40%) by the Government in the form of a voucher which shall be applicable in the payment for his tuition fees and books in any educational institution for secondary, tertiary, vocational or technological education. The amount of the education voucher shall be paid by the Government to the educational institution concerned within thirty (30) days from its presentation to the officer or agency designated by the Secretary of Finance.\nThe voucher shall not be transferable except when the payee thereof dies or for a justifiable cause stops in his duties in which case it can be transferred to his brothers or sisters. If there be none, the amount thereof shall be paid his heirs or to the payee himself, as the case may be."}},{"id":"PH-H5811-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"The Secretary of Labor and Employment, the Secretary of Education, Culture and Sports and the Secretary of Finance shall issue the corresponding rules and regulations to carry out the purposes of this Act.\nThe Secretary of Labor and Employment shall be the Project Director of this program."}},{"id":"PH-H5811-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"Any person or entity who shall make any fraudulent or fictitious claim under this Act, regardless of whether payment has been made, shall upon conviction be punished with imprisonment of not less than six (6) months and not more than one (1) year and a fine of not less than Ten thousand pesos (P10,000), without prejudice to their prosecution and punishment for any other offense punishable under the Revised Penal Code or any other penal statute.\nIn case of partnerships or corporations, the managing partner, general manager, or chief executive officer, as the case may be, shall be criminally liable."}},{"id":"PH-H5811-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"The amount necessary to carry out the purposes of this Act is hereby authorized to be appropriated in the General Appropriations Act for 1992 and the subsequent annual general appropriations acts."}},{"id":"PH-H5811-A6","no":6,"noLabel":{"en":"Section 6."},"text":{"en":"This Act shall take effect after its publication in the Official Gazette or in at least two (2) national newspapers of general circulation."}}],"pack":"ph-p82","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act to Help Poor But Deserving Students Pursue Their Education By Encouraging Their Employment During Summer And/Or Christmas Vacations, Through Incentives Granted to Employers, Allowing Them to Pay Only Sixty Per Centum of Their Salaries or Wages and the Forty Per Centum Through Education Vouchers to Be Paid By the Government, Prohibiting and Penalizing the Filing of Fraudulent or Fictitious Claims, and for Other Purposes","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H5812"] = {"id":"PH-H5812","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1992/ra_7324_1992.html","fetchedAt":"2026-10-06","articleCount":5,"structureMode":"ARTICLE","title":{"zh":"增加菲律宾赛马委员会成员人数，为此修订经修正的第 420 号总统法令的法案","en":"An Act Increasing the Members of the Board of the Philippine Racing Commission, Amending for the Purpose Presidential Decree Numbered Four Hundred Twenty, as Amended","orig":"An Act Increasing the Members of the Board of the Philippine Racing Commission, Amending for the Purpose Presidential Decree Numbered Four Hundred Twenty, as Amended"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 7324","issuingBody":"Congress of the Philippines","promulgatedDate":"1992-03-30","completenessNote":"全文，共 5 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1992/ra_7324_1992.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。 源文条号不连续（自第 1 条起，止于第 6 条，缺 5）：经逐条比对原始页面，该处原文没有对应的 “Section N.” 抬头行，系来源页自身的编号跳跃或条文以“续段”形式并入前条，非抽取遗漏，故未擅自补号。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H5812-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Section four of Presidential Decree Numbered Four hundred twenty is amended to read as follows:\n\""}},{"id":"PH-H5812-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"Membership of the Commission. - The Commission shall be composed of a chairman and six (6) members: Provided, That of the (6) members, there shall be one (1) representative of the Racehorse Owners Association, one (1) representative of the Jockeys Association and one (1) representative of the Trainers Association. The Commissioners shall be appointed by the President of the Philippines.\""}},{"id":"PH-H5812-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"Section six of the same decree is hereby amended to read as follows:\n\""}},{"id":"PH-H5812-A6","no":6,"noLabel":{"en":"Section 6."},"text":{"en":"Meetings and Quorum. - The Commissioners shall meet regularly once a week and as often as the exigencies of the service may demand, upon the call of the Chairman or upon the request of three (3) members of the Commission. The vote of at least four (4) members shall be necessary for the adoption of any rule, resolution or decision of the Commission.\""}},{"id":"PH-H5812-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"This Act shall take effect upon its approval."}}],"pack":"ph-p82","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Increasing the Members of the Board of the Philippine Racing Commission, Amending for the Purpose Presidential Decree Numbered Four Hundred Twenty, as Amended","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H5813"] = {"id":"PH-H5813","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1992/ra_7325_1992.html","fetchedAt":"2026-10-06","articleCount":5,"structureMode":"ARTICLE","title":{"zh":"规定甲米地省 Trece Martires 市市官员地方选举并为其他目的法案","en":"An Act Providing for the Local Elections of the City Officials of Trece Martires City, Province of Cavite, and for Other Purposes","orig":"An Act Providing for the Local Elections of the City Officials of Trece Martires City, Province of Cavite, and for Other Purposes"},"level":"law","status":"active","topics":["administrative"],"docNumber":"Republic Act No. 7325","issuingBody":"Congress of the Philippines","promulgatedDate":"1992-03-31","completenessNote":"全文，共 5 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1992/ra_7325_1992.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H5813-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Elective Officials of the City Government of Trece Martires City, Province of Cavite. - The following officials of the city government shall be elected at large by qualified voters of the city:\na. The mayor;\nb. The vice-mayor;\nc. The regular members of the sangguniang panlungsod; and\nd. Such other officials as may be provided by law."}},{"id":"PH-H5813-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"Date of Election. - Unless otherwise provided by law, the elections for the city officials shall be held simultaneously with the local elections in 1992."}},{"id":"PH-H5813-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"Transitory Provision. - Pending election of the officials of the city government during the regular local elections, the mayor, vice-mayor, and the members of the sangguniang panlungsod shall be appointed by the provincial governor of the Province of Cavite."}},{"id":"PH-H5813-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"Repealing Clause . - The provisions of Republic Act No. 981 which are inconsistent with the provisions of this Act and Republic Act No. 7160, otherwise known as the Local Government Code of 1991, are hereby repealed, modified or amended accordingly."}},{"id":"PH-H5813-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"Effectivity Clause. - This Act shall take effect upon its approval."}}],"pack":"ph-p82","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Providing for the Local Elections of the City Officials of Trece Martires City, Province of Cavite, and for Other Purposes","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H5814"] = {"id":"PH-H5814","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1992/ra_7326_1992.html","fetchedAt":"2026-10-06","articleCount":3,"structureMode":"ARTICLE","title":{"zh":"废止第6145号与第5474号共和国法（关于禁止在某些月份捕捞“Ipon”鱼等）","en":"An Act Repealing Republic Acts Numbered Sixty-one Hundred Forty-five and Fifty-four Hundred Seventy-four (Re: Prohibition to Catch Fish Called \"Ipon\" During Certain Months of the Year, Etc.)","orig":"An Act Repealing Republic Acts Numbered Sixty-one Hundred Forty-five and Fifty-four Hundred Seventy-four (Re: Prohibition to Catch Fish Called \"Ipon\" During Certain Months of the Year, Etc.)"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 7326","issuingBody":"Congress of the Philippines","promulgatedDate":"1992-03-31","completenessNote":"全文，共 3 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1992/ra_7326_1992.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H5814-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Republic Acts Numbered Sixty-one hundred forty-five and Fifty-four hundred seventy-four are hereby repealed by this Act."}},{"id":"PH-H5814-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"All provisions of existing laws, orders, decrees, rules and regulations inconsistent herewith are likewise repealed."}},{"id":"PH-H5814-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"This Act shall take effect upon its approval."}}],"pack":"ph-p82","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Repealing Republic Acts Numbered Sixty-one Hundred Forty-five and Fifty-four Hundred Seventy-four (Re: Prohibition to Catch Fish Called \"Ipon\" During Certain Months of the Year, Etc.)","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H5815"] = {"id":"PH-H5815","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1992/ra_7327_1992.html","fetchedAt":"2026-10-06","articleCount":3,"structureMode":"ARTICLE","title":{"zh":"将东米萨米斯省Balingasag市镇Balingasag医疗社区医院床位由15张增至25张并为此拨款的法案","en":"An Act Increasing the Bed Capacity of the Balingasag Medicare Community Hospital in the Municipality of Balingasag, Province of Misamis Oriental, From Fifteen (15) to Twenty-five (25) Beds, and Appropriating Funds Therefor","orig":"An Act Increasing the Bed Capacity of the Balingasag Medicare Community Hospital in the Municipality of Balingasag, Province of Misamis Oriental, From Fifteen (15) to Twenty-five (25) Beds, and Appropriating Funds Therefor"},"level":"law","status":"active","topics":["health"],"docNumber":"Republic Act No. 7327","issuingBody":"Congress of the Philippines","promulgatedDate":"1992-03-31","completenessNote":"全文，共 3 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1992/ra_7327_1992.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H5815-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The bed capacity of the Balingasag Medicare Community Hospital in the Municipality of Balingasag, Province of Misamis Oriental, is hereby increased from fifteen (15) to twenty-five (25) beds."}},{"id":"PH-H5815-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The amount necessary to carry out the provisions of this Act shall be charged against the lump-sum appropriations authorized for the purpose under the current General Appropriations Act. Thereafter, such sums as may be necessary for the operation and maintenance of the hospital shall be included in the annual General Appropriations Act."}},{"id":"PH-H5815-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"This Act shall take effect upon its approval."}}],"pack":"ph-p82","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Increasing the Bed Capacity of the Balingasag Medicare Community Hospital in the Municipality of Balingasag, Province of Misamis Oriental, From Fifteen (15) to Twenty-five (25) Beds, and Appropriating Funds Therefor","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H5816"] = {"id":"PH-H5816","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1992/ra_7328_1992.html","fetchedAt":"2026-10-06","articleCount":4,"structureMode":"ARTICLE","title":{"zh":"将西内格罗斯省Valladolid市镇Valladolid区医院床位由二十五（25）张增至五十（50）张并为此拨款的法案","en":"An Act Increasing the Bed Capacity of the Valladolid District Hospital in the Municipality of Valladolid, Province of Negros Occidental, From Twenty-five (25) to Fifty (50) Beds, and Appropriating Funds Therefor","orig":"An Act Increasing the Bed Capacity of the Valladolid District Hospital in the Municipality of Valladolid, Province of Negros Occidental, From Twenty-five (25) to Fifty (50) Beds, and Appropriating Funds Therefor"},"level":"law","status":"active","topics":["health"],"docNumber":"Republic Act No. 7328","issuingBody":"Congress of the Philippines","promulgatedDate":"1992-03-31","completenessNote":"全文，共 4 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1992/ra_7328_1992.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H5816-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The bed capacity of the Valladolid District Hospital in the Municipality of Valladolid, Province of Negros Occidental, is hereby increased from twenty-five (25) to fifty (50) beds."}},{"id":"PH-H5816-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"Upon approval of this Act, said existing Valladolid Emergency Hospital shall be called and publicly known as the Valladolid District Hospital."}},{"id":"PH-H5816-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"The amount necessary to carry out the provisions of this Act shall be charged against the lump-sum appropriations authorized for the purpose under the current General Appropriations Act. Thereafter, such sums as may be necessary for the operation and maintenance of the hospital shall be included in the annual General Appropriations Act."}},{"id":"PH-H5816-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"This Act shall take effect upon its approval."}}],"pack":"ph-p82","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Increasing the Bed Capacity of the Valladolid District Hospital in the Municipality of Valladolid, Province of Negros Occidental, From Twenty-five (25) to Fifty (50) Beds, and Appropriating Funds Therefor","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H5817"] = {"id":"PH-H5817","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1992/ra_7329_1992.html","fetchedAt":"2026-10-06","articleCount":3,"structureMode":"ARTICLE","title":{"zh":"设立Don Victoriano市","en":"An Act Converting the Rural Health Unit in the Municipality of Don Victoriano, Province of Misamis Occidental, Into a Five-bed Capacity Health Infirmary, to Be Known as the Don Victoriano Health Infirmary, and Appropriating Funds Therefor","orig":"An Act Converting the Rural Health Unit in the Municipality of Don Victoriano, Province of Misamis Occidental, Into a Five-bed Capacity Health Infirmary, to Be Known as the Don Victoriano Health Infirmary, and Appropriating Funds Therefor"},"level":"law","status":"active","topics":["health"],"docNumber":"Republic Act No. 7329","issuingBody":"Congress of the Philippines","promulgatedDate":"1992-03-31","completenessNote":"全文，共 3 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1992/ra_7329_1992.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H5817-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The rural health unit in the Municipality of Don Victoriano, Province of Misamis Occidental, is hereby converted into a five-bed capacity health infirmary, to be known as the Don Victoriano Health Infirmary."}},{"id":"PH-H5817-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The amount necessary to carry out the provisions of this Act shall be included in the General Appropriations Act of the year following its enactment into law and thereafter."}},{"id":"PH-H5817-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"This Act shall take effect upon its approval."}}],"pack":"ph-p82"};
  FT["PH-H5818"] = {"id":"PH-H5818","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1992/ra_7330_1992.html","fetchedAt":"2026-10-06","articleCount":3,"structureMode":"ARTICLE","title":{"zh":"规定在宿务市Basak设立南方群岛医疗中心25张床位的延伸分院并为此拨款的法案","en":"An Act Providing for An Extension Branch With a Twenty-five-bed Capacity of the Southern Islands Medical Center in Basak, City of Cebu, and Appropriating Funds Therefor","orig":"An Act Providing for An Extension Branch With a Twenty-five-bed Capacity of the Southern Islands Medical Center in Basak, City of Cebu, and Appropriating Funds Therefor"},"level":"law","status":"active","topics":["health"],"docNumber":"Republic Act No. 7330","issuingBody":"Congress of the Philippines","promulgatedDate":"1992-03-31","completenessNote":"全文，共 3 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1992/ra_7330_1992.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H5818-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"An extension branch with a twenty-five-bed capacity of the Southern Islands Medical Center is hereby established in Basak, City of Cebu."}},{"id":"PH-H5818-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The amount necessary to carry out the provisions of this Act shall be charged against the appropriations authorized for the purpose under the current General Appropriations Act. Thereafter, such sums as may be necessary for the operation and maintenance of the hospital shall be included in the annual General Appropriations Act."}},{"id":"PH-H5818-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"This Act shall take effect upon its approval."}}],"pack":"ph-p82","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Providing for An Extension Branch With a Twenty-five-bed Capacity of the Southern Islands Medical Center in Basak, City of Cebu, and Appropriating Funds Therefor","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H5819"] = {"id":"PH-H5819","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1992/ra_7331_1992.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":"将布拉干省圣玛丽亚市镇菲律宾国立农业学校的名称变更为Fortunato F. Halili国立农业学校的法案","en":"An Act Changing the Name of the Philippine National Agricultural School in the Municipality of Sta. Maria, Bulacan, to Fortunato F. Halili National Agricultural School","orig":"An Act Changing the Name of the Philippine National Agricultural School in the Municipality of Sta. Maria, Bulacan, to Fortunato F. Halili National Agricultural School"},"level":"law","status":"active","topics":["education","environment"],"docNumber":"Republic Act No. 7331","issuingBody":"Congress of the Philippines","promulgatedDate":"1992-03-31","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1992/ra_7331_1992.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H5819-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The name of the Philippine National Agricultural School in Ouyong, Sta. Maria, Bulacan, is hereby changed to Fortunato F. Halili National Agricultural School."}},{"id":"PH-H5819-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect upon its approval."}}],"pack":"ph-p82","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Changing the Name of the Philippine National Agricultural School in the Municipality of Sta. Maria, Bulacan, to Fortunato F. Halili National Agricultural School","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H5820"] = {"id":"PH-H5820","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1992/ra_7332_1992.html","fetchedAt":"2026-10-06","articleCount":4,"structureMode":"ARTICLE","title":{"zh":"设立San Rafael市","en":"An Act Converting the Rural Health Unit in the Municipality of San Rafael, Province of Iloilo, Into a Five-bed Capacity Health Infirmary, to Be Known as the San Rafael Health Infirmary, and Appropriating Funds Therefor","orig":"An Act Converting the Rural Health Unit in the Municipality of San Rafael, Province of Iloilo, Into a Five-bed Capacity Health Infirmary, to Be Known as the San Rafael Health Infirmary, and Appropriating Funds Therefor"},"level":"law","status":"active","topics":["health"],"docNumber":"Republic Act No. 7332","issuingBody":"Congress of the Philippines","promulgatedDate":"1992-03-31","completenessNote":"全文，共 4 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1992/ra_7332_1992.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H5820-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The rural health unit in the Municipality of San Rafael, Province of Iloilo, is hereby converted into a five-bed capacity health infirmary, to be known as the San Rafael Health Infirmary."}},{"id":"PH-H5820-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The Secretary of the Department of Health shall determine the manner by which said hospital shall be operational."}},{"id":"PH-H5820-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"The amount necessary to carry out the provisions of this Act shall be included in the General Appropriations Act of the year following its enactment into law and thereafter."}},{"id":"PH-H5820-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"This Act shall take effect upon its approval."}}],"pack":"ph-p82"};
  FT["PH-H5821"] = {"id":"PH-H5821","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1992/ra_7333_1992.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":"将莱特省阿布约格市镇阿布约格综合医院的名称变更为Octavio Traya，Sr.，纪念医院的法案","en":"An Act Changing the Name of the Abuyog General Hospital in the Municipality of Abuyog, Province of Leyte, to Octavio Traya, Sr., Memorial Hospital","orig":"An Act Changing the Name of the Abuyog General Hospital in the Municipality of Abuyog, Province of Leyte, to Octavio Traya, Sr., Memorial Hospital"},"level":"law","status":"active","topics":["health"],"docNumber":"Republic Act No. 7333","issuingBody":"Congress of the Philippines","promulgatedDate":"1992-03-31","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1992/ra_7333_1992.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H5821-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The name of the Abuyog General Hospital in the Municipality of Abuyog, Province of Leyte, is hereby changed to Octavio Traya, Sr., Memorial Hospital."}},{"id":"PH-H5821-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect upon its approval."}}],"pack":"ph-p82","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Changing the Name of the Abuyog General Hospital in the Municipality of Abuyog, Province of Leyte, to Octavio Traya, Sr., Memorial Hospital","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H5822"] = {"id":"PH-H5822","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1992/ra_7334_1992.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":"将西内格罗斯省 伊莎贝拉市镇伊莎贝拉区医院的名称变更为Don Gil Montilla 纪念医院的法案","en":"An Act Changing the Name of the Isabela District Hospital in the Municipality of Isabela, Province of Negros Occidental, to Don Gil Montilla Memorial Hospital","orig":"An Act Changing the Name of the Isabela District Hospital in the Municipality of Isabela, Province of Negros Occidental, to Don Gil Montilla Memorial Hospital"},"level":"law","status":"active","topics":["health"],"docNumber":"Republic Act No. 7334","issuingBody":"Congress of the Philippines","promulgatedDate":"1992-03-31","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1992/ra_7334_1992.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H5822-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The name of the Isabela District Hospital in the Municipality of Isabela, Province of Negros Occidental, is hereby changed to Don Gil Montilla Memorial Hospital."}},{"id":"PH-H5822-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect upon its approval."}}],"pack":"ph-p82","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Changing the Name of the Isabela District Hospital in the Municipality of Isabela, Province of Negros Occidental, to Don Gil Montilla Memorial Hospital","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H5823"] = {"id":"PH-H5823","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1992/ra_7335_1992.html","fetchedAt":"2026-10-06","articleCount":4,"structureMode":"ARTICLE","title":{"zh":"设立Tacurong市","en":"An Act Establishing a High School in the Municipality of Tacurong, Province of Sultan Kudarat, to Be Known as the Tacurong High School, and Appropriating Funds Therefor","orig":"An Act Establishing a High School in the Municipality of Tacurong, Province of Sultan Kudarat, to Be Known as the Tacurong High School, and Appropriating Funds Therefor"},"level":"law","status":"active","topics":["education"],"docNumber":"Republic Act No. 7335","issuingBody":"Congress of the Philippines","promulgatedDate":"1992-04-01","completenessNote":"全文，共 4 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1992/ra_7335_1992.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H5823-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"There shall be established a high school in the Municipality of Tacurong, Province of Sultan Kudarat, to be known as the Tacurong High School."}},{"id":"PH-H5823-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The Secretary of the Department of Education, Culture and Sports shall issue such rules and regulations as may be necessary to carry out the purpose of this Act."}},{"id":"PH-H5823-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"The amount needed to carry out the provisions of this Act is hereby authorized to be appropriated in the General Appropriations Act of the year following its enactment into law and thereafter."}},{"id":"PH-H5823-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"This Act shall take effect upon its approval."}}],"pack":"ph-p82"};
  FT["PH-H5824"] = {"id":"PH-H5824","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1992/ra_7336_1992.html","fetchedAt":"2026-10-06","articleCount":14,"structureMode":"ARTICLE","title":{"zh":"设立Iba市","en":"An Act Converting the Ramon Magsaysay Memorial School of Arts and Trades in the Municipality of Iba, Province of Zambales, Into a Polytechnic College to Be Known as the Ramon Magsaysay Polytechnic College, and Appropriating Funds Therefor","orig":"An Act Converting the Ramon Magsaysay Memorial School of Arts and Trades in the Municipality of Iba, Province of Zambales, Into a Polytechnic College to Be Known as the Ramon Magsaysay Polytechnic College, and Appropriating Funds Therefor"},"level":"law","status":"active","topics":["education","culture"],"docNumber":"Republic Act No. 7336","issuingBody":"Congress of the Philippines","promulgatedDate":"1992-04-01","completenessNote":"全文，共 14 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1992/ra_7336_1992.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H5824-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The Ramon Magsaysay Memorial School of Arts and Trades in the Municipality of Iba, Province of Zambales, is hereby converted into a polytechnic college to be known as the Ramon Magsaysay Polytechnic College, hereinafter referred to as the College."}},{"id":"PH-H5824-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The College shall be under the supervision and control of the Department of Education, Culture and Sports."}},{"id":"PH-H5824-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"The College shall offer one-year to three-year technical vocational courses and undergraduate courses in the field of industrial education and technology or such other courses which are relevant to the needs of its service area."}},{"id":"PH-H5824-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"The College shall be headed by a vocational college superintendent to be appointed by the Secretary of Education, Culture and Sports."}},{"id":"PH-H5824-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"The academic and administrative staff of the College shall be organized following the staffing pattern of the Department of Education, Culture and Sports for such type of schools pursuant to existing laws, rules and regulations."}},{"id":"PH-H5824-A6","no":6,"noLabel":{"en":"Section 6."},"text":{"en":"All assets, fixed and movable, personnel, records and documents of the Ramon Magsaysay Memorial School of Arts and Trades in the Municipality of Iba, Province of Zambales, as well as its liabilities shall be transferred to the Ramon Magsaysay Polytechnic College: Provided, however, That the positions, rights and security of tenure of personnel therein employed pursuant to the existing laws prior to its conversion into the Ramon Magsaysay Polytechnic College are not impaired."}},{"id":"PH-H5824-A7","no":7,"noLabel":{"en":"Section 7."},"text":{"en":"All parcels of land belonging to the Government occupied by the Ramon Magsaysay Memorial School of Arts and Trades are hereby declared to be the property of the Ramon Magsaysay Polytechnic College and shall be titled under that name: Provided, That should the Ramon Magsaysay Polytechnic College cease to exist or such aforementioned parcels of land be no longer needed by the College, the same shall revert to the Province of Zambales."}},{"id":"PH-H5824-A8","no":8,"noLabel":{"en":"Section 8."},"text":{"en":"In addition to the current appropriations of the Ramon Magsaysay Memorial School of Arts and Trades, the amount needed to carry out the provisions of this Act shall be included in the General Appropriations Act of the year following its enactment into law and thereafter."}},{"id":"PH-H5824-A9","no":9,"noLabel":{"en":"Section 9."},"text":{"en":"Tuition and other fees to be paid by students enrolled in post-secondary and higher education courses shall be retained and directly used by the College to improve the learning/training facilities."}},{"id":"PH-H5824-A10","no":10,"noLabel":{"en":"Section 10."},"text":{"en":"Income derived from production and service activities undertaken in aid of instruction and training and from auxiliary enterprises shall be retained by the College and shall be used exclusively for the acquisition of tools, equipment and other laboratory facilities for instruction, research and produce/process development and for incentives of students, teachers and other school personnel directly involved in production and service activities: Provided, however, That such incentives shall not exceed thirty percent (30%) of the income: Provided, further, That the utilization of this income shall be in accordance with auditing rules and regulations."}},{"id":"PH-H5824-A11","no":11,"noLabel":{"en":"Section 11."},"text":{"en":"Salary grades of faculty members, officials and other employees of the College shall be equal to that of their counterparts in state colleges and universities pursuant to the provisions of Republic Act Numbered Sixty-seven hundred and fifty-eight."}},{"id":"PH-H5824-A12","no":12,"noLabel":{"en":"Section 12."},"text":{"en":"If for any reason any section or provision of this Act shall be held unconstitutional or invalid, no other section or provision hereof shall be affected thereby."}},{"id":"PH-H5824-A13","no":13,"noLabel":{"en":"Section 13."},"text":{"en":"All laws, presidential decrees, executive orders, rules and regulations inconsistent with the provisions of this Act are hereby repealed, amended or modified accordingly."}},{"id":"PH-H5824-A14","no":14,"noLabel":{"en":"Section 14."},"text":{"en":"This Act shall take effect upon its approval."}}],"pack":"ph-p82"};
  FT["PH-H5825"] = {"id":"PH-H5825","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1992/ra_7337_1992.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":"授权莱特省 Tolosa 的 Daniel Z. Romualdez 渔业学校继续开设渔业理学士课程的法案","en":"An Act Authorizing the Daniel Z. Romualdez Memorial School of Fisheries in Tolosa, Leyte, to Continue to Offer the Bachelor of Science in Fisheries Program","orig":"An Act Authorizing the Daniel Z. Romualdez Memorial School of Fisheries in Tolosa, Leyte, to Continue to Offer the Bachelor of Science in Fisheries Program"},"level":"law","status":"active","topics":["environment","education"],"docNumber":"Republic Act No. 7337","issuingBody":"Congress of the Philippines","promulgatedDate":"1992-04-01","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1992/ra_7337_1992.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H5825-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The Daniel Z. Romualdez Memorial School of Fisheries in Tolosa, Leyte, is hereby authorized to continue to offer the Bachelor of Science in Fisheries Program."}},{"id":"PH-H5825-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect upon its approval."}}],"pack":"ph-p82","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Authorizing the Daniel Z. Romualdez Memorial School of Fisheries in Tolosa, Leyte, to Continue to Offer the Bachelor of Science in Fisheries Program","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
